INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (22392, 1, 'prompt1_core', '{"pos": "形容词", "semantic_class": "property", "definition": "做事情不费力，心里不紧张。", "primary_collocate": null, "pronunciation": "qīng sōng", "ipa": "tɕʰiŋ˥ sʊŋ˥", "syllable_count": 2, "sentences": [{"text": "这道题很简单，他轻松地做完了。", "target_word": "轻松", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "她轻松地提起了那个大箱子。", "target_word": "轻松", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "比赛中，我们轻松赢了对手。", "target_word": "轻松", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "这个游戏很容易，小孩子也能轻松学会。", "target_word": "轻松", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "有了这个新软件，我们可以轻松完成工作。", "target_word": "轻松", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "老师说这次考试很轻松，不用担心。", "target_word": "轻松", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "他跑得很快，轻松拿到了第一名。", "target_word": "轻松", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "她走上台，轻松地说了几句话。", "target_word": "轻松", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "这个问题不难，你可以轻松回答。", "target_word": "轻松", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "他每天锻炼，所以爬山也很轻松。", "target_word": "轻松", "complexity_tier": "T2", "sentence_source": "generated"}], "morphological_forms": [{"form": "轻轻松松", "label": "重叠"}, {"form": "轻松愉快", "label": "复合"}, {"form": "輕鬆", "label": "繁体"}], "register": "中性", "sense_fingerprint": "做事轻易、不费力气，态度从容不紧张", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '943f29bc-1364-4bfc-ba32-b020f53aa631') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (22392, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "轻松", "is_correct": true, "explanation": "正确：“他轻松地做完了”表示做事不费力，符合“这道题很简单”的语境。"}, {"text": "巨大", "is_correct": false, "explanation": "搭配：“巨大地做完”不成立，“巨大”不能修饰“做”。"}, {"text": "浑浊", "is_correct": false, "explanation": "语义：“浑浊”说水或空气不清，与做题的语境无关。"}, {"text": "漆黑", "is_correct": false, "explanation": "语义：“漆黑”说颜色或光线，与“做完了”不相干。"}], "explanations": {"轻松": "正确：“他轻松地做完了”表示做事不费力，符合“这道题很简单”的语境。", "巨大": "搭配：“巨大地做完”不成立，“巨大”不能修饰“做”。", "浑浊": "语义：“浑浊”说水或空气不清，与做题的语境无关。", "漆黑": "语义：“漆黑”说颜色或光线，与“做完了”不相干。"}, "sentence_index": 0, "correct_answer": "轻松"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "这把伞很轻松，放进包里也不占地方。", "explanation": "这里应该用〈轻巧〉。轻巧形容物体轻便小巧，“轻松”指做事不费力，不形容伞的重量。"}, {"text": "他做人很认真，从不轻松许诺。", "explanation": "这里应该用〈轻易〉。“轻易许诺”指随便答应，“轻松许诺”不成立。"}, {"text": "他只受了轻松的伤，休息几天就好了。", "explanation": "这里应该用〈轻微〉。轻微形容伤势轻，“轻松”不修饰“伤”。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '2d2a5323-8bfd-4791-8b01-9e493bbb56bb') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (22392, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "轻松", "is_correct": true, "explanation": "正确：“轻松拿到”表示不费力地拿到，与“跑得很快”的语境一致。"}, {"text": "放弃", "is_correct": false, "explanation": "语义：“放弃”与“拿到了第一名”的结果相矛盾，句子不通。"}, {"text": "丢失", "is_correct": false, "explanation": "语义：“丢失”指失去，与“拿到了第一名”相矛盾，句子不通。"}, {"text": "慢", "is_correct": false, "explanation": "搭配：“慢”修饰“拿到”不自然，且与“跑得很快”直接矛盾。"}], "explanations": {"轻松": "正确：“轻松拿到”表示不费力地拿到，与“跑得很快”的语境一致。", "放弃": "语义：“放弃”与“拿到了第一名”的结果相矛盾，句子不通。", "丢失": "语义：“丢失”指失去，与“拿到了第一名”相矛盾，句子不通。", "慢": "搭配：“慢”修饰“拿到”不自然，且与“跑得很快”直接矛盾。"}, "sentence_index": 6, "correct_answer": "轻松"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "这只小猫的身子很轻松，像一团棉花。", "explanation": "这里应该用〈轻盈〉。轻盈形容身体动作轻巧灵活，“轻松”指做事不费力，不用来形容身子。"}, {"text": "老师讲话的声音很轻松，像在哄孩子。", "explanation": "这里应该用〈轻柔〉。轻柔形容声音温和，不能用“轻松”描写声音。"}, {"text": "这碗粥的口味很轻松，清清淡淡的。", "explanation": "这里应该用〈清淡〉。清淡形容口味，不能用“轻松”形容口味。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '2d2a5323-8bfd-4791-8b01-9e493bbb56bb') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (22392, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "这次复习后，他轻松得完成了所有作业。", "corrected_sentence": "这次复习后，他轻松地完成了所有作业。", "error_description": "错误：“轻松”修饰动词时应用“地”，不能用“得”。应说“轻松地完成”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '2d2a5323-8bfd-4791-8b01-9e493bbb56bb') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (22392, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "她每天跑步，所以跑长途也比轻松。", "corrected_sentence": "她每天跑步，所以跑长途也很轻松。", "error_description": "错误：“很”被换成了“比”。“比”表示比较，需要比较的对象，“比轻松”不成立。此处应用程度副词“很”，说“也很轻松”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '2d2a5323-8bfd-4791-8b01-9e493bbb56bb') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (22396, 1, 'llm_types_A', '{"synonym_antonym_match": {"relation": "antonym", "options": [{"text": "看轻", "is_correct": true, "explanation": "与“看重”构成反义：看轻指认为某人或某事不重要。"}, {"text": "发现", "is_correct": false, "explanation": "与“看重”无反义关系，它指找到或察觉某事物。"}, {"text": "尊敬", "is_correct": false, "explanation": "与“看重”无反义关系，二者都是正面态度。"}, {"text": "推荐", "is_correct": false, "explanation": "与“看重”无反义关系，它指介绍并举荐某人或某物。"}], "correct_answer": "看轻", "explanations": {"看轻": "与“看重”构成反义：看轻指认为某人或某事不重要。", "发现": "与“看重”无反义关系，它指找到或察觉某事物。", "尊敬": "与“看重”无反义关系，二者都是正面态度。", "推荐": "与“看重”无反义关系，它指介绍并举荐某人或某物。"}, "sentence_index": 3}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '2d2a5323-8bfd-4791-8b01-9e493bbb56bb') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (22396, 1, 'llm_types_B', '{"synonym_antonym_match": {"relation": "antonym", "options": [{"text": "轻视", "is_correct": true, "explanation": "与“看重”构成反义：轻视指认为不重要、不当回事。"}, {"text": "欣赏", "is_correct": false, "explanation": "与“看重”无反义关系，二者都是正面评价。"}, {"text": "注意", "is_correct": false, "explanation": "与“看重”无反义关系，它表示留心、关注。"}, {"text": "照顾", "is_correct": false, "explanation": "与“看重”无反义关系，它表示照料、关照。"}], "correct_answer": "轻视", "explanations": {"轻视": "与“看重”构成反义：轻视指认为不重要、不当回事。", "欣赏": "与“看重”无反义关系，二者都是正面评价。", "注意": "与“看重”无反义关系，它表示留心、关注。", "照顾": "与“看重”无反义关系，它表示照料、关照。"}, "sentence_index": 9}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '2d2a5323-8bfd-4791-8b01-9e493bbb56bb') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (22396, 1, 'prompt1_core', '{"pos": "动词", "semantic_class": "action", "definition": "觉得一个人或东西很重要。", "primary_collocate": null, "pronunciation": "kàn zhòng", "ipa": "kʰan˥˩ ʈʂʊŋ˥˩", "syllable_count": 2, "sentences": [{"text": "老师很看重这个学生，常常帮助他。", "target_word": "看重", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "我最看重的是我们的友谊。", "target_word": "看重", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "他很看重自己的名声。", "target_word": "看重", "complexity_tier": "T1", "sentence_source": "generated"}, {"text": "经理看重小李，想让他当组长。", "target_word": "看重", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "奶奶看重这张老照片，从不让人碰。", "target_word": "看重", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "大家都看重他，因为他做事很可靠。", "target_word": "看重", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "年轻人看重自己的自由。", "target_word": "看重", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "我们公司很看重客户的意见。", "target_word": "看重", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "球队看重这位新来的队员。", "target_word": "看重", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "校长看重她的才华，让她上台发言。", "target_word": "看重", "complexity_tier": "T2", "sentence_source": "generated"}], "morphological_forms": [{"form": "看重了", "label": "体标"}, {"form": "看重过", "label": "体标"}], "register": "中性", "sense_fingerprint": "认为某个人或某样东西很重要、很有价值", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '943f29bc-1364-4bfc-ba32-b020f53aa631') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (22396, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "看重", "is_correct": true, "explanation": "正确：“老师很看重这个学生，常常帮助他”，“看重”表示认为学生重要，与“帮助他”相呼应。"}, {"text": "嫌弃", "is_correct": false, "explanation": "语义：“嫌弃”表示不喜欢，与“常常帮助他”的语境相矛盾。"}, {"text": "厌恶", "is_correct": false, "explanation": "语义：“厌恶”表示极度讨厌，与“常常帮助他”的语境完全相反。"}, {"text": "欺负", "is_correct": false, "explanation": "语义：“欺负”指欺压，与“常常帮助他”完全相反。"}], "explanations": {"看重": "正确：“老师很看重这个学生，常常帮助他”，“看重”表示认为学生重要，与“帮助他”相呼应。", "嫌弃": "语义：“嫌弃”表示不喜欢，与“常常帮助他”的语境相矛盾。", "厌恶": "语义：“厌恶”表示极度讨厌，与“常常帮助他”的语境完全相反。", "欺负": "语义：“欺负”指欺压，与“常常帮助他”完全相反。"}, "sentence_index": 0, "correct_answer": "看重"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "我们站在山顶，远远地看重了那片湖。", "explanation": "这里应该用〈眺望〉。眺望指向远处看风景，看重指认为人或事重要，不表示看景。"}, {"text": "周末我去医院看重生病的朋友。", "explanation": "这里应该用〈看望〉。看望指探望；看重不表示去探望。"}, {"text": "我抬头看重了天上的飞机。", "explanation": "这里应该用〈看见〉。看见指视觉上看到眼前的景物；看重不表示看到。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '2d2a5323-8bfd-4791-8b01-9e493bbb56bb') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (22396, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "看重", "is_correct": true, "explanation": "正确：“年轻人看重自己的自由”表示认为自由很重要。"}, {"text": "测量", "is_correct": false, "explanation": "搭配：“测量”不能与“自由”搭配。"}, {"text": "拆除", "is_correct": false, "explanation": "搭配：“拆除”指拆掉建筑，不能用于“自由”。"}, {"text": "粉刷", "is_correct": false, "explanation": "语义：“粉刷”指涂墙，与“年轻人”的语境无关。"}], "explanations": {"看重": "正确：“年轻人看重自己的自由”表示认为自由很重要。", "测量": "搭配：“测量”不能与“自由”搭配。", "拆除": "搭配：“拆除”指拆掉建筑，不能用于“自由”。", "粉刷": "语义：“粉刷”指涂墙，与“年轻人”的语境无关。"}, "sentence_index": 6, "correct_answer": "看重"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "爸妈出门了，我留在家里看重门。", "explanation": "这里应该用〈看门〉。看门指守护门户；看重指认为重要，不指守门。"}, {"text": "我留在家里看重院子，不让别人进来。", "explanation": "这里应该用〈看家〉。看家指守护家里；看重不表示守护。"}, {"text": "姐姐负责看重弟弟，每天带他去上学。", "explanation": "这里应该用〈看管〉。看管指照看孩子；看重指认为重要，不表示照看。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '2d2a5323-8bfd-4791-8b01-9e493bbb56bb') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (22396, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "老师常常看重了这个学生，帮助他。", "corrected_sentence": "老师常常看重这个学生，帮助他。", "error_description": "错误：“常常”表示经常性的动作，句中“看重”后不能接“了”。应说“常常看重这个学生”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '2d2a5323-8bfd-4791-8b01-9e493bbb56bb') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (22396, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "年轻人比看重自己的自由。", "corrected_sentence": "年轻人很看重自己的自由。", "error_description": "错误：“很”被换成了“比”。“比”表示比较，需要比较的对象，“比看重”不成立。此处应用程度副词“很”，说“很看重”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '2d2a5323-8bfd-4791-8b01-9e493bbb56bb') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
