INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (22402, 1, 'llm_types_B', '{}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '2d2a5323-8bfd-4791-8b01-9e493bbb56bb') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (22402, 1, 'prompt1_core', '{"pos": "名词", "semantic_class": "abstract", "definition": "指在一起做事情的两边人。", "primary_collocate": null, "pronunciation": "shuāng fāng", "ipa": "ʂwɑŋ˥ fɑŋ˥", "syllable_count": 2, "sentences": [{"text": "打球的双方都很累，但是没人想停。", "target_word": "双方", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "朋友吵架，双方都应该先冷静一下。", "target_word": "双方", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "这次交换学生，双方学校都很满意。", "target_word": "双方", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "请双方说说自己的看法。", "target_word": "双方", "complexity_tier": "T1", "sentence_source": "generated"}, {"text": "比赛结束后，双方一起拍了照片。", "target_word": "双方", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "房东和租客双方要先看合同。", "target_word": "双方", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "双方约好周六下午在公园见面。", "target_word": "双方", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "谈判桌的两边坐着双方的代表。", "target_word": "双方", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "做生意要让双方都得到好处。", "target_word": "双方", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "对话的双方要互相听，不要打断。", "target_word": "双方", "complexity_tier": "T2", "sentence_source": "generated"}], "morphological_forms": [], "register": "中性", "sense_fingerprint": "一起做事情的两边人", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '943f29bc-1364-4bfc-ba32-b020f53aa631') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (22402, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "双方", "is_correct": true, "explanation": "符合语境：打球的两边人都很累，但是没人想停。"}, {"text": "球拍", "is_correct": false, "explanation": "语义：球拍不会感到累，句子的主语与“累”不搭。"}, {"text": "球鞋", "is_correct": false, "explanation": "搭配：“累”多用于人，不说球鞋累。"}, {"text": "篮筐", "is_correct": false, "explanation": "语义：篮筐是物体，不会感到累。"}], "explanations": {"双方": "符合语境：打球的两边人都很累，但是没人想停。", "球拍": "语义：球拍不会感到累，句子的主语与“累”不搭。", "球鞋": "搭配：“累”多用于人，不说球鞋累。", "篮筐": "语义：篮筐是物体，不会感到累。"}, "sentence_index": 0, "correct_answer": "双方"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "全班四十人一起打扫教室，双方都很认真。", "explanation": "这里应该用〈大家〉。“双方”只指两边的人，不能用于四十人的全班。"}, {"text": "他双方握着方向盘，很用力。", "explanation": "这里应该用〈双手〉。“双方”指一起做事的两边人，不指人的身体部位，两只手要说双手。"}, {"text": "这件衣服的双方很漂亮。", "explanation": "这里应该用〈两面〉。“双方”只指做事的两边人，不指衣服的两面。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '2d2a5323-8bfd-4791-8b01-9e493bbb56bb') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (22402, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "双方", "is_correct": true, "explanation": "符合语境：指约好见面的两边人。"}, {"text": "家具", "is_correct": false, "explanation": "语义：家具不会约人见面，句子说不通。"}, {"text": "雨伞", "is_correct": false, "explanation": "搭配：“约好见面”的主语须是人，不说雨伞约好见面。"}, {"text": "月亮", "is_correct": false, "explanation": "语义：月亮不会与人约定见面。"}], "explanations": {"双方": "符合语境：指约好见面的两边人。", "家具": "语义：家具不会约人见面，句子说不通。", "雨伞": "搭配：“约好见面”的主语须是人，不说雨伞约好见面。", "月亮": "语义：月亮不会与人约定见面。"}, "sentence_index": 6, "correct_answer": "双方"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "我的双方想法很一致。", "explanation": "这里应该去掉〈双方〉，说“我的想法很一致”。“双方”指两边的人，我一个人的想法不能说双方。"}, {"text": "这两块木板的双方互相配合，缺一不可。", "explanation": "这里应该用〈两者〉。“双方”只指一起做事的两边人，不指木板等物件，木板之间的配合要说两者。"}, {"text": "他双方一个人做完了所有工作。", "explanation": "这里应该用〈独自〉。“双方”指一起做事的两边人，只有一人做事时要说独自。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '2d2a5323-8bfd-4791-8b01-9e493bbb56bb') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (22402, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "比赛的一个双方都很冷静。", "corrected_sentence": "比赛的双方都很冷静。", "error_description": "量词重复：“双方”本身已经指两边，前面不能加“一个”，应直接说“双方都很冷静”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '2d2a5323-8bfd-4791-8b01-9e493bbb56bb') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (22402, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "比赛结束后，一起双方吃了晚饭。", "corrected_sentence": "比赛结束后，双方吃了晚饭。", "error_description": "副词位置错误：“一起”不能放在主语“双方”之前，语序不通，应删去“一起”，说“双方吃了晚饭”；若要强调共同，可说“双方一起吃了晚饭”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '2d2a5323-8bfd-4791-8b01-9e493bbb56bb') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
