INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (22408, 1, 'prompt1_core', '{"pos": "名词", "semantic_class": "concrete", "definition": "指与自己交谈、交往或较量的另一方（人或团体）。", "primary_collocate": null, "pronunciation": "duì fāng", "ipa": "tuei˥˩ faŋ˥", "syllable_count": 2, "sentences": [{"text": "打电话时，要听清对方的话。", "target_word": "对方", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "他不知道对方是谁。", "target_word": "对方", "complexity_tier": "T1", "sentence_source": "generated"}, {"text": "谈生意要先了解对方。", "target_word": "对方", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "比赛中，对方的速度很快。", "target_word": "对方", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "吵架时，不要一直批评对方。", "target_word": "对方", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "我给对方发了一条短信。", "target_word": "对方", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "她笑着对对方说谢谢。", "target_word": "对方", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "好朋友要多为对方想一想。", "target_word": "对方", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "对方同意了我们的办法。", "target_word": "对方", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "两个人说话时，要看着对方的眼睛。", "target_word": "对方", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [], "register": "中性", "sense_fingerprint": "名词：与自己交谈、交往或较量的另一方", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'ca85f957-df35-4d8f-af57-1db695739dd7') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (22408, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "对方", "is_correct": true, "explanation": "“对方”指打电话时对面说话的人，与“话”搭配，句意通顺。"}, {"text": "台灯", "is_correct": false, "explanation": "语义：台灯不会说话，无法发出“的话”，句意不通。"}, {"text": "窗户", "is_correct": false, "explanation": "语义：窗户不会说话，与“听清……的话”矛盾。"}, {"text": "桌子", "is_correct": false, "explanation": "搭配：“听清”的对象应是说话的人或声音，不能说“听清桌子的话”。"}], "explanations": {"对方": "“对方”指打电话时对面说话的人，与“话”搭配，句意通顺。", "台灯": "语义：台灯不会说话，无法发出“的话”，句意不通。", "窗户": "语义：窗户不会说话，与“听清……的话”矛盾。", "桌子": "搭配：“听清”的对象应是说话的人或声音，不能说“听清桌子的话”。"}, "sentence_index": 0, "correct_answer": "对方"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "这个对方是用来喝水的。", "explanation": "这里应该用〈杯子〉。“对方”指与自己相对的人或一方，不能指盛水的器具，应说“杯子”。"}, {"text": "这门对方很难学。", "explanation": "这里应该用〈课程〉。“对方”指相对的人或一方，不能指学习的内容，应说“课程”。"}, {"text": "这个房间的对方很干净。", "explanation": "“对方”只指人或团体，不能指房间等物品，应直接说“这个房间很干净”。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'c290b81d-0dcb-45a5-b379-91fe24a99a2f') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (22408, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "对方", "is_correct": true, "explanation": "“对方”指对面的人，能接受感谢，与“说谢谢”搭配，句意通顺。"}, {"text": "课本", "is_correct": false, "explanation": "搭配：“说谢谢”的对象应是能听见、能接受感谢的人，不能对“课本”说。"}, {"text": "冰箱", "is_correct": false, "explanation": "语义：冰箱不能听，也不能接受感谢，句意不通。"}, {"text": "墙壁", "is_correct": false, "explanation": "语义：墙壁无法接受感谢，句子不合常理。"}], "explanations": {"对方": "“对方”指对面的人，能接受感谢，与“说谢谢”搭配，句意通顺。", "课本": "搭配：“说谢谢”的对象应是能听见、能接受感谢的人，不能对“课本”说。", "冰箱": "语义：冰箱不能听，也不能接受感谢，句意不通。", "墙壁": "语义：墙壁无法接受感谢，句子不合常理。"}, "sentence_index": 6, "correct_answer": "对方"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "马路对方有一家超市。", "explanation": "这里应该用〈对面〉。“对方”指交谈或较量中相对的另一方，表示位置在路的另一侧要说“对面”。"}, {"text": "这次会谈有三个对方参加。", "explanation": "这里应该用〈三方〉。“对方”只指与己方相对的一方，不能用“个”计数多方，三方会谈要说“三方”。"}, {"text": "我在工作对方很努力。", "explanation": "这里应该用〈方面〉。“对方”指与自己相对的一方，不能表示工作等领域，应说“工作方面”。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'c290b81d-0dcb-45a5-b379-91fe24a99a2f') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (22408, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "我对方商量了一下。", "corrected_sentence": "我跟对方商量了一下。", "error_description": "缺少介词“跟”：表示与对方一起商量，要说“跟对方商量”，不能直接说“对方商量”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'c290b81d-0dcb-45a5-b379-91fe24a99a2f') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (22408, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "会议结束后，我们感谢对方对方的合作。", "corrected_sentence": "会议结束后，我们感谢对方的合作。", "error_description": "错误：“对方”重复出现，“对方对方”多了一个“对方”，应说“会议结束后，我们感谢对方的合作。”", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'c290b81d-0dcb-45a5-b379-91fe24a99a2f') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
