INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (22412, 1, 'prompt1_core', '{"pos": "名词", "semantic_class": "abstract", "definition": "不同国家的人互相来往、一起做事。", "primary_collocate": null, "pronunciation": "guó jì jiāo wǎng", "ipa": "kwo˧˥ tɕi˥˩ tɕjɑʊ̯˥ wɑŋ˨˩˦", "syllable_count": 4, "sentences": [{"text": "国际交往时，我们要先了解对方的习惯。", "target_word": "国际交往", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "做国际交往的工作，要会说几种语言。", "target_word": "国际交往", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "孩子们通过夏令营开始了国际交往。", "target_word": "国际交往", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "国际交往中，送礼物也要看对方的文化。", "target_word": "国际交往", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "多参加国际交往，可以认识很多朋友。", "target_word": "国际交往", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "国际交往不只是开会，也包括一起吃饭。", "target_word": "国际交往", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "学校办了活动，让学生多一些国际交往。", "target_word": "国际交往", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "她从小就有很多国际交往的机会。", "target_word": "国际交往", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这个城市因为旅游业发达，国际交往很频繁。", "target_word": "国际交往", "complexity_tier": "T3", "furigana": "guó jì jiāo wǎng", "sentence_source": "generated"}, {"text": "他靠国际交往认识了很多外国朋友。", "target_word": "国际交往", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "國際交往", "label": "繁体"}], "register": "中性", "sense_fingerprint": "名词，不同国家的人之间的来往和合作", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '94f37671-3cb2-4c91-96f6-cc44ccf4491d') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (22412, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "国际交往", "is_correct": true, "explanation": "国际交往指不同国家的人之间的来往，与句中“国际交往时”相符。"}, {"text": "国际地震", "is_correct": false, "explanation": "语义：地震是自然灾害，与“了解对方的习惯”无关。"}, {"text": "国际压力", "is_correct": false, "explanation": "搭配：“国际压力”不是可以进行交往的场合，不能说“国际压力时”。"}, {"text": "国际天气", "is_correct": false, "explanation": "语义：天气是自然现象，不能用来指交往的场合。"}], "explanations": {"国际交往": "国际交往指不同国家的人之间的来往，与句中“国际交往时”相符。", "国际地震": "语义：地震是自然灾害，与“了解对方的习惯”无关。", "国际压力": "搭配：“国际压力”不是可以进行交往的场合，不能说“国际压力时”。", "国际天气": "语义：天气是自然现象，不能用来指交往的场合。"}, "sentence_index": 0, "correct_answer": "国际交往"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "他和同事都是本地人，他的国际交往很好，大家经常一起吃饭。", "explanation": "这里应该用〈人际关系〉。国际交往指不同国家的人之间的往来，同事都是本地人时，相处要说人际关系。"}, {"text": "我们小区的国际交往很频繁，邻居都是老街坊，大家经常互相帮忙。", "explanation": "这里应该用〈邻里往来〉。国际交往指不同国家的人之间的往来，同一小区的老街坊之间的来往要说邻里往来。"}, {"text": "两家本地公司之间的国际交往越来越多。", "explanation": "这里应该用〈商业往来〉。国际交往指国家之间的往来，两家本地公司之间的业务联系要说商业往来。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '547c9bf1-1d04-47df-8459-aa8d45987f7c') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (22412, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "国际交往", "is_correct": true, "explanation": "国际交往指不同国家的人之间的来往，句中“让学生多一些”正指交往活动。"}, {"text": "国际噪音", "is_correct": false, "explanation": "语义：噪音不是可以让学生“多一些”的交流对象，句意不通。"}, {"text": "国际闪电", "is_correct": false, "explanation": "搭配：“多一些”不宜与闪电这类自然现象搭配。"}, {"text": "国际疾病", "is_correct": false, "explanation": "语义：疾病不能让学生“多一些”，与“办活动”的语境不符。"}], "explanations": {"国际交往": "国际交往指不同国家的人之间的来往，句中“让学生多一些”正指交往活动。", "国际噪音": "语义：噪音不是可以让学生“多一些”的交流对象，句意不通。", "国际闪电": "搭配：“多一些”不宜与闪电这类自然现象搭配。", "国际疾病": "语义：疾病不能让学生“多一些”，与“办活动”的语境不符。"}, "sentence_index": 6, "correct_answer": "国际交往"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "我和老同学都是本地人，我们的国际交往很深，十年没有断过。", "explanation": "这里应该用〈友情〉。国际交往指不同国家的人之间的往来，两个本地人之间的交情要说友情。"}, {"text": "这座山村的村民都是本地人，村民之间的国际交往很频繁，大家经常一起种地。", "explanation": "这里应该用〈村民往来〉。国际交往指不同国家的人之间的往来，同村本地村民之间的来往要说村民往来。"}, {"text": "这家饭店的客人都是附近居民，每天的国际交往很多，大家常在这里聊天。", "explanation": "这里应该用〈客流〉。国际交往指不同国家的人之间的往来，附近居民在饭店里的进进出出要说客流。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '547c9bf1-1d04-47df-8459-aa8d45987f7c') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (22412, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "他有过几只国际交往，每次都学到不少东西。", "corrected_sentence": "他有过几次国际交往，每次都学到不少东西。", "error_description": "量词错误：“国际交往”以“次”计量，“只”不能用于交往活动。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '547c9bf1-1d04-47df-8459-aa8d45987f7c') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (22412, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "我们班这学期安排了一只国际交往，大家都很期待。", "corrected_sentence": "我们班这学期安排了一次国际交往，大家都很期待。", "error_description": "量词错误：“国际交往”以“次”计量，应说“一次国际交往”，“只”不能用于交往活动。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '547c9bf1-1d04-47df-8459-aa8d45987f7c') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (22414, 1, 'llm_types_A', '{}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '547c9bf1-1d04-47df-8459-aa8d45987f7c') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (22414, 1, 'llm_types_B', '{}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '547c9bf1-1d04-47df-8459-aa8d45987f7c') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (22414, 1, 'prompt1_core', '{"pos": "动词", "semantic_class": "action", "definition": "想一想，说一个东西是对的还是错的。", "primary_collocate": null, "pronunciation": "pàn duàn", "ipa": "pʰan˥˩ twan˥˩", "syllable_count": 2, "sentences": [{"text": "你来判断，这个答案对不对？", "target_word": "判断", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "我不会判断这朵花有没有毒。", "target_word": "判断", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "请你判断一下，这句话是真是假。", "target_word": "判断", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "两种解法我一时无法判断哪种是对的。", "target_word": "判断", "complexity_tier": "T3", "furigana": "pàn duàn", "sentence_source": "generated"}, {"text": "你能判断这段话的内容是对的还是错的吗？", "target_word": "判断", "complexity_tier": "T3", "furigana": "pàn duàn", "sentence_source": "generated"}, {"text": "他想了想，判断这道题的答案是错的。", "target_word": "判断", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "奶奶闻一闻，就能判断鱼新不新。", "target_word": "判断", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "孩子们要学会判断什么是对，什么是错。", "target_word": "判断", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "只看一眼，我没法判断这个东西好不好。", "target_word": "判断", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "老师请大家判断这个故事是不是真的。", "target_word": "判断", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "判断了", "label": "体标"}, {"form": "判断力", "label": "复合"}], "register": "中性", "sense_fingerprint": "想一想后说东西是对是错", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '94f37671-3cb2-4c91-96f6-cc44ccf4491d') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (22414, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "判断", "is_correct": true, "explanation": "判断指想一想后说对错，句中“这个答案对不对”正是要判断的内容。"}, {"text": "洗", "is_correct": false, "explanation": "语义：洗是清除脏东西，与判断答案对错无关。"}, {"text": "搬", "is_correct": false, "explanation": "语义：搬是移动物体，与判断答案不符。"}, {"text": "寄", "is_correct": false, "explanation": "搭配：“寄”针对信件或包裹，不能用于“答案对不对”。"}], "explanations": {"判断": "判断指想一想后说对错，句中“这个答案对不对”正是要判断的内容。", "洗": "语义：洗是清除脏东西，与判断答案对错无关。", "搬": "语义：搬是移动物体，与判断答案不符。", "寄": "搭配：“寄”针对信件或包裹，不能用于“答案对不对”。"}, "sentence_index": 0, "correct_answer": "判断"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "他能判断出每个人的声音。", "explanation": "这里应该用〈分辨〉。判断是想一想说对错，听出声音是谁要说分辨。"}, {"text": "妈妈判断了一条鱼。", "explanation": "这里应该用〈挑〉。判断是对对错的认识，挑选东西要说挑。"}, {"text": "老师判断了黑板上的字，很快就清理了。", "explanation": "这里应该用〈擦〉。判断是想一想说对错，擦掉黑板上的字要说擦。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '547c9bf1-1d04-47df-8459-aa8d45987f7c') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (22414, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "判断", "is_correct": true, "explanation": "判断指想一想说对错，“闻一闻就能……鱼新不新”正是对鱼的新鲜度作出认识。"}, {"text": "煎", "is_correct": false, "explanation": "语义：煎是用油加热做饭，与判断鱼新不新无关。"}, {"text": "扔", "is_correct": false, "explanation": "语义：扔是丢弃，不是对事物作出认识。"}, {"text": "拍", "is_correct": false, "explanation": "搭配：“拍”后面不能接“鱼新不新”这类结构，句子不通。"}], "explanations": {"判断": "判断指想一想说对错，“闻一闻就能……鱼新不新”正是对鱼的新鲜度作出认识。", "煎": "语义：煎是用油加热做饭，与判断鱼新不新无关。", "扔": "语义：扔是丢弃，不是对事物作出认识。", "拍": "搭配：“拍”后面不能接“鱼新不新”这类结构，句子不通。"}, "sentence_index": 6, "correct_answer": "判断"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "奶奶给孩子们判断了一个故事。", "explanation": "这里应该用〈讲〉。判断是对对错作出认识，给孩子们讲故事要说讲。"}, {"text": "这位歌手判断了一首歌。", "explanation": "这里应该用〈唱〉。判断是对事情作出认识，演唱歌曲要说唱。"}, {"text": "他判断了一下花园里的小路。", "explanation": "这里应该用〈修〉。判断是对对错作出认识，修整小路要说修。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '547c9bf1-1d04-47df-8459-aa8d45987f7c') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (22414, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "他一眼就判断着这个方案是错的。", "corrected_sentence": "他一眼就判断了这个方案是错的。", "error_description": "体标错误：“一眼就”表示瞬间完成的判断，应用“了”；“着”表示持续，与之不能搭配。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '547c9bf1-1d04-47df-8459-aa8d45987f7c') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (22414, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "我判断了错这道题的答案。", "corrected_sentence": "我判断错了这道题的答案。", "error_description": "补语错误：结果补语“错”应紧跟动词，说“判断错了”，不能说“判断了错”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '547c9bf1-1d04-47df-8459-aa8d45987f7c') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
