INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (22416, 1, 'prompt1_core', '{"pos": "动词", "semantic_class": "action", "definition": "两个人想的不一样，就错了。", "primary_collocate": null, "pronunciation": "chǎn shēng wù huì", "ipa": "tʂʰan˨˩˦ ʂɤŋ˥ u˥˩ xweɪ̯˥˩", "syllable_count": 4, "sentences": [{"text": "你们想法不一样，难免会产生误会。", "target_word": "产生误会", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他以为我在笑他，所以产生误会。", "target_word": "产生误会", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "我说的是明天，她听成了今天，产生误会。", "target_word": "产生误会", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "她没看清楚信，就产生误会，哭了。", "target_word": "产生误会", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他们对同一句话理解不同，产生误会。", "target_word": "产生误会", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这件事我没解释，朋友就产生误会。", "target_word": "产生误会", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "老师和家长没有沟通，孩子容易产生误会。", "target_word": "产生误会", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他把我的玩笑当真了，结果产生误会。", "target_word": "产生误会", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "地址写得不清楚，我们差点产生误会。", "target_word": "产生误会", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "打电话说清楚，才不会产生误会。", "target_word": "产生误会", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "产生了误会", "label": "体标"}, {"form": "产生过误会", "label": "体标"}, {"form": "產生誤會", "label": "繁体"}], "register": "中性", "sense_fingerprint": "动宾短语，两人想法不同而理解错了对方的意思", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '94f37671-3cb2-4c91-96f6-cc44ccf4491d') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (22416, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "产生误会", "is_correct": true, "explanation": "产生误会：因想法不同而理解有偏差，出现错误的认识，与“想法不一样”的语境相符。"}, {"text": "达成一致", "is_correct": false, "explanation": "语义：“达成一致”表示意见相同，与“想法不一样”的前提正好相反。"}, {"text": "表示赞同", "is_correct": false, "explanation": "搭配：“表示赞同”要求双方已有相同看法，与“想法不一样”不搭配。"}, {"text": "心有灵犀", "is_correct": false, "explanation": "语义：“心有灵犀”表示心意相通，与“想法不一样”相矛盾。"}], "explanations": {"产生误会": "产生误会：因想法不同而理解有偏差，出现错误的认识，与“想法不一样”的语境相符。", "达成一致": "语义：“达成一致”表示意见相同，与“想法不一样”的前提正好相反。", "表示赞同": "搭配：“表示赞同”要求双方已有相同看法，与“想法不一样”不搭配。", "心有灵犀": "语义：“心有灵犀”表示心意相通，与“想法不一样”相矛盾。"}, "sentence_index": 0, "correct_answer": "产生误会"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "这种药很容易产生误会。", "explanation": "这里应该用〈副作用〉。“误会”指人与人之间因理解不同而产生的错误认识，药物引起的不良反应应说副作用。"}, {"text": "这台电脑产生了误会。", "explanation": "这里应该用〈故障〉。“误会”只用于人对事情的理解错误，电脑出问题应说故障。"}, {"text": "这块布料产生了误会。", "explanation": "这里应该用〈起球〉。“误会”不能用于布料，布料表面起小球应说起球。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '547c9bf1-1d04-47df-8459-aa8d45987f7c') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (22416, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "产生误会", "is_correct": true, "explanation": "产生误会：因理解有偏差而出现错误的认识，与“没有沟通”容易导致的结果相符。"}, {"text": "建立信任", "is_correct": false, "explanation": "语义：“建立信任”是积极结果，与“没有沟通”的前提相矛盾。"}, {"text": "形成默契", "is_correct": false, "explanation": "语义：“形成默契”需要充分沟通，与“没有沟通”的前提冲突。"}, {"text": "促膝长谈", "is_correct": false, "explanation": "语域：“促膝长谈”是书面色彩较强的成语，与这句口语化的叙述不合，且与“没有沟通”相矛盾。"}], "explanations": {"产生误会": "产生误会：因理解有偏差而出现错误的认识，与“没有沟通”容易导致的结果相符。", "建立信任": "语义：“建立信任”是积极结果，与“没有沟通”的前提相矛盾。", "形成默契": "语义：“形成默契”需要充分沟通，与“没有沟通”的前提冲突。", "促膝长谈": "语域：“促膝长谈”是书面色彩较强的成语，与这句口语化的叙述不合，且与“没有沟通”相矛盾。"}, "sentence_index": 6, "correct_answer": "产生误会"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "这个伤口容易产生误会。", "explanation": "这里应该用〈感染〉。“误会”指人对事情理解有误，伤口发炎应说感染。"}, {"text": "这个软件产生了误会。", "explanation": "这里应该用〈漏洞〉。“误会”不能用于软件，软件存在的缺陷应说漏洞。"}, {"text": "她的皮肤产生了误会。", "explanation": "这里应该用〈过敏〉。“误会”不能用于皮肤，皮肤对某物产生反应应说过敏。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '547c9bf1-1d04-47df-8459-aa8d45987f7c') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (22416, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "他们曾经产生着误会，后来和好了。", "corrected_sentence": "他们曾经产生过误会，后来和好了。", "error_description": "错误：“着”用错。“曾经”指已结束的经历，应用表示经历的“过”；“着”表示持续的状态，与“曾经”矛盾。正确说法是“他们曾经产生过误会，后来和好了”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '547c9bf1-1d04-47df-8459-aa8d45987f7c') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (22416, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "两人之间产生误会着，后来和好了。", "corrected_sentence": "两人之间产生误会了，后来和好了。", "error_description": "错误：“着”用错。“着”表示持续的状态，“产生误会”是一次性的事件，完成后应用“了”，正确说法是“产生误会了”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '547c9bf1-1d04-47df-8459-aa8d45987f7c') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
