INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (22420, 1, 'prompt1_core', '{"pos": "名词", "semantic_class": "abstract", "definition": "专业指一个人专门学习或从事的学科或领域。", "primary_collocate": null, "pronunciation": "zhuān yè", "ipa": "ʈʂwan˥ jɛ˥˩", "syllable_count": 2, "sentences": [{"text": "我的专业是历史。", "target_word": "专业", "complexity_tier": "T1", "sentence_source": "generated"}, {"text": "你学什么专业？", "target_word": "专业", "complexity_tier": "T1", "sentence_source": "generated"}, {"text": "她选了一个很难的专业。", "target_word": "专业", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "哥哥的专业是电脑，他每天都写程序。", "target_word": "专业", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "我对这个专业很有兴趣。", "target_word": "专业", "complexity_tier": "T1", "sentence_source": "generated"}, {"text": "上大学以前，我还不知道要选什么专业。", "target_word": "专业", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "我们的专业不一样，可是我们是好朋友。", "target_word": "专业", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "他毕业后做的工作和专业没有关系。", "target_word": "专业", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "弟弟想换一个专业，爸爸不同意。", "target_word": "专业", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "她的专业是音乐，所以唱歌唱得很好。", "target_word": "专业", "complexity_tier": "T2", "sentence_source": "generated"}], "morphological_forms": [{"form": "專業", "label": "繁体"}, {"form": "个", "label": "量词"}], "register": "中性", "sense_fingerprint": "专业·名词·专门学习或从事的领域", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '79963f23-daa7-47ea-a422-83820dc3fd66') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (22420, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "专业", "is_correct": true, "explanation": "专业：指所学的学科，“我的专业是历史”说明学的是历史。"}, {"text": "身高", "is_correct": false, "explanation": "语义：“身高”指身体的高度，不能与“是历史”搭配，句子说不通。"}, {"text": "性格", "is_correct": false, "explanation": "语义：“性格”指个人的脾气特点，不能是一门学科。"}, {"text": "颜色", "is_correct": false, "explanation": "搭配：“颜色”不能与“是历史”搭配，句子说不通。"}], "explanations": {"专业": "专业：指所学的学科，“我的专业是历史”说明学的是历史。", "身高": "语义：“身高”指身体的高度，不能与“是历史”搭配，句子说不通。", "性格": "语义：“性格”指个人的脾气特点，不能是一门学科。", "颜色": "搭配：“颜色”不能与“是历史”搭配，句子说不通。"}, "sentence_index": 0, "correct_answer": "专业"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "他的专业是医生，每天都看病人。", "explanation": "这里应该用〈职业〉。“专业”指所学的方向，不能指工作身份。"}, {"text": "这孩子的专业很好，每顿都吃两碗饭。", "explanation": "这里应该用〈食欲〉。“专业”指所学的学科或所做的事，不能用来说吃饭的胃口。"}, {"text": "这个菜的专业很好，我每天都吃。", "explanation": "这里应该用〈味道〉。“专业”指所学或所做的领域，不能用来形容菜的口感。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '5c0637b4-a516-4149-95c7-5f1973d11154') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (22420, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "专业", "is_correct": true, "explanation": "专业：指所学的学科，“我们的专业不一样”说明所学的方向不同。"}, {"text": "敌人", "is_correct": false, "explanation": "语义：“敌人”与“是好朋友”矛盾，句子语义不通。"}, {"text": "天气", "is_correct": false, "explanation": "搭配：“天气”指气候，不能用来指人所学的方向。"}, {"text": "海拔", "is_correct": false, "explanation": "搭配：“海拔”指地面的高度，不能用于人所学的内容。"}], "explanations": {"专业": "专业：指所学的学科，“我们的专业不一样”说明所学的方向不同。", "敌人": "语义：“敌人”与“是好朋友”矛盾，句子语义不通。", "天气": "搭配：“天气”指气候，不能用来指人所学的方向。", "海拔": "搭配：“海拔”指地面的高度，不能用于人所学的内容。"}, "sentence_index": 6, "correct_answer": "专业"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "他在金融专业工作，每天很忙。", "explanation": "这里应该用〈行业〉。“专业”指所学的学科，不能指工作的领域或单位。"}, {"text": "这个笑话很专业，大家都笑了。", "explanation": "这里应该用〈好笑〉。“专业”形容技能或做事水平，不能用来形容笑话。"}, {"text": "她的专业很高兴，老师让她回家。", "explanation": "这里应该用〈心情〉。“专业”指所学的学科，不能用来形容人的情绪。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '5c0637b4-a516-4149-95c7-5f1973d11154') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (22420, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "这是我个专业，我很喜欢它。", "corrected_sentence": "这是我的专业，我很喜欢它。", "error_description": "“我的”表示所属，应写成“我的专业”；“我个专业”误用量词“个”，量词不能直接放在代词和名词之间表示所属。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '5c0637b4-a516-4149-95c7-5f1973d11154') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (22420, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "我妹妹地专业是英语，她很喜欢。", "corrected_sentence": "我妹妹的专业是英语，她很喜欢。", "error_description": "“的”误写为“地”：“的”修饰名词“专业”，应写成“我妹妹的专业”；“地”用于修饰动词或形容词，“妹妹地专业”不通。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '5c0637b4-a516-4149-95c7-5f1973d11154') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
