INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (22422, 1, 'prompt1_core', '{"pos": "形容词", "semantic_class": "function", "definition": "跟别的不一样，很突出。", "primary_collocate": null, "pronunciation": "tè bié", "ipa": "tʰɤ˥˩ pje˧˥", "syllable_count": 2, "sentences": [{"text": "这是一个特别的日子。", "target_word": "特别", "complexity_tier": "T3", "furigana": "zhè shì yí gè tè bié de rì zi", "sentence_source": "generated"}, {"text": "这家店的菜很特别。", "target_word": "特别", "complexity_tier": "T3", "furigana": "zhè jiā diàn de cài hěn tè bié", "sentence_source": "generated"}, {"text": "他的想法很特别。", "target_word": "特别", "complexity_tier": "T3", "furigana": "tā de xiǎng fǎ hěn tè bié", "sentence_source": "generated"}, {"text": "他有一种特别的气质。", "target_word": "特别", "complexity_tier": "T3", "furigana": "tā yǒu yì zhǒng tè bié de qì zhì", "sentence_source": "generated"}, {"text": "这个设计很特别，大家都没见过。", "target_word": "特别", "complexity_tier": "T3", "furigana": "zhè gè shè jì hěn tè bié dà jiā dōu méi jiàn guo", "sentence_source": "generated"}, {"text": "她的笑容很特别。", "target_word": "特别", "complexity_tier": "T3", "furigana": "tā de xiào róng hěn tè bié", "sentence_source": "generated"}, {"text": "这座城市的建筑很特别。", "target_word": "特别", "complexity_tier": "T3", "furigana": "zhè zuò chéng shì de jiàn zhù hěn tè bié", "sentence_source": "generated"}, {"text": "这个小镇有一个特别的习俗。", "target_word": "特别", "complexity_tier": "T3", "furigana": "zhè gè xiǎo zhèn yǒu yí gè tè bié de xí sú", "sentence_source": "generated"}, {"text": "他选择的职业很特别。", "target_word": "特别", "complexity_tier": "T3", "furigana": "tā xuǎn zé de zhí yè hěn tè bié", "sentence_source": "generated"}, {"text": "这只猫的叫声很特别。", "target_word": "特别", "complexity_tier": "T3", "furigana": "zhè zhī māo de jiào shēng hěn tè bié", "sentence_source": "generated"}], "morphological_forms": [{"form": "特别是", "label": "复合"}], "register": "中性", "sense_fingerprint": "形容词，表示跟别的不一样、很突出", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '06053499-ed7b-46b4-88c1-4bffbe9831f7') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (22422, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "咸", "is_correct": false, "explanation": "语义：“咸”形容味道，不能用来形容日子。"}, {"text": "坚硬", "is_correct": false, "explanation": "语义：“坚硬”形容物体质地硬，不能用来形容日子。"}, {"text": "特别", "is_correct": true, "explanation": "“特别”表示跟别的不一样、很突出，与“一个特别的日子”相符。"}, {"text": "大方", "is_correct": false, "explanation": "搭配：“大方”形容人的举止、待人的态度，不能用来形容日子。"}], "explanations": {"咸": "语义：“咸”形容味道，不能用来形容日子。", "坚硬": "语义：“坚硬”形容物体质地硬，不能用来形容日子。", "特别": "“特别”表示跟别的不一样、很突出，与“一个特别的日子”相符。", "大方": "搭配：“大方”形容人的举止、待人的态度，不能用来形容日子。"}, "sentence_index": 0, "correct_answer": "特别"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "我特别从北京赶来看你。", "explanation": "这里的“特别”是“特地、专门”的意思，表示为某事特意去做，不是“跟别的不一样、很突出”的意思。"}, {"text": "我最喜欢夏天，特别是七月。", "explanation": "这里的“特别是”是“尤其”的意思，用来强调范围，不是“跟别的不一样、很突出”的意思。"}, {"text": "这间房是特别为客人准备的。", "explanation": "这里的“特别”表示“专门为……”，强调用途，不是“很突出、跟别的不一样”的意思。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'a704dd41-623e-44e9-8b48-d1a704de2e07') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (22422, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "清澈", "is_correct": false, "explanation": "搭配：“清澈”形容水、眼睛等，不能用来形容建筑。"}, {"text": "甜美", "is_correct": false, "explanation": "语义：“甜美”形容味道、笑容或声音，不能用来形容建筑。"}, {"text": "轻快", "is_correct": false, "explanation": "搭配：“轻快”形容步伐、节奏，不用于描写建筑。"}, {"text": "特别", "is_correct": true, "explanation": "“特别”表示跟别的不一样、很突出，与“建筑很特别”相符。"}], "explanations": {"清澈": "搭配：“清澈”形容水、眼睛等，不能用来形容建筑。", "甜美": "语义：“甜美”形容味道、笑容或声音，不能用来形容建筑。", "轻快": "搭配：“轻快”形容步伐、节奏，不用于描写建筑。", "特别": "“特别”表示跟别的不一样、很突出，与“建筑很特别”相符。"}, "sentence_index": 6, "correct_answer": "特别"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "这家餐厅的菜很有特别，很多人慕名而来。", "explanation": "这里应该用〈特色〉。“有特色”是固定说法；“特别”是形容词或副词，不能作名词，说“有特别”不通。"}, {"text": "这种花的特别很明显，叶子又大又厚。", "explanation": "这里应该用〈特征〉。“特别”不能作名词，说明事物显著的特点要用“特征”。"}, {"text": "这部电影的特别很逼真，让人印象深刻。", "explanation": "这里应该用〈特效〉。“特效”是名词，“特别”不能作名词使用。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'a704dd41-623e-44e9-8b48-d1a704de2e07') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (22422, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "他送的礼物有特别。", "corrected_sentence": "他送的礼物很特别。", "error_description": "错误：“特别”是形容词，不能跟动词“有”连用，说“有特别”不通；应用程度副词“很”修饰形容词，说“很特别”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'a704dd41-623e-44e9-8b48-d1a704de2e07') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (22422, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "这个小镇有很多特别是节日，外地人都想来看看。", "corrected_sentence": "这个小镇有很多特别的节日，外地人都想来看看。", "error_description": "错误：“特别是”是固定的连词，表示“尤其”，不能直接修饰名词“节日”，应说“特别的节日”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'a704dd41-623e-44e9-8b48-d1a704de2e07') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (22424, 1, 'llm_types_A', '{"synonym_antonym_match": {"relation": "antonym", "options": [{"text": "勤快", "is_correct": true, "explanation": "勤快与懒是反义词，指肯劳动、爱做事。"}, {"text": "健康", "is_correct": false, "explanation": "与懒不构成反义关系，健康指身体状况良好。"}, {"text": "聪明", "is_correct": false, "explanation": "与懒不构成反义关系，聪明指智力高。"}, {"text": "安静", "is_correct": false, "explanation": "与懒不构成反义关系，安静指没有声音或不吵闹。"}], "correct_answer": "勤快", "explanations": {"勤快": "勤快与懒是反义词，指肯劳动、爱做事。", "健康": "与懒不构成反义关系，健康指身体状况良好。", "聪明": "与懒不构成反义关系，聪明指智力高。", "安静": "与懒不构成反义关系，安静指没有声音或不吵闹。"}, "sentence_index": 3}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'af16ae78-9ad3-4555-8654-f22afd99fb1e') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
