INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (22434, 1, 'prompt1_core', '{"pos": "名词", "semantic_class": "abstract", "definition": "生活就是每天做的事情。", "primary_collocate": null, "pronunciation": "shēng huó", "ipa": "ʂəŋ˥ xuo˧˥", "syllable_count": 2, "sentences": [{"text": "早上跑步、晚上看书是我每天的生活。", "target_word": "生活", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "我的生活很简单：上班、吃饭、睡觉。", "target_word": "生活", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "每天做饭、洗衣服就是妈妈的生活。", "target_word": "生活", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "你每天的生活是什么样的？", "target_word": "生活", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他把每天的生活都写在日记里。", "target_word": "生活", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "学生的生活就是上课和做作业。", "target_word": "生活", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "来到新城市，我每天的生活有了变化。", "target_word": "生活", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "孩子们每天的生活很有意思。", "target_word": "生活", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "请给我们说说你一天的生活。", "target_word": "生活", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "退休后，奶奶每天的生活很有规律。", "target_word": "生活", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "日常生活", "label": "复合"}, {"form": "生活费", "label": "复合"}], "register": "中性", "sense_fingerprint": "每天做的事情，日常的作息和安排", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '405dfc4a-6ee0-42e9-8dd9-f58f27602e01') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (22434, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "生活", "is_correct": true, "explanation": "正确：指每天的日常作息和做的事情，与“跑步、看书”的语境相符。"}, {"text": "天气", "is_correct": false, "explanation": "语义：天气不是人每天做的事情，“每天的天气”与“跑步、看书”不能并列。"}, {"text": "外貌", "is_correct": false, "explanation": "体貌：外貌指长相，与跑步、看书这类活动无关，不能说成每天的外貌。"}, {"text": "电话", "is_correct": false, "explanation": "语义：电话是通讯工具，不是每天做的事情，句子说的是日常活动。"}], "explanations": {"生活": "正确：指每天的日常作息和做的事情，与“跑步、看书”的语境相符。", "天气": "语义：天气不是人每天做的事情，“每天的天气”与“跑步、看书”不能并列。", "外貌": "体貌：外貌指长相，与跑步、看书这类活动无关，不能说成每天的外貌。", "电话": "语义：电话是通讯工具，不是每天做的事情，句子说的是日常活动。"}, "sentence_index": 0, "correct_answer": "生活"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "这家店的生活很好。", "explanation": "这里应用〈生意〉。“生活”指人过日子，不指店铺的经营状况，店铺经营得好应说〈生意〉。"}, {"text": "这台旧冰箱的生活已经很长了。", "explanation": "这里应用〈寿命〉。“生活”指人的日常过日子，不指物品的使用年限，应说〈寿命〉。"}, {"text": "这个月我的生活比上个月多了三千块。", "explanation": "这里应用〈收入〉。“生活”不表示金钱收入，收入的增减应说〈收入〉。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '25f006cb-5b59-4041-be28-5e9b648439a2') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (22434, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "生活", "is_correct": true, "explanation": "正确：指日常的生活状况，与“来到新城市，有了变化”的语境相符。"}, {"text": "年龄", "is_correct": false, "explanation": "语义：年龄不会每天变化，“每天的年龄”与句意矛盾。"}, {"text": "学历", "is_correct": false, "explanation": "语义：学历是受教育的经历记录，不会随每天的变化而改变。"}, {"text": "星座", "is_correct": false, "explanation": "语义：星座是出生时就确定的，不会随时间变化，与“来到新城市”后的变化不合。"}], "explanations": {"生活": "正确：指日常的生活状况，与“来到新城市，有了变化”的语境相符。", "年龄": "语义：年龄不会每天变化，“每天的年龄”与句意矛盾。", "学历": "语义：学历是受教育的经历记录，不会随每天的变化而改变。", "星座": "语义：星座是出生时就确定的，不会随时间变化，与“来到新城市”后的变化不合。"}, "sentence_index": 6, "correct_answer": "生活"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "奶奶每天的生活很好吃。", "explanation": "这里应用〈饭菜〉。“生活”不指饭菜，说味道好应用〈饭菜〉。"}, {"text": "奶奶每天早上都生活一杯牛奶。", "explanation": "这里应用〈喝〉。“生活”是名词，不能作动词，喝牛奶应说“喝一杯牛奶”。"}, {"text": "奶奶每天在公园生活两个小时。", "explanation": "这里应用〈锻炼〉。“生活”是过日子，不能表示在某地做某事一段时间。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '25f006cb-5b59-4041-be28-5e9b648439a2') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (22434, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "他过着一根平静的生活。", "corrected_sentence": "他过着一种平静的生活。", "error_description": "量词错误：“生活”不能用“根”，“根”用于细长的东西。正确形式：一种平静的生活。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '25f006cb-5b59-4041-be28-5e9b648439a2') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (22434, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "我们的生活过很幸福。", "corrected_sentence": "我们的生活过得很幸福。", "error_description": "补语错误：“过”与补语“很幸福”之间应加“得”。正确形式：过得很幸福。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '25f006cb-5b59-4041-be28-5e9b648439a2') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (22440, 1, 'llm_types_A', '{}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '547c9bf1-1d04-47df-8459-aa8d45987f7c') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
