INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (22440, 1, 'prompt1_core', '{"pos": "副词", "semantic_class": "function", "definition": "在事情开始之前做。", "primary_collocate": null, "pronunciation": "tí qián", "ipa": "tʰi˧˥ tɕʰiɛn˧˥", "syllable_count": 2, "sentences": [{"text": "请提前告诉我你什么时候到。", "target_word": "提前", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "看病要提前预约，不然要等很久。", "target_word": "提前", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "出门旅行，要提前买好车票。", "target_word": "提前", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "我提前做好了晚饭，等你回来吃。", "target_word": "提前", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "老师让我们提前看一看明天的课文。", "target_word": "提前", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "客人要来，妈妈提前打扫了房间。", "target_word": "提前", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "你提前准备好，考试时就不会紧张。", "target_word": "提前", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "这家饭店很热门，最好提前订位子。", "target_word": "提前", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "下雨的话，请提前给我打个电话。", "target_word": "提前", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "他提前到了会场，想先看看环境。", "target_word": "提前", "complexity_tier": "T2", "sentence_source": "generated"}], "morphological_forms": [], "register": "中性", "sense_fingerprint": "在事情开始之前先做", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '94f37671-3cb2-4c91-96f6-cc44ccf4491d') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (22440, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "提前", "is_correct": true, "explanation": "提前：在到达之前先告知，符合“请……告诉我”的语境。"}, {"text": "已经", "is_correct": false, "explanation": "语义：“已经”表示动作已经完成，与“请……告诉我”的请求语气不合。"}, {"text": "终于", "is_correct": false, "explanation": "语义：“终于”表示经过等待后的结果，不用来提出请求。"}, {"text": "刚刚", "is_correct": false, "explanation": "语义：“刚刚”指不久前发生的事，与对将来的请求不合。"}], "explanations": {"提前": "提前：在到达之前先告知，符合“请……告诉我”的语境。", "已经": "语义：“已经”表示动作已经完成，与“请……告诉我”的请求语气不合。", "终于": "语义：“终于”表示经过等待后的结果，不用来提出请求。", "刚刚": "语义：“刚刚”指不久前发生的事，与对将来的请求不合。"}, "sentence_index": 0, "correct_answer": "提前"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "比赛时他提前追上了对手。", "explanation": "这里应该用〈超过〉。“提前”只指在事情开始之前做某事或时间的前移，赛跑中胜过对手要说“超过”。"}, {"text": "会议已经开始了，他才提前到会场。", "explanation": "这里应该用〈迟到〉。会议已经开始，他才到会场，说明没有事先到达，“提前”在此说不通。"}, {"text": "作业已经交了，我又提前把作业写完了。", "explanation": "这里的“提前”被误当作“早就、早已”的意思。作业已经交了，写完已是事后之事，不能说提前写完，应说〈补写〉。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '547c9bf1-1d04-47df-8459-aa8d45987f7c') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (22440, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "提前", "is_correct": true, "explanation": "提前：先把事情做好，使考试时更有把握，符合语境。"}, {"text": "白白", "is_correct": false, "explanation": "语义：“白白”表示徒劳，与“考试时就不会紧张”的积极结果矛盾。"}, {"text": "正在", "is_correct": false, "explanation": "体貌：“正在”表示动作进行中，与表示结果已完成的“准备好”不相容。"}, {"text": "忽然", "is_correct": false, "explanation": "语义：“忽然”表示突然发生，与有计划的“准备”不合。"}], "explanations": {"提前": "提前：先把事情做好，使考试时更有把握，符合语境。", "白白": "语义：“白白”表示徒劳，与“考试时就不会紧张”的积极结果矛盾。", "正在": "体貌：“正在”表示动作进行中，与表示结果已完成的“准备好”不相容。", "忽然": "语义：“忽然”表示突然发生，与有计划的“准备”不合。"}, "sentence_index": 6, "correct_answer": "提前"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "这台机器的功率提前了一倍。", "explanation": "这里应该用〈增大〉。“提前”只指在事情开始之前做某事或时间的前移，功率的增加要说“增大”。"}, {"text": "他已经到了会场，却还要提前进场。", "explanation": "这里的“提前”被误当作“早已、先于某时”的意思。他已身在会场，不能再说提前进场，应说〈准时入场〉。"}, {"text": "电影已经放映了一半，我提前买了票。", "explanation": "这里的“提前”被误当作“早先”的意思。电影已放映过半，买票已不是事先的行为，应说〈补票〉。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '547c9bf1-1d04-47df-8459-aa8d45987f7c') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (22440, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "我们提前的订好了机票。", "corrected_sentence": "我们提前订好了机票。", "error_description": "错误：“提前的订好了机票”；正确：“提前订好了机票”。“提前”是状语修饰动词，后面不加“的”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '547c9bf1-1d04-47df-8459-aa8d45987f7c') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (22440, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "老师提前了通知我们考试的时间。", "corrected_sentence": "老师提前通知我们考试的时间。", "error_description": "错误：“提前了通知”；正确：“提前通知”。“提前”作状语修饰动词，其后不能直接加“了”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '547c9bf1-1d04-47df-8459-aa8d45987f7c') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
