INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (22448, 1, 'prompt1_core', '{"pos": "名词", "semantic_class": "concrete", "definition": "显影剂是让照片慢慢变出来的药水。", "primary_collocate": null, "pronunciation": "xiǎn yǐng jì", "ipa": "ɕjɛn˨˩˦ iŋ˨˩˦ tɕi˥˩", "syllable_count": 3, "sentences": [{"text": "把相纸放进显影剂，照片慢慢出现了。", "target_word": "显影剂", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这瓶显影剂是专门冲照片用的。", "target_word": "显影剂", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "暗房里有一盆显影剂。", "target_word": "显影剂", "complexity_tier": "T1", "sentence_source": "generated"}, {"text": "他用显影剂洗出了旧照片。", "target_word": "显影剂", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "显影剂倒进盘子里，白纸上出现了人脸。", "target_word": "显影剂", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "没有显影剂，底片上什么也看不见。", "target_word": "显影剂", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "爷爷年轻时常常自己配显影剂。", "target_word": "显影剂", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "显影剂要放在阴凉的地方。", "target_word": "显影剂", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "照片在显影剂里一点点变清楚。", "target_word": "显影剂", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "小心，显影剂不能喝，也不要碰到眼睛。", "target_word": "显影剂", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "种", "label": "量词"}, {"form": "瓶", "label": "量词"}, {"form": "顯影劑", "label": "繁体"}], "register": "中性", "sense_fingerprint": "洗照片时让相纸或底片上的图像慢慢出现的药水", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '9b63813c-68c7-48fa-8360-f041b5f6ea4e') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (22448, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "显影剂", "is_correct": true, "explanation": "正确：显影剂能使相纸上的图像慢慢出现，符合句意。"}, {"text": "洗衣粉", "is_correct": false, "explanation": "语义：洗衣粉不能使图像显现。"}, {"text": "茶叶", "is_correct": false, "explanation": "语义：茶叶与照片出现无关。"}, {"text": "垃圾桶", "is_correct": false, "explanation": "语义：垃圾桶是盛放废物的容器，不会使照片出现。"}], "explanations": {"显影剂": "正确：显影剂能使相纸上的图像慢慢出现，符合句意。", "洗衣粉": "语义：洗衣粉不能使图像显现。", "茶叶": "语义：茶叶与照片出现无关。", "垃圾桶": "语义：垃圾桶是盛放废物的容器，不会使照片出现。"}, "sentence_index": 0, "correct_answer": "显影剂"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "照片洗好后，要用显影剂把图像固定下来。", "explanation": "这里应该用〈定影剂〉。显影剂使图像显现，固定图像要用定影剂。"}, {"text": "这件衣服要用显影剂洗干净。", "explanation": "这里应该用〈洗涤剂〉。显影剂只让照片上的影像显出来，不能用来洗衣服，去污要用洗涤剂。"}, {"text": "这些旧照片泛黄了，要用显影剂漂白。", "explanation": "这里应该用〈漂白剂〉。显影剂只让图像显现，不起漂白作用。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'ecdaac6c-e131-43d3-92f5-dda6f5f80093') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (22448, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "显影剂", "is_correct": true, "explanation": "正确：显影剂是可以自己调配的药水，符合句意。"}, {"text": "手机", "is_correct": false, "explanation": "搭配：“配”一般不与手机搭配，手机无法自己调配。"}, {"text": "汽车", "is_correct": false, "explanation": "语义：汽车不能自己调配，与冲洗照片无关。"}, {"text": "冰箱", "is_correct": false, "explanation": "语义：冰箱是成品家电，一般不能说“自己配”，与句意不合。"}], "explanations": {"显影剂": "正确：显影剂是可以自己调配的药水，符合句意。", "手机": "搭配：“配”一般不与手机搭配，手机无法自己调配。", "汽车": "语义：汽车不能自己调配，与冲洗照片无关。", "冰箱": "语义：冰箱是成品家电，一般不能说“自己配”，与句意不合。"}, "sentence_index": 6, "correct_answer": "显影剂"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "这种显影剂能把布料上的颜色去掉。", "explanation": "这里应该用〈脱色剂〉。显影剂只让照片上的影像显出来，不能去掉布料上的颜色。"}, {"text": "装底片前，先在底片上涂一层显影剂，使它感光。", "explanation": "这里应该用〈感光剂〉。显影剂只能显现已曝光的影像，不能使底片感光。"}, {"text": "这瓶显影剂可以用来写字。", "explanation": "这里应该用〈墨水〉。显影剂用于冲洗照片，不能用来写字。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'ecdaac6c-e131-43d3-92f5-dda6f5f80093') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (22448, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "照片要先显影剂里泡一下。", "corrected_sentence": "照片要先在显影剂里泡一下。", "error_description": "介词漏掉：表示地点的“显影剂里”前要加介词“在”，应说“在显影剂里泡”，不能直接说“显影剂里泡”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'ecdaac6c-e131-43d3-92f5-dda6f5f80093') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (22448, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "他把一只显影剂倒进了盘子里。", "corrected_sentence": "他把一瓶显影剂倒进了盘子里。", "error_description": "量词错误：显影剂是液体，应用“瓶”，不能用“只”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'ecdaac6c-e131-43d3-92f5-dda6f5f80093') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
