INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (22450, 1, 'prompt1_core', '{"pos": "动词", "semantic_class": "action", "definition": "慢慢地被影响，自己不知道。", "primary_collocate": null, "pronunciation": "qián yí mò huà", "ipa": "tɕʰjɛn˧˥ i˧˥ mwo˥˩ xwa˥˩", "syllable_count": 4, "sentences": [{"text": "他跟朋友学，潜移默化地爱上了跑步。", "target_word": "潜移默化", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "孩子的好习惯是潜移默化地养成的。", "target_word": "潜移默化", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "看了很多年中国电影，她潜移默化地会说一些中文。", "target_word": "潜移默化", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "爸爸爱读书，我也潜移默化地喜欢上了书。", "target_word": "潜移默化", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "在这个班里，大家潜移默化地都变得很努力。", "target_word": "潜移默化", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "你的话潜移默化地改变了我的想法。", "target_word": "潜移默化", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "住在海边的人，潜移默化地习惯了海的声音。", "target_word": "潜移默化", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "老师不说教，却潜移默化地教会了我们很多。", "target_word": "潜移默化", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "奶奶做饭的味道，潜移默化地留在了我心里。", "target_word": "潜移默化", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "音乐对孩子的影响是潜移默化的。", "target_word": "潜移默化", "complexity_tier": "T2", "sentence_source": "generated"}], "morphological_forms": [{"form": "潜移默化地", "label": "状语形式"}, {"form": "潜移默化的", "label": "定语形式"}], "register": "书面语", "sense_fingerprint": "自己没有发觉，却慢慢受到别人或环境的影响", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '9b63813c-68c7-48fa-8360-f041b5f6ea4e') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (22450, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "潜移默化", "is_correct": true, "explanation": "正确：“潜移默化地”表示慢慢在不自觉中爱上某事，与“跟朋友学”相合。"}, {"text": "刻意", "is_correct": false, "explanation": "语义：“刻意”指有意去做，与“不知不觉”地受影响的意思相反。"}, {"text": "立竿见影", "is_correct": false, "explanation": "搭配：“立竿见影”多用于效果显现，不用于爱上某项爱好的过程。"}, {"text": "大张旗鼓", "is_correct": false, "explanation": "语义：“大张旗鼓”指公开张扬，与“自己没有发觉”的意思相反。"}], "explanations": {"潜移默化": "正确：“潜移默化地”表示慢慢在不自觉中爱上某事，与“跟朋友学”相合。", "刻意": "语义：“刻意”指有意去做，与“不知不觉”地受影响的意思相反。", "立竿见影": "搭配：“立竿见影”多用于效果显现，不用于爱上某项爱好的过程。", "大张旗鼓": "语义：“大张旗鼓”指公开张扬，与“自己没有发觉”的意思相反。"}, "sentence_index": 0, "correct_answer": "潜移默化"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "我潜移默化地学习了跑步，每天练习。", "explanation": "这里应该用〈刻意〉。潜移默化指不知不觉中受影响，有目的地学习要用〈刻意〉。"}, {"text": "他潜移默化地拨通了报警电话。", "explanation": "这里应该用〈立刻〉。潜移默化指慢慢在不自觉中受影响，拨报警电话是有意的瞬间动作，不能用潜移默化。"}, {"text": "他潜移默化地打碎了杯子。", "explanation": "这里应该用〈故意〉。打碎杯子是有意的动作，潜移默化指不自觉的影响。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'ecdaac6c-e131-43d3-92f5-dda6f5f80093') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (22450, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "潜移默化", "is_correct": true, "explanation": "正确：“潜移默化地”表示在不知不觉中习惯了海的声音，与“住在海边”相合。"}, {"text": "骤然", "is_correct": false, "explanation": "语义：“骤然”指突然发生，习惯海的声音需要时间，不能骤然完成。"}, {"text": "立即", "is_correct": false, "explanation": "搭配：“立即”修饰瞬间的动作，不修饰“习惯”这类逐渐形成的状态。"}, {"text": "特意", "is_correct": false, "explanation": "语义：“特意”指有意去做，与“不知不觉”的意思相反。"}], "explanations": {"潜移默化": "正确：“潜移默化地”表示在不知不觉中习惯了海的声音，与“住在海边”相合。", "骤然": "语义：“骤然”指突然发生，习惯海的声音需要时间，不能骤然完成。", "立即": "搭配：“立即”修饰瞬间的动作，不修饰“习惯”这类逐渐形成的状态。", "特意": "语义：“特意”指有意去做，与“不知不觉”的意思相反。"}, "sentence_index": 6, "correct_answer": "潜移默化"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "他潜移默化地说出了答案。", "explanation": "这里应该用〈直接〉。潜移默化指慢慢在不自觉中受影响，说出答案要用〈直接〉。"}, {"text": "他潜移默化地跑完了全程。", "explanation": "这里应该用〈坚持〉。潜移默化指不自觉地慢慢受影响，跑完全程要靠有意识的坚持，不能说成潜移默化。"}, {"text": "他潜移默化地抢到了第一名。", "explanation": "这里应该用〈一下子〉。潜移默化指慢慢在不自觉中受影响，抢到第一名是瞬间的结果，不能用潜移默化。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'ecdaac6c-e131-43d3-92f5-dda6f5f80093') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (22450, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "她在书香家庭里潜移默化的爱上了阅读。", "corrected_sentence": "她在书香家庭里潜移默化地爱上了阅读。", "error_description": "状语标记错误：修饰动词“爱上”要用“地”，不能用“的”，应说“潜移默化地爱上”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'ecdaac6c-e131-43d3-92f5-dda6f5f80093') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (22450, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "环境对孩子的成长有潜移默化地作用。", "corrected_sentence": "环境对孩子的成长有潜移默化的作用。", "error_description": "修饰语错误：“潜移默化”修饰名词“作用”时要用“的”，不能用“地”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'ecdaac6c-e131-43d3-92f5-dda6f5f80093') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
