INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (22454, 1, 'prompt1_core', '{"pos": "名词", "semantic_class": "abstract", "definition": "指测量东西有多少、多大、多高的标准或结果。", "primary_collocate": null, "pronunciation": "dù liàng", "ipa": "tu˥˩ ljɑŋ˥˩", "syllable_count": 2, "sentences": [{"text": "这个度量是三米，不是两米。", "target_word": "度量", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "长度的度量要看尺子上的数字。", "target_word": "度量", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "不同国家用不同的度量。", "target_word": "度量", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这张桌子的度量是多少？", "target_word": "度量", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他记下了房间的度量。", "target_word": "度量", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "老师让我们写出每条边的度量。", "target_word": "度量", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "请告诉我这个箱子的度量。", "target_word": "度量", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "重量的度量，每个地方不太一样。", "target_word": "度量", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这块布的度量不对，做不了衣服。", "target_word": "度量", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "我们先量一下，再记下度量。", "target_word": "度量", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "度量衡", "label": "复合"}, {"form": "度量单位", "label": "复合"}], "register": "中性", "sense_fingerprint": "度量：测量大小多少的标准或结果", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '3dd671e0-53f7-42b7-bb84-bc75686d43c6') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (22454, 1, 'prompt2_exercises_A', '{"level_1": {"options": [{"text": "度量", "is_correct": true, "explanation": "度量 dù liàng：指测量多少、大小的标准或结果。"}, {"text": "大量", "is_correct": false, "explanation": "dà 与 dù 韵母不同（a 与 u），意思是数量多，不是标准或结果。"}, {"text": "数量", "is_correct": false, "explanation": "数量 shù liàng：声母是 sh，与 dù 的 d 不同，韵母与声调相同，意思是数目多少。"}, {"text": "多量", "is_correct": false, "explanation": "duō 与 dù 的韵母和声调都不同，意思是数量多。"}], "explanations": {"度量": "度量 dù liàng：指测量多少、大小的标准或结果。", "大量": "dà 与 dù 韵母不同（a 与 u），意思是数量多，不是标准或结果。", "数量": "数量 shù liàng：声母是 sh，与 dù 的 d 不同，韵母与声调相同，意思是数目多少。", "多量": "duō 与 dù 的韵母和声调都不同，意思是数量多。"}, "sentence_index": null, "correct_answer": "度量"}, "level_3": {"options": [{"text": "度量", "is_correct": true, "explanation": "「这个度量」指测得的大小结果，与「是三米」相符，句意通顺。"}, {"text": "颜色", "is_correct": false, "explanation": "语义：颜色不是长度，「颜色是三米」说不通。"}, {"text": "重量", "is_correct": false, "explanation": "语义：重量指轻重，不用米来计量，「重量是三米」与句意不符。"}, {"text": "年龄", "is_correct": false, "explanation": "搭配：「三米」不能用来说明年龄，「年龄是三米」搭配不当。"}], "explanations": {"度量": "「这个度量」指测得的大小结果，与「是三米」相符，句意通顺。", "颜色": "语义：颜色不是长度，「颜色是三米」说不通。", "重量": "语义：重量指轻重，不用米来计量，「重量是三米」与句意不符。", "年龄": "搭配：「三米」不能用来说明年龄，「年龄是三米」搭配不当。"}, "sentence_index": 0, "correct_answer": "度量"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "这双鞋的度量很舒服，我每天都穿。", "explanation": "这里应该用〈合脚〉。度量指测量得到的标准或结果，鞋子穿着合不合脚要说合脚，不能用度量来形容。"}, {"text": "我的度量是一位很好的朋友。", "explanation": "这里不能用度量指人。度量指测量得到的标准或结果；表示胸怀的“度量”是另一个义项，也不能说成“是一位朋友”。"}, {"text": "这次比赛的度量是冠军。", "explanation": "这里应该用〈成绩〉。度量指测量的标准或结果，比赛的名次要用成绩。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'bf1db7bd-d73c-42f3-a03b-50f946dbbbca') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (22454, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "度量", "is_correct": true, "explanation": "「箱子的度量」指测量得出的大小，与「告诉我」的语境相符。"}, {"text": "心情", "is_correct": false, "explanation": "语义：箱子没有心情，把「心情」说成箱子的，与句意不符。"}, {"text": "体温", "is_correct": false, "explanation": "搭配：箱子没有体温，「体温」不能用来形容箱子。"}, {"text": "语言", "is_correct": false, "explanation": "语义：箱子不会说话，「箱子的语言」与句意不符。"}], "explanations": {"度量": "「箱子的度量」指测量得出的大小，与「告诉我」的语境相符。", "心情": "语义：箱子没有心情，把「心情」说成箱子的，与句意不符。", "体温": "搭配：箱子没有体温，「体温」不能用来形容箱子。", "语言": "语义：箱子不会说话，「箱子的语言」与句意不符。"}, "sentence_index": 6, "correct_answer": "度量"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "这次考试的度量是两个小时。", "explanation": "这里应该用〈时长〉。度量指测量大小多少的标准或结果，考试的时间长短要用时长。"}, {"text": "这张照片的度量很漂亮。", "explanation": "这里应该用〈外观〉。度量指测量的标准或结果，照片好看要用外观来说。"}, {"text": "妈妈看了一眼汤，就度量出它的美味。", "explanation": "这里应该用〈品尝〉。度量用于长度、容量、重量等可测量的东西，汤的美味要靠品尝。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'bf1db7bd-d73c-42f3-a03b-50f946dbbbca') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (22454, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "这块木板度量是两米，请记下来。", "corrected_sentence": "这块木板的度量是两米，请记下来。", "error_description": "错误：「木板度量」。「木板」修饰「度量」，名词修饰名词时要在前面加「的」，应说「木板的度量」。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'bf1db7bd-d73c-42f3-a03b-50f946dbbbca') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (22454, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "我们记下了这把尺子地度量。", "corrected_sentence": "我们记下了这把尺子的度量。", "error_description": "「度量」在这里是名词，修饰它要用「的」，不用「地」（「地」只修饰动词），「尺子地度量」说不通。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'bf1db7bd-d73c-42f3-a03b-50f946dbbbca') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
