INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (22468, 1, 'llm_types_B', '{}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'bf1db7bd-d73c-42f3-a03b-50f946dbbbca') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (22468, 1, 'prompt1_core', '{"pos": "形容词", "semantic_class": "abstract", "definition": "不同地方的人一起学习对方的文化。", "primary_collocate": null, "pronunciation": "kuà wén huà", "ipa": "kʰua˥˩ wən˧˥ xua˥˩", "syllable_count": 3, "sentences": [{"text": "这个夏令营是跨文化的活动。", "target_word": "跨文化", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "跨文化学习让我们更了解彼此。", "target_word": "跨文化", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "我和中国朋友一起做跨文化的学习。", "target_word": "跨文化", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "她参加了一个跨文化项目。", "target_word": "跨文化", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "我们班有跨文化的交流活动。", "target_word": "跨文化", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "跨文化体验让他爱上了中国菜。", "target_word": "跨文化", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他们在跨文化的课上互相教语言。", "target_word": "跨文化", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这次跨文化旅行，我学会了做饺子。", "target_word": "跨文化", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "学校办了跨文化周，大家带来了各国的菜。", "target_word": "跨文化", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这个跨文化社团每周都会一起学习各国的文化。", "target_word": "跨文化", "complexity_tier": "T3", "furigana": "zhè ge kuà wén huà shè tuán měi zhōu dōu huì yì qǐ xué xí gè guó de wén huà", "sentence_source": "generated"}], "morphological_forms": [{"form": "跨文化交流", "label": "复合"}, {"form": "跨文化学习", "label": "复合"}], "register": "中性", "sense_fingerprint": "跨文化：不同地方的人一起学习对方的文化", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '3dd671e0-53f7-42b7-bb84-bc75686d43c6') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (22468, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "跨文化", "is_correct": true, "explanation": "「跨文化的活动」指不同地方的人一起学习对方文化的活动，与「夏令营」相符。"}, {"text": "液态", "is_correct": false, "explanation": "语义：夏令营是人的活动，不能说成液态的活动，句意不通。"}, {"text": "灰色", "is_correct": false, "explanation": "体貌：「灰色」形容颜色，与「活动」搭配不通，句意不通。"}, {"text": "高温", "is_correct": false, "explanation": "语义：「高温的活动」指天气，与夏令营的文化学习无关。"}], "explanations": {"跨文化": "「跨文化的活动」指不同地方的人一起学习对方文化的活动，与「夏令营」相符。", "液态": "语义：夏令营是人的活动，不能说成液态的活动，句意不通。", "灰色": "体貌：「灰色」形容颜色，与「活动」搭配不通，句意不通。", "高温": "语义：「高温的活动」指天气，与夏令营的文化学习无关。"}, "sentence_index": 0, "correct_answer": "跨文化"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "她跨文化地读完了这本书。", "explanation": "这里应该用〈认真〉。跨文化修饰的是不同地方的人一起学习对方文化的活动，读书是个人行为，不能用跨文化地修饰。"}, {"text": "她参加了一个跨文化的体检。", "explanation": "这里应该用〈例行〉。跨文化修饰交流、学习这类活动，体检属于医疗检查，不能用跨文化修饰。"}, {"text": "他的跨文化很简单，每天只吃一顿饭。", "explanation": "这里应该用〈饮食〉。跨文化指不同地方的人一起学习对方文化的活动，一日三餐的习惯要用饮食来说。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'bf1db7bd-d73c-42f3-a03b-50f946dbbbca') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (22468, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "跨文化", "is_correct": true, "explanation": "「跨文化的课」指学习不同文化的课，与「互相教语言」的语境相符。"}, {"text": "无线", "is_correct": false, "explanation": "语义：「无线的课」不是指课程的性质，与句意不符。"}, {"text": "冰冻", "is_correct": false, "explanation": "语义：「冰冻的课」不成立，与互相教语言无关。"}, {"text": "食用", "is_correct": false, "explanation": "搭配：「食用」不能修饰「课」，「食用的课」说不通。"}], "explanations": {"跨文化": "「跨文化的课」指学习不同文化的课，与「互相教语言」的语境相符。", "无线": "语义：「无线的课」不是指课程的性质，与句意不符。", "冰冻": "语义：「冰冻的课」不成立，与互相教语言无关。", "食用": "搭配：「食用」不能修饰「课」，「食用的课」说不通。"}, "sentence_index": 6, "correct_answer": "跨文化"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "这个社团每周都会用跨文化的货车运送各国的货物。", "explanation": "这里应该用〈跨境〉。跨文化修饰的是交流、学习的活动，修饰货车、运送货物要用跨境。"}, {"text": "跨文化每周都会一起学习各国的文化。", "explanation": "这里应该用〈社团〉。跨文化描述的是活动的性质，不能充当学习的主语，主语要用社团这样的人或组织。"}, {"text": "这个社团每周都会去操场练跑步，跨文化得满头大汗。", "explanation": "这里应该用〈累〉。跨文化修饰交流、学习类的活动，不能用来描述跑步的累。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'bf1db7bd-d73c-42f3-a03b-50f946dbbbca') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (22468, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "我们班的跨文化地项目很受欢迎。", "corrected_sentence": "我们班的跨文化项目很受欢迎。", "error_description": "「跨文化」修饰名词「项目」要用「的」，不用「地」（「地」修饰动词）。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'bf1db7bd-d73c-42f3-a03b-50f946dbbbca') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (22468, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "我们参加了一本跨文化活动。", "corrected_sentence": "我们参加了一次跨文化活动。", "error_description": "活动的量词应用「次」，不用「本」（「本」用于书籍等）。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'bf1db7bd-d73c-42f3-a03b-50f946dbbbca') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
