INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (22470, 1, 'prompt1_core', '{"pos": "名词", "semantic_class": "concrete", "definition": "有用的东西很少，不够大家用。", "primary_collocate": null, "pronunciation": "xī quē zī yuán", "ipa": "ɕi⁵⁵ tɕʰɥe⁵⁵ tsɹ̩⁵⁵ ɥɛn³⁵", "syllable_count": 4, "sentences": [{"text": "在沙漠里，水是稀缺资源。", "target_word": "稀缺资源", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "这个小岛上，淡水是稀缺资源。", "target_word": "稀缺资源", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "冬天，新鲜蔬菜成了稀缺资源。", "target_word": "稀缺资源", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "我们学校机房少，上机的名额是稀缺资源。", "target_word": "稀缺资源", "complexity_tier": "T3", "furigana": "xī quē zī yuán", "sentence_source": "generated"}, {"text": "考试前，安静的座位成了稀缺资源。", "target_word": "稀缺资源", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "对穷国来说，干净的水是稀缺资源。", "target_word": "稀缺资源", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "地球上的石油是稀缺资源，我们要节约使用。", "target_word": "稀缺资源", "complexity_tier": "T3", "furigana": "xī quē zī yuán", "sentence_source": "generated"}, {"text": "过年回家时，车票是稀缺资源。", "target_word": "稀缺资源", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "山区缺医少药，医疗设备是稀缺资源。", "target_word": "稀缺资源", "complexity_tier": "T3", "furigana": "xī quē zī yuán", "sentence_source": "generated"}, {"text": "他说，好老师是学校的稀缺资源。", "target_word": "稀缺资源", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "种", "label": "量词"}, {"form": "稀缺資源", "label": "繁体"}], "register": "中性", "sense_fingerprint": "日常意义上数量很少、不够大家使用的有用东西", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'b1532fc7-f679-448f-975d-e35ead7876dd') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (22470, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "稀缺资源", "is_correct": true, "explanation": "正确：沙漠里的水数量很少、不够使用，符合“稀缺资源”的意思。"}, {"text": "天空", "is_correct": false, "explanation": "语义：天空是自然景观，不能说“水是天空”，与“水”作为有用东西的语境冲突。"}, {"text": "玩意儿", "is_correct": false, "explanation": "语域：“玩意儿”是口语、随意的说法，不能用来指沙漠中珍贵的水。"}, {"text": "颜色", "is_correct": false, "explanation": "语义：颜色不是有用的东西，“水是颜色”与句意不符。"}], "explanations": {"稀缺资源": "正确：沙漠里的水数量很少、不够使用，符合“稀缺资源”的意思。", "天空": "语义：天空是自然景观，不能说“水是天空”，与“水”作为有用东西的语境冲突。", "玩意儿": "语域：“玩意儿”是口语、随意的说法，不能用来指沙漠中珍贵的水。", "颜色": "语义：颜色不是有用的东西，“水是颜色”与句意不符。"}, "sentence_index": 0, "correct_answer": "稀缺资源"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "夏天雨水很多，河里湖里到处都是水，水成了稀缺资源。", "explanation": "这里应该用〈充足〉。稀缺资源指有用的东西很少、不够大家用；水源充足时，水不是稀缺资源。"}, {"text": "学校买了一张稀缺资源。", "explanation": "这里应该用〈种〉。资源是抽象名词，不能用“张”，“张”多用于平面的、扁的东西。"}, {"text": "这个城市的超市遍地都是，牛奶人人买得到，牛奶成了稀缺资源。", "explanation": "这里应该用〈普通〉。稀缺资源指数量少、不够用；人人买得到的牛奶属于普通商品，不是稀缺资源。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'a3efeaae-98b1-4058-8d03-9b7bda897c88') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (22470, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "稀缺资源", "is_correct": true, "explanation": "正确：石油数量有限、难以替代，所以需要节约使用，符合“稀缺资源”的意思。"}, {"text": "饮料", "is_correct": false, "explanation": "语义：石油不是饮料，“石油是饮料”与句中“节约使用”的语境冲突。"}, {"text": "晚餐", "is_correct": false, "explanation": "语义：晚餐是一顿饭，不是需要节约使用的资源，与“石油”的语境不符。"}, {"text": "玩具", "is_correct": false, "explanation": "语义：玩具不是能源，与“石油”及“节约使用”的语境冲突。"}], "explanations": {"稀缺资源": "正确：石油数量有限、难以替代，所以需要节约使用，符合“稀缺资源”的意思。", "饮料": "语义：石油不是饮料，“石油是饮料”与句中“节约使用”的语境冲突。", "晚餐": "语义：晚餐是一顿饭，不是需要节约使用的资源，与“石油”的语境不符。", "玩具": "语义：玩具不是能源，与“石油”及“节约使用”的语境冲突。"}, "sentence_index": 6, "correct_answer": "稀缺资源"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "公园里的空气到处都是，它是稀缺资源。", "explanation": "这里应该用〈普遍〉。稀缺资源指有用的东西很少、不够大家用；随处可得的空气不属于稀缺资源。"}, {"text": "这场比赛的门票很多，人人都买得到，门票是稀缺资源。", "explanation": "这里应该用〈富余〉。稀缺资源指数量少、不够大家用；门票人人买得到时，它并不稀缺。"}, {"text": "这次考试很简单，人人都得满分，满分成了稀缺资源。", "explanation": "这里应该用〈常见〉。稀缺资源指数量少、不够大家用；人人都能拿到的满分不属于稀缺资源。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'a3efeaae-98b1-4058-8d03-9b7bda897c88') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (22470, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "这个小岛上，淡水是一只稀缺资源。", "corrected_sentence": "这个小岛上，淡水是一种稀缺资源。", "error_description": "量词错误：“只”多用于动物或成对物品中的一个，“资源”应用“种”，正确说法是“一种稀缺资源”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'a3efeaae-98b1-4058-8d03-9b7bda897c88') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (22470, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "在山里，清澈的泉水稀缺资源。", "corrected_sentence": "在山里，清澈的泉水是稀缺资源。", "error_description": "漏掉判断动词“是”：“稀缺资源”作谓语时要带“是”，应说“泉水是稀缺资源”，不能直接说“泉水稀缺资源”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'a3efeaae-98b1-4058-8d03-9b7bda897c88') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
