INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (22472, 1, 'prompt1_core', '{"pos": "形容词", "semantic_class": "property", "definition": "像一条直线一样，没有弯曲。", "primary_collocate": null, "pronunciation": "xiàn xìng", "ipa": "ɕjɛn˥˩ ɕiŋ˥˩", "syllable_count": 2, "sentences": [{"text": "这张图上的线性关系很清楚。", "target_word": "线性", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "水温和时间是线性关系。", "target_word": "线性", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这家公司的收入是线性增长的。", "target_word": "线性", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这个问题可以用线性方程来解。", "target_word": "线性", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "汽车匀速开，路程的变化是线性的。", "target_word": "线性", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这个图是线性的，所以线是直的。", "target_word": "线性", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他的进步不是线性的，有高有低。", "target_word": "线性", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "弹簧拉长的长度和力是线性关系。", "target_word": "线性", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "数学课上我们学了线性函数。", "target_word": "线性", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这种变化是线性的，图上看是直线。", "target_word": "线性", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "线性的", "label": "的字结构"}, {"form": "非线性", "label": "否定形式"}], "register": "书面语", "sense_fingerprint": "线性：像直线一样，没有弯曲，多用于数学、科学", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'fd8ccd27-d9af-45a9-8d08-de0015174fd9') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (22472, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "线性", "is_correct": true, "explanation": "线性指两个量之间呈直线关系，图上可以清楚看出，符合“关系很清楚”的语境。"}, {"text": "模糊", "is_correct": false, "explanation": "语义：“模糊”与“关系很清楚”相矛盾。"}, {"text": "隐晦", "is_correct": false, "explanation": "语义：“隐晦”与“关系很清楚”相矛盾。"}, {"text": "随机", "is_correct": false, "explanation": "语义：“随机”指没有规律，与“关系很清楚”相矛盾。"}], "explanations": {"线性": "线性指两个量之间呈直线关系，图上可以清楚看出，符合“关系很清楚”的语境。", "模糊": "语义：“模糊”与“关系很清楚”相矛盾。", "隐晦": "语义：“隐晦”与“关系很清楚”相矛盾。", "随机": "语义：“随机”指没有规律，与“关系很清楚”相矛盾。"}, "sentence_index": 0, "correct_answer": "线性"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "这只猫的叫声很线性。", "explanation": "这里应该用〈响亮〉。线性只描述数量或图形之间的关系，不形容声音，猫叫要说“响亮”。"}, {"text": "这次考试的线性很高。", "explanation": "这里应该用〈成绩〉。线性不用于形容考试的分数，分数要说“成绩”。"}, {"text": "这台机器运行很线性。", "explanation": "这里应该用〈稳定〉。线性不用于形容机器的运行状态，这里应该说“稳定”。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'ee911bcc-5f51-4212-b250-ee73f2686fed') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (22472, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "线性", "is_correct": true, "explanation": "线性指数量之间的直线关系，用在这里描述进步的规律，符合语境。"}, {"text": "平等", "is_correct": false, "explanation": "搭配：“平等”描述人与人之间的关系，不用来形容进步。"}, {"text": "可怕", "is_correct": false, "explanation": "语义：进步是积极的，不能说“可怕”，与语境相矛盾。"}, {"text": "无聊", "is_correct": false, "explanation": "语义：进步不是无聊的状态，与“进步”的积极含义相矛盾。"}], "explanations": {"线性": "线性指数量之间的直线关系，用在这里描述进步的规律，符合语境。", "平等": "搭配：“平等”描述人与人之间的关系，不用来形容进步。", "可怕": "语义：进步是积极的，不能说“可怕”，与语境相矛盾。", "无聊": "语义：进步不是无聊的状态，与“进步”的积极含义相矛盾。"}, "sentence_index": 6, "correct_answer": "线性"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "这顿饭的味道很线性。", "explanation": "这里应该用〈鲜美〉。线性只指数量或图形之间的关系，不能形容味道。"}, {"text": "他的表情很线性。", "explanation": "这里应该用〈呆板〉。线性不形容人的表情，只描述数量或图形之间的关系。"}, {"text": "这面墙的颜色涂得很线性。", "explanation": "这里应该用〈均匀〉。线性指数量之间的关系，不用来形容颜色涂抹的均匀程度。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'ee911bcc-5f51-4212-b250-ee73f2686fed') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (22472, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "这个规律线性的。", "corrected_sentence": "这个规律是线性的。", "error_description": "句式错误：“线性的”作谓语时缺少“是”，应说“这个规律是线性的”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'ee911bcc-5f51-4212-b250-ee73f2686fed') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (22472, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "这两个量之间是很线性关系。", "corrected_sentence": "这两个量之间是线性关系。", "error_description": "程度错误：“线性关系”中的“线性”作定语修饰“关系”，不能受程度副词“很”修饰，应说“是线性关系”。正确为“这两个量之间是线性关系。”", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'ee911bcc-5f51-4212-b250-ee73f2686fed') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
