INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (22486, 1, 'prompt1_core', '{"pos": "动词", "semantic_class": "action", "definition": "把测量工具上的数字和标准对比，让它们一样准。", "primary_collocate": null, "pronunciation": "jiào zhǔn", "ipa": "tɕiɑʊ̯˥˩ ʈʂuən˨˩˦", "syllable_count": 2, "sentences": [{"text": "请用标准砝码校准这个秤。", "target_word": "校准", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他校准了那支温度计。", "target_word": "校准", "complexity_tier": "T3", "furigana": "tā jiào zhǔn le nà zhī wēn dù jì", "sentence_source": "generated"}, {"text": "妈妈用旧体温计校准了新的。", "target_word": "校准", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "商店每个月都要校准电子秤。", "target_word": "校准", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "修理师傅正在校准汽车的速度表。", "target_word": "校准", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "校准以后，两把尺子的数字一样了。", "target_word": "校准", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "老师教我们怎么校准天平。", "target_word": "校准", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这块表慢了，我要把它校准。", "target_word": "校准", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "校准时要对照标准值。", "target_word": "校准", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "他把电表重新校准了一遍。", "target_word": "校准", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "校准了", "label": "体标（了）"}, {"form": "校准过", "label": "体标（过）"}, {"form": "校准好", "label": "结果补语（好）"}], "register": "中性", "sense_fingerprint": "校准：把测量工具的读数和标准对比使之准确", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '9bf20c0d-3c61-4a52-8a10-ec6c7498801e') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (22486, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "校准", "is_correct": true, "explanation": "校准：用标准砝码比照，使秤的读数准确，与句意相符。"}, {"text": "擦拭", "is_correct": false, "explanation": "语义：擦拭是擦去灰尘或污渍，与用标准砝码让秤的读数准确无关。"}, {"text": "包装", "is_correct": false, "explanation": "搭配：包装指把物品装进包装物，不能说“用标准砝码包装秤”。"}, {"text": "购买", "is_correct": false, "explanation": "配价：购买的必要成分是买主和所买的商品，“标准砝码”不能充当它的成分。"}], "explanations": {"校准": "校准：用标准砝码比照，使秤的读数准确，与句意相符。", "擦拭": "语义：擦拭是擦去灰尘或污渍，与用标准砝码让秤的读数准确无关。", "包装": "搭配：包装指把物品装进包装物，不能说“用标准砝码包装秤”。", "购买": "配价：购买的必要成分是买主和所买的商品，“标准砝码”不能充当它的成分。"}, "sentence_index": 0, "correct_answer": "校准"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "请校准一下这份账单，看看有没有算错。", "explanation": "这里应该用〈核对〉。校准用于让测量仪器的读数与标准一致，检查账单有没有算错要用〈核对〉。"}, {"text": "这篇文章错别字很多，需要校准一下。", "explanation": "这里应该用〈校对〉。校准针对测量仪器，改正文章里的错别字要用〈校对〉。"}, {"text": "我把头发校准得很整齐。", "explanation": "这里应该用〈梳理〉。校准用于测量仪器的读数，整理头发要用〈梳理〉。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '123cdbe1-3f2b-4a56-b0ff-c1ffedab4432') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (22486, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "校准", "is_correct": true, "explanation": "校准：让天平的读数与标准一致，符合“老师教我们怎么”的句意。"}, {"text": "烹饪", "is_correct": false, "explanation": "搭配：烹饪的对象是食物，不能用于天平。"}, {"text": "饲养", "is_correct": false, "explanation": "搭配：饲养的对象是动植物，天平不能被饲养。"}, {"text": "切割", "is_correct": false, "explanation": "语义：切割是把东西割开，与让天平读数准确的意思完全不符。"}], "explanations": {"校准": "校准：让天平的读数与标准一致，符合“老师教我们怎么”的句意。", "烹饪": "搭配：烹饪的对象是食物，不能用于天平。", "饲养": "搭配：饲养的对象是动植物，天平不能被饲养。", "切割": "语义：切割是把东西割开，与让天平读数准确的意思完全不符。"}, "sentence_index": 6, "correct_answer": "校准"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "医生正在校准那位病人。", "explanation": "这里应该用〈诊断〉。校准是把测量工具的读数对齐标准，用在人身上不通；判断病人的病情要用〈诊断〉。"}, {"text": "工人正在校准那堵墙。", "explanation": "这里应该用〈粉刷〉。校准只用于测量器具的读数，给墙面涂饰要用〈粉刷〉。"}, {"text": "妈妈校准了那只小狗。", "explanation": "这里应该用〈训练〉。校准只用于测量工具的读数，让小狗学会听指令要用〈训练〉。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '123cdbe1-3f2b-4a56-b0ff-c1ffedab4432') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (22486, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "工人明天校准了这台秤。", "corrected_sentence": "工人明天校准这台秤。", "error_description": "错误：“校准了”，正确：“校准”。“明天”指将来，动作还没有发生，动词后不能用“了”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '123cdbe1-3f2b-4a56-b0ff-c1ffedab4432') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (22486, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "我已经把这台天平校准了好。", "corrected_sentence": "我已经把这台天平校准好了。", "error_description": "语序错误：结果补语“好”应紧接动词“校准”，“了”放在句尾，应说“校准好了”，不能说“校准了好”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '123cdbe1-3f2b-4a56-b0ff-c1ffedab4432') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
