INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (22494, 1, 'llm_types_B', '{}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'e0dd51db-3c3a-4cb2-b11a-a4fe275f2fbc') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (22494, 1, 'prompt1_core', '{"pos": "名词", "semantic_class": "abstract", "definition": "每天要做的事情的安排表。", "primary_collocate": null, "pronunciation": "rì chéng", "ipa": "ʐʅ˥˩ ʈʂʰɤŋ˧˥", "syllable_count": 2, "sentences": [{"text": "我昨天的日程很满，没时间吃饭。", "target_word": "日程", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他每天看一遍日程，不会忘事。", "target_word": "日程", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "手机里的日程提醒我八点开会。", "target_word": "日程", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这是我今天的日程，上午有两个会。", "target_word": "日程", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "妈妈把全家的日程贴在冰箱上。", "target_word": "日程", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "孩子的日程里有钢琴课和游泳课。", "target_word": "日程", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "我每天早上先查看日程。", "target_word": "日程", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "你可以把新任务加到日程里。", "target_word": "日程", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他每天的日程很简单：上班、回家、睡觉。", "target_word": "日程", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "周末我的日程是空的，可以见面。", "target_word": "日程", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "日程表", "label": "复合"}, {"form": "日程安排", "label": "复合"}], "register": "中性", "sense_fingerprint": "日程：每天要做的事情的安排", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '2c0316e5-c34c-466b-b987-b6779688b332') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (22494, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "钱包", "is_correct": false, "explanation": "语义：“很满”说钱包装得多，与“没时间吃饭”所表达的忙碌无关。"}, {"text": "日程", "is_correct": true, "explanation": "“我昨天的日程很满”指昨天安排得满，与“没时间吃饭”前后呼应。"}, {"text": "食谱", "is_correct": false, "explanation": "语义：“食谱”是菜谱，“很满”与“没时间吃饭”的因果不通。"}, {"text": "戒指", "is_correct": false, "explanation": "搭配：“戒指”不能说“很满”，搭配不当。"}], "explanations": {"钱包": "语义：“很满”说钱包装得多，与“没时间吃饭”所表达的忙碌无关。", "日程": "“我昨天的日程很满”指昨天安排得满，与“没时间吃饭”前后呼应。", "食谱": "语义：“食谱”是菜谱，“很满”与“没时间吃饭”的因果不通。", "戒指": "搭配：“戒指”不能说“很满”，搭配不当。"}, "sentence_index": 0, "correct_answer": "日程"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "我今天的日程很便宜。", "explanation": "这里形容词用错。日程指安排，不能说“便宜”。"}, {"text": "我今天有一条日程很重要。", "explanation": "这里量词用错。日程要用〈项〉或〈个〉，〈条〉用于路、消息等细长的东西。"}, {"text": "我每天睡前写日程记录心情。", "explanation": "这里应该用〈日记〉。记录心情用日记；日程是要做的安排，不能用来写心情。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'e0dd51db-3c3a-4cb2-b11a-a4fe275f2fbc') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (22494, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "味道", "is_correct": false, "explanation": "搭配：“查看”的对象是具体的信息或事物，不能查看“味道”。"}, {"text": "日程", "is_correct": true, "explanation": "“查看日程”指查看当天要做的安排，与“每天早上先”相合。"}, {"text": "颜色", "is_correct": false, "explanation": "搭配：“查看颜色”搭配生硬，也与“每天早上先”的语境不呼应。"}, {"text": "脾气", "is_correct": false, "explanation": "语义：“脾气”不是可以查看的安排信息，句意不通。"}], "explanations": {"味道": "搭配：“查看”的对象是具体的信息或事物，不能查看“味道”。", "日程": "“查看日程”指查看当天要做的安排，与“每天早上先”相合。", "颜色": "搭配：“查看颜色”搭配生硬，也与“每天早上先”的语境不呼应。", "脾气": "语义：“脾气”不是可以查看的安排信息，句意不通。"}, "sentence_index": 6, "correct_answer": "日程"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "他把日程喝光了。", "explanation": "搭配不当：“喝”的对象应是饮品，日程不能喝。"}, {"text": "我今天没有日程吃午饭。", "explanation": "这里应该用〈时间〉。“没有时间”说没有空闲，“日程”指已经安排好的事项，不能用来表示有没有空。"}, {"text": "明天下午我和客户有个日程，不能迟到。", "explanation": "这里应该用〈约会〉。与客户见面是一次具体的会面，用约会；日程是一段时间内全部安排的总称，不说“有个日程”。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'e0dd51db-3c3a-4cb2-b11a-a4fe275f2fbc') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (22494, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "妈妈帮我整理了一把日程。", "corrected_sentence": "妈妈帮我整理了一份日程。", "error_description": "量词错误：“日程”不能用“把”（“把”用于有柄、可握的东西）。正确说法：一份日程。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'e0dd51db-3c3a-4cb2-b11a-a4fe275f2fbc') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (22494, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "这块日程我已经看过了。", "corrected_sentence": "这个日程我已经看过了。", "error_description": "量词错误：“日程”不能用“块”（“块”用于成片的东西，如土地、肥皂）。正确说法：这个日程。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'e0dd51db-3c3a-4cb2-b11a-a4fe275f2fbc') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
