INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (22506, 1, 'prompt1_core', '{"pos": "动词", "semantic_class": "action", "definition": "让一件事变成常常这样做，有固定的规则。", "primary_collocate": null, "pronunciation": "zhì dù huà", "ipa": "ʈʂɻ̩˥˩ tu˥˩ xua˥˩", "syllable_count": 3, "sentences": [{"text": "公司把每周开会制度化了。", "target_word": "制度化", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "老师想把读书时间制度化。", "target_word": "制度化", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "我们把打扫卫生制度化，每人轮流做。", "target_word": "制度化", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这家店把试吃活动制度化了。", "target_word": "制度化", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "家长会应该制度化，一学期开两次。", "target_word": "制度化", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "他们把周五聚餐制度化，已经三年了。", "target_word": "制度化", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "小组决定把互相检查制度化。", "target_word": "制度化", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "学校把早读制度化后，学生进步很快。", "target_word": "制度化", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这种交流最好制度化，每月都要有。", "target_word": "制度化", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "运动不容易坚持，所以他把跑步制度化。", "target_word": "制度化", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "制度化了", "label": "体标"}], "register": "中性", "sense_fingerprint": "让一件事固定下来，按规则经常做", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '9ba9e274-b8ab-4e4c-bbe4-4a904cae9285') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (22506, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "制度化", "is_correct": true, "explanation": "制度化指让一件事固定下来、按规则经常做，与“公司把每周开会……了”相符。"}, {"text": "随机化", "is_correct": false, "explanation": "语义：随机化与“每周”的固定周期相反。"}, {"text": "零散化", "is_correct": false, "explanation": "语义：零散化指分散、不成体系，与“每周开会”的固定安排相反。"}, {"text": "节日化", "is_correct": false, "explanation": "搭配：节日化指变得像节日一样，不能用来形容“开会”这种安排。"}], "explanations": {"制度化": "制度化指让一件事固定下来、按规则经常做，与“公司把每周开会……了”相符。", "随机化": "语义：随机化与“每周”的固定周期相反。", "零散化": "语义：零散化指分散、不成体系，与“每周开会”的固定安排相反。", "节日化": "搭配：节日化指变得像节日一样，不能用来形容“开会”这种安排。"}, "sentence_index": 0, "correct_answer": "制度化"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "这家店的餐具每次都不一样，已经制度化了。", "explanation": "这里应该用〈随意〉。制度化指把做法固定下来，每次都不一样与之矛盾。"}, {"text": "他昨天写了一封信，已经制度化了。", "explanation": "这里应该用〈完成〉。制度化指让一件事变成常规，只做过一次的事不能说制度化，应说完成。"}, {"text": "他的心情很制度化。", "explanation": "这里应该用〈平静〉。制度化不能形容人的心情，心情的状态要说平静。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '7deeda03-da33-4b74-a27c-2bf61f5f2016') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (22506, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "制度化", "is_correct": true, "explanation": "制度化指把某件事固定为有规则的做法，与“小组决定把互相检查……”相符。"}, {"text": "商业化", "is_correct": false, "explanation": "语义：商业化指变成买卖营利的事，与小组内部互相检查的做法无关。"}, {"text": "闲置化", "is_correct": false, "explanation": "语义：闲置化指搁置不用，与小组主动决定推行检查的意图相反。"}, {"text": "口语化", "is_correct": false, "explanation": "搭配：口语化指用口语表达，不能和“检查”搭配。"}], "explanations": {"制度化": "制度化指把某件事固定为有规则的做法，与“小组决定把互相检查……”相符。", "商业化": "语义：商业化指变成买卖营利的事，与小组内部互相检查的做法无关。", "闲置化": "语义：闲置化指搁置不用，与小组主动决定推行检查的意图相反。", "口语化": "搭配：口语化指用口语表达，不能和“检查”搭配。"}, "sentence_index": 6, "correct_answer": "制度化"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "爱迪生制度化了电灯。", "explanation": "这里应该用〈发明〉。制度化指把做法或规则固定下来，不能用于具体器物的创造。"}, {"text": "她的脾气很制度化。", "explanation": "这里应该用〈温和〉。制度化不能形容性格或脾气。"}, {"text": "他把跑步路线制度化了，但每天都换。", "explanation": "这里应该用〈变动〉。制度化要求固定不变，每天都换与之矛盾。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '7deeda03-da33-4b74-a27c-2bf61f5f2016') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (22506, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "老师已经把读书时间制度化。", "corrected_sentence": "老师已经把读书时间制度化了。", "error_description": "漏掉了“了”。“已经”表示已完成，句末要用“了”，应说“把读书时间制度化了”，不能说“把读书时间制度化”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '7deeda03-da33-4b74-a27c-2bf61f5f2016') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (22506, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "小组很快把互相检查制度化的。", "corrected_sentence": "小组很快把互相检查制度化了。", "error_description": "“了”误用为“的”。正确形式是“制度化了”，表示动作完成；“制度化的”不能结束把字句，应改为“制度化了”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '7deeda03-da33-4b74-a27c-2bf61f5f2016') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
