INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (22508, 1, 'prompt1_core', '{"pos": "情态动词", "semantic_class": "function", "definition": "表示不可以，用来告诉别人不能做某事。", "primary_collocate": null, "pronunciation": "bù kě", "ipa": "pu⁵¹ kʰɤ²¹⁴", "syllable_count": 2, "sentences": [{"text": "小朋友，这里很危险，你不可进去。", "target_word": "不可", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "火车还没停，你不可下车。", "target_word": "不可", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "别人的东西，你不可乱拿。", "target_word": "不可", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这个门坏了，大家不可用力推。", "target_word": "不可", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "孩子们，上课时不可玩手机。", "target_word": "不可", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "明天要考试，今晚你不可太晚睡。", "target_word": "不可", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "妈妈说，生水不可直接喝。", "target_word": "不可", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "病还没好，你不可吃冰的东西。", "target_word": "不可", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "开车前不可喝酒，这很重要。", "target_word": "不可", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这件事很重要，你不可告诉别人。", "target_word": "不可", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [], "register": "书面语", "sense_fingerprint": "情态动词，书面，对别人提醒或劝告不能做某事", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '281d9421-fb6f-489e-9c50-1dff686839f2') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (22508, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "不可", "is_correct": true, "explanation": "正确：「不可」表示劝阻不能做某事，与“这里很危险”的提醒语境相符。"}, {"text": "必须", "is_correct": false, "explanation": "语义：「必须」表示必要，填入后变成“你必须进去”，与“这里很危险”的劝阻矛盾。"}, {"text": "可以", "is_correct": false, "explanation": "语义：「可以」表示允许，填入后变成“你可以进去”，与前面提醒危险的语气矛盾。"}, {"text": "要", "is_correct": false, "explanation": "语域：「要」口语化，且表示打算，与书面劝阻的语气不一致，句意也与“很危险”冲突。"}], "explanations": {"不可": "正确：「不可」表示劝阻不能做某事，与“这里很危险”的提醒语境相符。", "必须": "语义：「必须」表示必要，填入后变成“你必须进去”，与“这里很危险”的劝阻矛盾。", "可以": "语义：「可以」表示允许，填入后变成“你可以进去”，与前面提醒危险的语气矛盾。", "要": "语域：「要」口语化，且表示打算，与书面劝阻的语气不一致，句意也与“很危险”冲突。"}, "sentence_index": 0, "correct_answer": "不可"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "这个门还能开，大家不可试试。", "explanation": "这里应该用〈不妨〉，表示可以试一试；不可表示禁止，与“还能开”的语境相反。"}, {"text": "这是一个好消息，大家不可高兴。", "explanation": "这里应该用〈不禁〉，表示忍不住地高兴；“不可”表示禁止，说“不可高兴”把自然的情绪说成了禁令，句意不通。"}, {"text": "大家忙得不可开交，没人去开门。", "explanation": "这里是“不可开交”的固定用法，表示非常忙碌，不表示禁止或不能；此句的“不可”与禁止义项无关。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '9affae7e-c415-4850-84d6-4a2bebe3b2f2') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (22508, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "不可", "is_correct": true, "explanation": "正确：「不可」表示禁止，与“妈妈说”的劝告和生水需要避免的语境相符。"}, {"text": "应该", "is_correct": false, "explanation": "语义：「应该」表示按道理应当，填入后变成“生水应该直接喝”，与“妈妈说”的劝告和卫生常识相反。"}, {"text": "敢", "is_correct": false, "explanation": "搭配：「敢」要求有人作主语、表示有胆量，不能以无生命的“生水”作主语，说“生水敢直接喝”不成立。"}, {"text": "会", "is_correct": false, "explanation": "语义：「会」表示将要或可能，填入后变成“生水会直接喝”，是预测而非劝阻，与“妈妈说”的告诫语境不合。"}], "explanations": {"不可": "正确：「不可」表示禁止，与“妈妈说”的劝告和生水需要避免的语境相符。", "应该": "语义：「应该」表示按道理应当，填入后变成“生水应该直接喝”，与“妈妈说”的劝告和卫生常识相反。", "敢": "搭配：「敢」要求有人作主语、表示有胆量，不能以无生命的“生水”作主语，说“生水敢直接喝”不成立。", "会": "语义：「会」表示将要或可能，填入后变成“生水会直接喝”，是预测而非劝阻，与“妈妈说”的告诫语境不合。"}, "sentence_index": 6, "correct_answer": "不可"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "这个笑话很好笑，大家不可笑。", "explanation": "这里应该用〈不禁〉，表示忍不住而笑；不可表示禁止，与“很好笑”的语境矛盾，把自然的笑说成了“不许笑”。"}, {"text": "他一直很骄傲，总是不可理睬别人。", "explanation": "这里应该用〈不屑〉，表示看不起而不予理会；不可表示禁止，与“骄傲”的态度不合。"}, {"text": "孩子哭得很厉害，大家不可安慰他。", "explanation": "这里应该用〈不忍〉，表示心里不忍心；不可表示禁止，把“不忍”说成了“不许安慰”，与语境不合。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '9affae7e-c415-4850-84d6-4a2bebe3b2f2') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (22508, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "这个电梯坏了，大家不可了乘坐。", "corrected_sentence": "这个电梯坏了，大家不可乘坐。", "error_description": "「不可」是情态动词，后面不能直接加动态助词「了」，应删去「了」，说「大家不可乘坐」。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '9affae7e-c415-4850-84d6-4a2bebe3b2f2') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (22508, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "过马路时，孩子们很不可乱跑。", "corrected_sentence": "过马路时，孩子们不可乱跑。", "error_description": "“不可”不能受程度副词“很”修饰，应删去“很”，说“过马路时，孩子们不可乱跑”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '9affae7e-c415-4850-84d6-4a2bebe3b2f2') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
