INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (22514, 1, 'prompt1_core', '{"pos": "名词", "semantic_class": "concrete", "definition": "可以装东西的盒子、瓶子等。", "primary_collocate": null, "pronunciation": "róng qì", "ipa": "ɻʊŋ˧˥ tɕʰi˥˩", "syllable_count": 2, "sentences": [{"text": "这个容器可以装水，也可以装米。", "target_word": "容器", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "请把食物放进干净的容器里。", "target_word": "容器", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这种塑料容器很轻，孩子也能拿。", "target_word": "容器", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "我买了几个玻璃容器放在厨房里。", "target_word": "容器", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "容器太小了，装不下这么多汤。", "target_word": "容器", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这个容器有盖子，东西不会洒出来。", "target_word": "容器", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "实验室里有各种各样的容器。", "target_word": "容器", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他找了一个大容器来装雨水。", "target_word": "容器", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "把剩菜倒进容器，再放进冰箱。", "target_word": "容器", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这个容器不能放进微波炉。", "target_word": "容器", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "个", "label": "量词"}, {"form": "塑料容器", "label": "复合"}, {"form": "玻璃容器", "label": "复合"}], "register": "中性", "sense_fingerprint": "名词，用来装水、食物等东西的器具，如盒子、瓶子", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'ca85f957-df35-4d8f-af57-1db695739dd7') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (22514, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "容器", "is_correct": true, "explanation": "“容器”指可以盛装东西的器具，与“装水、装米”搭配，句意通顺。"}, {"text": "房子", "is_correct": false, "explanation": "语义：房子不能用来装水和米，与“装”的内容矛盾。"}, {"text": "灯泡", "is_correct": false, "explanation": "语义：灯泡不能盛装东西，句意不通。"}, {"text": "桌子", "is_correct": false, "explanation": "搭配：“装”的对象应是能盛东西的器具，不能说桌子可以装水和米。"}], "explanations": {"容器": "“容器”指可以盛装东西的器具，与“装水、装米”搭配，句意通顺。", "房子": "语义：房子不能用来装水和米，与“装”的内容矛盾。", "灯泡": "语义：灯泡不能盛装东西，句意不通。", "桌子": "搭配：“装”的对象应是能盛东西的器具，不能说桌子可以装水和米。"}, "sentence_index": 0, "correct_answer": "容器"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "我买了一条容器，放在厨房里。", "explanation": "这里应该用〈个〉。“容器”一般用“个”计量，“条”用于细长的东西，不能用于容器。"}, {"text": "这次考试的容器很难。", "explanation": "这里应该用〈难度〉。“容器”指盛装东西的器具，考试的难易程度应说“难度”。"}, {"text": "这个小伙子的容器很高。", "explanation": "这里应该用〈身材〉。“容器”指装东西的器具，形容人的高矮、体形要用“身材”。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'c290b81d-0dcb-45a5-b379-91fe24a99a2f') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (22514, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "容器", "is_correct": true, "explanation": "“容器”是可以装东西的器具，与“各种各样的”搭配，在实验室里很常见，句意通顺。"}, {"text": "教室", "is_correct": false, "explanation": "语义：实验室里不会有“教室”这类场所，句子语义不通。"}, {"text": "海洋", "is_correct": false, "explanation": "搭配：“各种各样的”修饰的是可以分类的器物，不能修饰“海洋”。"}, {"text": "动物园", "is_correct": false, "explanation": "语义：“动物园”是场所，不能与“实验室里有”的物品类搭配，句意矛盾。"}], "explanations": {"容器": "“容器”是可以装东西的器具，与“各种各样的”搭配，在实验室里很常见，句意通顺。", "教室": "语义：实验室里不会有“教室”这类场所，句子语义不通。", "海洋": "搭配：“各种各样的”修饰的是可以分类的器物，不能修饰“海洋”。", "动物园": "语义：“动物园”是场所，不能与“实验室里有”的物品类搭配，句意矛盾。"}, "sentence_index": 6, "correct_answer": "容器"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "她的容器很美。", "explanation": "这里应该用〈容貌〉。“容器”指盛装东西的器具，形容人的长相要用“容貌”。"}, {"text": "这件衣服的容器很大。", "explanation": "这里应该用〈尺码〉。“容器”指盛装东西的器具，衣服的大小要用“尺码”。"}, {"text": "这次比赛的容器很激烈。", "explanation": "这里应该用〈竞争〉。“容器”指盛装东西的器具，比赛的激烈程度应说“竞争很激烈”。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'c290b81d-0dcb-45a5-b379-91fe24a99a2f') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (22514, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "这条容器很大，可以装很多水。", "corrected_sentence": "这个容器很大，可以装很多水。", "error_description": "量词错误：“容器”一般用“个”，不能用“条”（“条”多用于细长的东西）；应说“这个容器”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'c290b81d-0dcb-45a5-b379-91fe24a99a2f') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (22514, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "我家的容器们很大，能装很多米。", "corrected_sentence": "我家的容器很大，能装很多米。", "error_description": "多加“们”：“们”多用于指人，“容器”是物，不能加“们”；应说“我家的容器很大”，不能说“我家的容器们很大”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'c290b81d-0dcb-45a5-b379-91fe24a99a2f') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
