INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (22518, 1, 'prompt1_core', '{"pos": "动词", "semantic_class": "action", "definition": "把东西分开，比如用刀把蛋糕切成小块。", "primary_collocate": null, "pronunciation": "qiē gē", "ipa": "tɕʰie˥ kɤ˥", "syllable_count": 2, "sentences": [{"text": "这张大纸要切割成四份，分给各组。", "target_word": "切割", "complexity_tier": "T3", "furigana": "qiē gē", "sentence_source": "generated"}, {"text": "这卷绳子要切割成五段，分给五个人。", "target_word": "切割", "complexity_tier": "T3", "furigana": "qiē gē", "sentence_source": "generated"}, {"text": "这卷电线要切割成小段，方便搬运。", "target_word": "切割", "complexity_tier": "T3", "furigana": "qiē gē", "sentence_source": "generated"}, {"text": "这块硬纸板要切割成三个小方块。", "target_word": "切割", "complexity_tier": "T3", "furigana": "qiē gē", "sentence_source": "generated"}, {"text": "切割纸板前，先量好尺寸。", "target_word": "切割", "complexity_tier": "T3", "furigana": "qiē gē", "sentence_source": "generated"}, {"text": "裁缝把这块布切割成几段，做成窗帘。", "target_word": "切割", "complexity_tier": "T3", "furigana": "qiē gē", "sentence_source": "generated"}, {"text": "他把一张纸切割成三份。", "target_word": "切割", "complexity_tier": "T3", "furigana": "qiē gē", "sentence_source": "generated"}, {"text": "这根长木条要切割成八段才够用。", "target_word": "切割", "complexity_tier": "T3", "furigana": "qiē gē", "sentence_source": "generated"}, {"text": "这块铁皮要切割成小方块，装进箱子。", "target_word": "切割", "complexity_tier": "T3", "furigana": "qiē gē", "sentence_source": "generated"}, {"text": "工人把这块厚钢板切割成小方块。", "target_word": "切割", "complexity_tier": "T3", "furigana": "qiē gē", "sentence_source": "generated"}], "morphological_forms": [{"form": "切割了", "label": "体标"}, {"form": "切割着", "label": "体标"}, {"form": "切割过", "label": "体标"}, {"form": "切割机", "label": "复合"}], "register": "中性", "sense_fingerprint": "把东西分成小块，如用刀切蛋糕", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '92c60d06-3515-47fc-b463-2e1824a62f42') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (22518, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "切割", "is_correct": true, "explanation": "切割指把东西分成小块，与“大纸要……成四份”相符。"}, {"text": "烤", "is_correct": false, "explanation": "语义：“烤”需用火加热食物，不能用来把纸分份。"}, {"text": "唱", "is_correct": false, "explanation": "搭配：“唱”不能和“大纸成四份”搭配。"}, {"text": "洗", "is_correct": false, "explanation": "搭配：“洗”的结果不能是“成四份”，与纸张搭配不当。"}], "explanations": {"切割": "切割指把东西分成小块，与“大纸要……成四份”相符。", "烤": "语义：“烤”需用火加热食物，不能用来把纸分份。", "唱": "搭配：“唱”不能和“大纸成四份”搭配。", "洗": "搭配：“洗”的结果不能是“成四份”，与纸张搭配不当。"}, "sentence_index": 0, "correct_answer": "切割"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "妈妈把衣服切割好放进柜子。", "explanation": "这里应该用〈叠〉。叠是把衣服折叠整齐，切割是把物体分成几块。"}, {"text": "妈妈在厨房里切割了一首歌。", "explanation": "这里应该用〈唱〉。唱歌是发出歌声，切割是把物体分开，不能用来指唱歌。"}, {"text": "他在夜里切割了一首诗。", "explanation": "这里应该用〈写〉。写诗是用文字创作，“切割”是把实物分开，不能用来指创作一首诗。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '628b12a7-913f-4083-93e1-62d9695b39ac') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (22518, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "切割", "is_correct": true, "explanation": "切割指把东西分成小块，与“把一张纸……成三份”相符。"}, {"text": "喝", "is_correct": false, "explanation": "语义：“喝”的对象是饮品，不能用来把纸分份。"}, {"text": "哭", "is_correct": false, "explanation": "配价：“哭”是不及物动词，不能带宾语，也不能说“哭成三份”。"}, {"text": "熬", "is_correct": false, "explanation": "语义：“熬”是用水长时间加热，与纸张分割不符。"}], "explanations": {"切割": "切割指把东西分成小块，与“把一张纸……成三份”相符。", "喝": "语义：“喝”的对象是饮品，不能用来把纸分份。", "哭": "配价：“哭”是不及物动词，不能带宾语，也不能说“哭成三份”。", "熬": "语义：“熬”是用水长时间加热，与纸张分割不符。"}, "sentence_index": 6, "correct_answer": "切割"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "他在纸上切割了一幅画。", "explanation": "这里应该用〈画〉。画画是用笔作画，切割是把物体分开，不能用来作画。"}, {"text": "工匠在木头上切割了一句祝福。", "explanation": "这里应该用〈刻〉。刻是在木头上雕出字句，“切割”是把实物分开，不能用来指“一句祝福”。"}, {"text": "工人把钢板切割成了一本书。", "explanation": "这里应该用〈印〉。印书是印刷装订成册，切割是把物体分开，钢板不能切割成书。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '628b12a7-913f-4083-93e1-62d9695b39ac') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (22518, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "妈妈把面包切割了成几片。", "corrected_sentence": "妈妈把面包切割成几片。", "error_description": "体标位置错误：“了”不能插在动词“切割”和结果补语“成”之间，应说“把面包切割成几片”，去掉“了”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '628b12a7-913f-4083-93e1-62d9695b39ac') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (22518, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "这沓纸切割很整齐。", "corrected_sentence": "这沓纸切割得很整齐。", "error_description": "补语标记缺失：程度补语前要用“得”，应说“切割得很整齐”，不能说“切割很整齐”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '628b12a7-913f-4083-93e1-62d9695b39ac') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
