INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (22522, 1, 'prompt1_core', '{"pos": "名词", "semantic_class": "concrete", "definition": "织物就是做衣服、窗帘用的布。", "primary_collocate": null, "pronunciation": "zhī wù", "ipa": "ʈʂʅ˥ u˥˩", "syllable_count": 2, "sentences": [{"text": "妈妈买了织物，准备做窗帘。", "target_word": "织物", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这家店卖各种颜色的织物。", "target_word": "织物", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "沙发上的织物很容易脏。", "target_word": "织物", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "冬天的衣服要用厚一点的织物。", "target_word": "织物", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这种织物摸起来很舒服。", "target_word": "织物", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "我想选一块织物做新衣服。", "target_word": "织物", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这种织物不用熨，洗完就能穿。", "target_word": "织物", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "奶奶用旧织物做了一个小包。", "target_word": "织物", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "窗帘用的织物要能挡光。", "target_word": "织物", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这种织物又轻又薄，夏天穿很舒服。", "target_word": "织物", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "一块织物", "label": "量词"}, {"form": "一种织物", "label": "量词"}, {"form": "针织物", "label": "复合"}, {"form": "織物", "label": "繁体"}], "register": "中性", "sense_fingerprint": "做衣服、窗帘用的布", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '92c60d06-3515-47fc-b463-2e1824a62f42') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (22522, 1, 'prompt2_exercises_A', '{"level_1": {"options": [{"text": "织物", "is_correct": true, "explanation": "zhī wù：做衣服、窗帘用的布，正是本词的意思。"}, {"text": "职务", "is_correct": false, "explanation": "zhí（第二声）与 zhī（第一声）声调不同，职务指工作中的职位与责任。"}, {"text": "支付", "is_correct": false, "explanation": "fù 与 wù 声母不同（f 与 w），支付指付钱。"}, {"text": "事务", "is_correct": false, "explanation": "shì 与 zhī 声母和声调都不同，事务指日常的工作或业务。"}, {"text": "失物", "is_correct": false, "explanation": "shī 与 zhī 声母不同（sh 与 zh），失物指丢失的东西。"}], "explanations": {"织物": "zhī wù：做衣服、窗帘用的布，正是本词的意思。", "职务": "zhí（第二声）与 zhī（第一声）声调不同，职务指工作中的职位与责任。", "支付": "fù 与 wù 声母不同（f 与 w），支付指付钱。", "事务": "shì 与 zhī 声母和声调都不同，事务指日常的工作或业务。", "失物": "shī 与 zhī 声母不同（sh 与 zh），失物指丢失的东西。"}, "sentence_index": null, "correct_answer": "织物"}, "level_3": {"options": [{"text": "织物", "is_correct": true, "explanation": "正确：窗帘是用布做的，“买了织物，准备做窗帘”合乎逻辑。"}, {"text": "蔬菜", "is_correct": false, "explanation": "语义：蔬菜是食物，不能用来做窗帘。"}, {"text": "铁板", "is_correct": false, "explanation": "体貌：铁板坚硬笨重，无法做柔软能挂的窗帘。"}, {"text": "饼干", "is_correct": false, "explanation": "语义：饼干是食品，与“做窗帘”的用途无关。"}], "explanations": {"织物": "正确：窗帘是用布做的，“买了织物，准备做窗帘”合乎逻辑。", "蔬菜": "语义：蔬菜是食物，不能用来做窗帘。", "铁板": "体貌：铁板坚硬笨重，无法做柔软能挂的窗帘。", "饼干": "语义：饼干是食品，与“做窗帘”的用途无关。"}, "sentence_index": 0, "correct_answer": "织物"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "他每天用织物刷牙。", "explanation": "这里应该用〈牙刷〉。刷牙要用牙刷，织物是布料，不能用来刷牙。"}, {"text": "我买了一双织物做窗帘。", "explanation": "这里应该用〈块〉。“双”用于成对的东西，织物是一整块布，不用“双”。"}, {"text": "她用织物绣花，绣得很漂亮。", "explanation": "这里应该用〈丝线〉。绣花要用线，织物已经是布，不能用它来绣花。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '628b12a7-913f-4083-93e1-62d9695b39ac') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (22522, 1, 'prompt2_exercises_B', '{"level_1": {"options": [{"text": "织物", "is_correct": true, "explanation": "zhī wù：做衣服、窗帘用的布，正是本词的意思。"}, {"text": "植物", "is_correct": false, "explanation": "zhí（第二声）与 zhī（第一声）声调不同，植物指生长在土地上的生物。"}, {"text": "实务", "is_correct": false, "explanation": "shí 与 zhī 声母不同，声调也不同，实务指实际的业务工作。"}, {"text": "置物", "is_correct": false, "explanation": "zhì（第四声）与 zhī（第一声）声调不同，置物指放置物品，如置物架。"}, {"text": "支吾", "is_correct": false, "explanation": "第二音节 wu 为轻声，与 wù（第四声）声调不同，支吾指言语含糊、躲闪。"}], "explanations": {"织物": "zhī wù：做衣服、窗帘用的布，正是本词的意思。", "植物": "zhí（第二声）与 zhī（第一声）声调不同，植物指生长在土地上的生物。", "实务": "shí 与 zhī 声母不同，声调也不同，实务指实际的业务工作。", "置物": "zhì（第四声）与 zhī（第一声）声调不同，置物指放置物品，如置物架。", "支吾": "第二音节 wu 为轻声，与 wù（第四声）声调不同，支吾指言语含糊、躲闪。"}, "sentence_index": null, "correct_answer": "织物"}, "level_3": {"options": [{"text": "织物", "is_correct": true, "explanation": "正确：这种布料不用熨、洗完就能穿，符合织物的特点。"}, {"text": "木头", "is_correct": false, "explanation": "语义：木头不能穿，“洗完就能穿”说不通。"}, {"text": "玻璃", "is_correct": false, "explanation": "体貌：玻璃坚硬易碎，与能穿的柔软衣料不相符。"}, {"text": "面包", "is_correct": false, "explanation": "语义：面包是食品，不能穿，与整句的语境矛盾。"}], "explanations": {"织物": "正确：这种布料不用熨、洗完就能穿，符合织物的特点。", "木头": "语义：木头不能穿，“洗完就能穿”说不通。", "玻璃": "体貌：玻璃坚硬易碎，与能穿的柔软衣料不相符。", "面包": "语义：面包是食品，不能穿，与整句的语境矛盾。"}, "sentence_index": 6, "correct_answer": "织物"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "他是一名织物，负责裁剪布料。", "explanation": "这里应该用〈工人〉。织物是布料，指物品而不指人；指从事裁剪的人应说“裁缝”或“工人”。"}, {"text": "妈妈在一家织物工作，每天很忙。", "explanation": "这里应该用〈纺织厂〉。织物指布料等纺织成品，不指工厂或公司，“在一家……工作”要用〈纺织厂〉。"}, {"text": "工厂把织物织成了纱线。", "explanation": "这里应该用〈拆〉。织物是纱线织成的，应说“把织物拆成纱线”，“织成”的方向说反了。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '628b12a7-913f-4083-93e1-62d9695b39ac') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content,