INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (22522, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "这只织物很厚，可以做窗帘。", "corrected_sentence": "这块织物很厚，可以做窗帘。", "error_description": "量词错误：“只”用于动物或成对器官中的一个，布料不用“只”，应说“块”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '628b12a7-913f-4083-93e1-62d9695b39ac') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (22522, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "这种又厚又软织物，做窗帘很合适。", "corrected_sentence": "这种又厚又软的织物，做窗帘很合适。", "error_description": "的字缺失：修饰语“又厚又软”与“织物”之间要加“的”，应说“又厚又软的织物”，不说“又厚又软织物”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '628b12a7-913f-4083-93e1-62d9695b39ac') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
