INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (22524, 1, 'prompt1_core', '{"pos": "动词", "semantic_class": "action", "definition": "表示把它放在其他东西前面。", "primary_collocate": null, "pronunciation": "yōu xiān", "ipa": "joʊ˥ ɕjɛn˥", "syllable_count": 2, "sentences": [{"text": "请让老人优先。", "target_word": "优先", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这些客人优先入场。", "target_word": "优先", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "我们优先处理最急的工作。", "target_word": "优先", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "学生优先使用图书馆的电脑。", "target_word": "优先", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "路上遇到救护车，要让它优先通过。", "target_word": "优先", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "报名时，有经验的人优先。", "target_word": "优先", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "孩子的健康要优先。", "target_word": "优先", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他优先选择了最便宜的那个。", "target_word": "优先", "complexity_tier": "T3", "furigana": "tā yōu xiān xuǎn zé le zuì pián yi de nà ge。", "sentence_source": "generated"}, {"text": "他总是把家人放在第一，优先考虑他们。", "target_word": "优先", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这个窗口，残疾人优先办理。", "target_word": "优先", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "优先权", "label": "复合"}, {"form": "优先级", "label": "复合"}, {"form": "優先", "label": "繁体"}], "register": "中性", "sense_fingerprint": "把某人或某事放在其他前面", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '92c60d06-3515-47fc-b463-2e1824a62f42') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (22524, 1, 'prompt2_exercises_A', '{"level_1": {"options": [{"text": "优先", "is_correct": true, "explanation": "正确：优先（yōu xiān）即本词，意思是把某人或某事放在其他前面。"}, {"text": "悠闲", "is_correct": false, "explanation": "xián（第二声）与 xiān（第一声）声调不同，意思是悠闲。"}, {"text": "幽香", "is_correct": false, "explanation": "xiāng 与 xiān 韵母不同（-ang 与 -an），意思是幽香。"}, {"text": "忧心", "is_correct": false, "explanation": "xīn 与 xiān 韵母不同（-in 与 -an），意思是忧心。"}, {"text": "有限", "is_correct": false, "explanation": "yǒu xiàn 与 yōu xiān 两个音节声调都不同，意思是有限。"}], "explanations": {"优先": "正确：优先（yōu xiān）即本词，意思是把某人或某事放在其他前面。", "悠闲": "xián（第二声）与 xiān（第一声）声调不同，意思是悠闲。", "幽香": "xiāng 与 xiān 韵母不同（-ang 与 -an），意思是幽香。", "忧心": "xīn 与 xiān 韵母不同（-in 与 -an），意思是忧心。", "有限": "yǒu xiàn 与 yōu xiān 两个音节声调都不同，意思是有限。"}, "sentence_index": null, "correct_answer": "优先"}, "level_3": {"options": [{"text": "优先", "is_correct": true, "explanation": "正确：“请让老人优先”即请把老人放在前面，符合句意。"}, {"text": "作废", "is_correct": false, "explanation": "语义：“作废”指失效，与“请让老人”的礼让意思不符。"}, {"text": "倒闭", "is_correct": false, "explanation": "语义：“倒闭”指企业停业，不能用于让人让位的语境。"}, {"text": "延长", "is_correct": false, "explanation": "配价：“延长”要带时间或期限作宾语，不能直接以“老人”作宾语后作结。"}], "explanations": {"优先": "正确：“请让老人优先”即请把老人放在前面，符合句意。", "作废": "语义：“作废”指失效，与“请让老人”的礼让意思不符。", "倒闭": "语义：“倒闭”指企业停业，不能用于让人让位的语境。", "延长": "配价：“延长”要带时间或期限作宾语，不能直接以“老人”作宾语后作结。"}, "sentence_index": 0, "correct_answer": "优先"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "妹妹优先学会了走路。", "explanation": "这里应该用〈先〉。优先表示把某人某事放在其他东西前面，学会走路的先后是自然发展，应该说“先学会”。"}, {"text": "这次比赛，我优先到达了终点。", "explanation": "这里应该用〈先〉。优先表示把某人某事放在其他东西前面，比赛中谁先到终点是自然结果，不是优先安排的结果，应说“先到达”。"}, {"text": "孩子们优先长高了。", "explanation": "这里应该用〈先〉。优先表示把某人某事放在其他东西前面，身高变化是自然过程，不能说“优先长高”。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '628b12a7-913f-4083-93e1-62d9695b39ac') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (22524, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "优先", "is_correct": true, "explanation": "正确：“孩子的健康要优先”表示孩子的健康应放在最前面，符合句意。"}, {"text": "忘记", "is_correct": false, "explanation": "语义：“忘记”与“孩子的健康要……”的要求矛盾，不能说“要忘记健康”。"}, {"text": "放弃", "is_correct": false, "explanation": "语义：“放弃”与“健康”应受保护的意思相反，句意不通。"}, {"text": "推迟", "is_correct": false, "explanation": "配价：“推迟”要带被推迟的事项作宾语，不能以“健康”直接作被推迟的对象。"}], "explanations": {"优先": "正确：“孩子的健康要优先”表示孩子的健康应放在最前面，符合句意。", "忘记": "语义：“忘记”与“孩子的健康要……”的要求矛盾，不能说“要忘记健康”。", "放弃": "语义：“放弃”与“健康”应受保护的意思相反，句意不通。", "推迟": "配价：“推迟”要带被推迟的事项作宾语，不能以“健康”直接作被推迟的对象。"}, "sentence_index": 6, "correct_answer": "优先"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "他优先害羞地笑了。", "explanation": "这里应该用〈先〉。优先表示把某人某事放在其他东西前面，害羞是自然反应，不是安排的先后，不能用“优先”。"}, {"text": "他优先忘记了我的名字。", "explanation": "这里应该用〈先〉。优先表示把某人某事放在其他东西前面，忘记名字不是选择的结果，不能用“优先”。"}, {"text": "那个女孩优先哭了。", "explanation": "这里应该用〈先〉。优先表示把某人某事放在其他东西前面，哭的先后是自然发生的，不能用“优先”。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '628b12a7-913f-4083-93e1-62d9695b39ac') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (22524, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "医院应该优先权救治重伤者。", "corrected_sentence": "医院应该优先救治重伤者。", "error_description": "错误：“优先权”是名词，不能直接放在动词“救治”前作状语。应说“优先救治重伤者”，去掉“权”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '628b12a7-913f-4083-93e1-62d9695b39ac') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (22524, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "请让老人优先权下车。", "corrected_sentence": "请让老人优先下车。", "error_description": "错误：“优先权”是名词，不能直接放在动词“下车”前作状语。应说“优先下车”，去掉“权”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '628b12a7-913f-4083-93e1-62d9695b39ac') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
