INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (22526, 1, 'prompt1_core', '{"pos": "名词", "semantic_class": "abstract", "definition": "完整就是一样东西的所有部分都在，没有少掉任何一块。", "primary_collocate": null, "pronunciation": "wán zhěng xìng", "ipa": "wan˧˥ ʈʂəŋ˨˩ ɕiŋ˥˩", "syllable_count": 3, "sentences": [{"text": "这套拼图的完整性很高，一块都不少。", "target_word": "完整性", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "买玩具时，我先检查它的完整性。", "target_word": "完整性", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这张地图被撕坏了，完整性没有了。", "target_word": "完整性", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "盒子里的零件都在，完整性没有问题。", "target_word": "完整性", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "老师说，这套课本的完整性很重要。", "target_word": "完整性", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这副象棋少了一个棋子，完整性不够。", "target_word": "完整性", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "收到包裹后，请先看一看东西的完整性。", "target_word": "完整性", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这幅画被剪掉一角，完整性受到了破坏。", "target_word": "完整性", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他把旧相册保存得很好，完整性让人佩服。", "target_word": "完整性", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "为了保持书的完整性，请不要撕页。", "target_word": "完整性", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "数据完整性", "label": "复合"}, {"form": "完整性检查", "label": "复合"}], "register": "中性", "sense_fingerprint": "东西的所有部分都在、一块不少", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'ba713f93-d7fe-4309-b531-8a7d0486cb5c') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (22526, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "完整性", "is_correct": true, "explanation": "“完整性很高，一块都不少”说明拼图各部分齐全，符合语境。"}, {"text": "颜色", "is_correct": false, "explanation": "搭配：颜色不能用“高”来形容，“颜色很高”不成立。"}, {"text": "速度", "is_correct": false, "explanation": "语义：拼图与速度无关，这句话说不通。"}, {"text": "声音", "is_correct": false, "explanation": "语义：声音的高低与拼图是否齐全无关。"}], "explanations": {"完整性": "“完整性很高，一块都不少”说明拼图各部分齐全，符合语境。", "颜色": "搭配：颜色不能用“高”来形容，“颜色很高”不成立。", "速度": "语义：拼图与速度无关，这句话说不通。", "声音": "语义：声音的高低与拼图是否齐全无关。"}, "sentence_index": 0, "correct_answer": "完整性"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "这个盒子的完整性很轻。", "explanation": "这里应该用〈重量〉。完整性指各部分齐全，不能用来说轻重。"}, {"text": "这套拼图的完整性很便宜。", "explanation": "这里应该用〈价格〉。完整性不能用来说价钱的高低。"}, {"text": "这套拼图的完整性很鲜艳。", "explanation": "这里应该用〈颜色〉。完整性不能用来形容颜色。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'a1697b85-2e0f-4e53-8d0e-b40ae68bea44') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (22526, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "完整性", "is_correct": true, "explanation": "“看一看东西的完整性”指检查东西的各部分是否齐全，符合语境。"}, {"text": "音量", "is_correct": false, "explanation": "语义：音量指声音的大小，与东西是否齐全无关。"}, {"text": "心情", "is_correct": false, "explanation": "语义：东西没有心情，这里说不通。"}, {"text": "脾气", "is_correct": false, "explanation": "语义：东西没有脾气，这里说不通。"}], "explanations": {"完整性": "“看一看东西的完整性”指检查东西的各部分是否齐全，符合语境。", "音量": "语义：音量指声音的大小，与东西是否齐全无关。", "心情": "语义：东西没有心情，这里说不通。", "脾气": "语义：东西没有脾气，这里说不通。"}, "sentence_index": 6, "correct_answer": "完整性"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "这张桌子的完整性很大。", "explanation": "这里应该用〈宽度〉。完整性指各部分齐全，不表示宽窄。"}, {"text": "这根绳子的完整性很长。", "explanation": "这里应该用〈长度〉。完整性不能用来表示长短。"}, {"text": "他打球的完整性很大。", "explanation": "这里应该用〈力度〉。完整性不能用来形容用力的程度。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'a1697b85-2e0f-4e53-8d0e-b40ae68bea44') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (22526, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "这副拼图的完整性很多，一块都不少。", "corrected_sentence": "这副拼图的完整性很高，一块都不少。", "error_description": "“完整性”是抽象名词，不能用“很多”来修饰，应说“很高”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'a1697b85-2e0f-4e53-8d0e-b40ae68bea44') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (22526, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "这套书的完整性把破坏了。", "corrected_sentence": "这套书的完整性被破坏了。", "error_description": "“完整性”是被破坏的对象，应用“被”引出，不用“把”。“把”字句要求受事放在“把”后，说“完整性把破坏了”不通，应说“完整性被破坏了”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'a1697b85-2e0f-4e53-8d0e-b40ae68bea44') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
