INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (22528, 1, 'prompt1_core', '{"pos": "名词", "semantic_class": "concrete", "definition": "尺子上的小线，用来量东西有多长。", "primary_collocate": null, "pronunciation": "kè dù", "ipa": "kʰɤ˥˩ tu˥˩", "syllable_count": 2, "sentences": [{"text": "尺子上有很多小刻度。", "target_word": "刻度", "complexity_tier": "T1", "sentence_source": "generated"}, {"text": "一厘米有十个小刻度。", "target_word": "刻度", "complexity_tier": "T1", "sentence_source": "generated"}, {"text": "我数了数尺子上的刻度。", "target_word": "刻度", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "这把尺子没有刻度，不能量长度。", "target_word": "刻度", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "请看刻度，这支笔长十二厘米。", "target_word": "刻度", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "这把尺子刻度清楚，量起来很方便。", "target_word": "刻度", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "最小的刻度表示一毫米。", "target_word": "刻度", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "刻度太小，我看不清。", "target_word": "刻度", "complexity_tier": "T1", "sentence_source": "generated"}, {"text": "老师教我们怎么读刻度。", "target_word": "刻度", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "旧尺子的刻度都磨掉了。", "target_word": "刻度", "complexity_tier": "T2", "sentence_source": "generated"}], "morphological_forms": [{"form": "刻度尺", "label": "复合"}, {"form": "刻度线", "label": "复合"}], "register": "中性", "sense_fingerprint": "尺子上用来量长度的小线", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '0f195968-6b0c-4b2a-8e22-a822d564ee90') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (22528, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "刻度", "is_correct": true, "explanation": "正确：尺子上的小线就是刻度，“尺子上有很多小刻度”符合语境。"}, {"text": "故事", "is_correct": false, "explanation": "语义：故事不是尺子上的标记，“尺子上有很多小故事”说不通。"}, {"text": "味道", "is_correct": false, "explanation": "语义：味道不能刻在尺子上，句中说不通。"}, {"text": "歌曲", "is_correct": false, "explanation": "搭配：“尺子上有很多小……”不搭配“歌曲”，尺子上不会有歌曲。"}], "explanations": {"刻度": "正确：尺子上的小线就是刻度，“尺子上有很多小刻度”符合语境。", "故事": "语义：故事不是尺子上的标记，“尺子上有很多小故事”说不通。", "味道": "语义：味道不能刻在尺子上，句中说不通。", "歌曲": "搭配：“尺子上有很多小……”不搭配“歌曲”，尺子上不会有歌曲。"}, "sentence_index": 0, "correct_answer": "刻度"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "我看了一把刻度。", "explanation": "量词错误：这里应该用〈道〉。“把”用于有柄的器具，刻度是尺子上的小线，应用“道”计量。"}, {"text": "厘米是长度的刻度。", "explanation": "这里应该用〈单位〉。厘米是长度的计量单位，刻度是尺子上的标线，不能这样说。"}, {"text": "这双鞋的刻度是四十二。", "explanation": "这里应该用〈尺码〉。四十二是鞋的号数，应说“尺码”，刻度不表示号数。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '5f7505f7-c7aa-4e1c-be2a-f731873138c7') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (22528, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "刻度", "is_correct": true, "explanation": "正确：最小的刻度表示一毫米，符合尺子的语境。"}, {"text": "颜色", "is_correct": false, "explanation": "语义：颜色不能表示长度，“最小的颜色表示一毫米”说不通。"}, {"text": "气味", "is_correct": false, "explanation": "语义：气味不能表示长度，句中说不通。"}, {"text": "歌词", "is_correct": false, "explanation": "搭配：“最小的”后接“歌词”不通，歌词不表示长度。"}], "explanations": {"刻度": "正确：最小的刻度表示一毫米，符合尺子的语境。", "颜色": "语义：颜色不能表示长度，“最小的颜色表示一毫米”说不通。", "气味": "语义：气味不能表示长度，句中说不通。", "歌词": "搭配：“最小的”后接“歌词”不通，歌词不表示长度。"}, "sentence_index": 6, "correct_answer": "刻度"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "我数了一位刻度。", "explanation": "量词错误：这里应该用〈道〉。“位”只用于人，刻度是尺子上的小线，应用“道”计量。"}, {"text": "这副眼镜的刻度是三百度。", "explanation": "这里应该用〈度数〉。“三百度”指镜片的光学度数，刻度只是量具上的标线，不能这样表示。"}, {"text": "这双鞋的尺码是四十二，刻度也是四十二。", "explanation": "这里误把〈刻度〉当成了表示鞋码的意思：刻度是量具上的标线，不能用来表示鞋子的号码。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '5f7505f7-c7aa-4e1c-be2a-f731873138c7') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (22528, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "尺子上有一把清楚的刻度。", "corrected_sentence": "尺子上有一道清楚的刻度。", "error_description": "量词错误：“刻度”应使用量词“道”，“把”用于有柄的器具，不能用来计量尺子上的小线。正确说法是“一道刻度”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '5f7505f7-c7aa-4e1c-be2a-f731873138c7') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (22528, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "尺子上的刻度们都很清楚。", "corrected_sentence": "尺子上的刻度都很清楚。", "error_description": "错误：「刻度们」；正确：「刻度」。「们」只加在指人的名词或代词后，刻度是物品，不能加「们」。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '5f7505f7-c7aa-4e1c-be2a-f731873138c7') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
