INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (22530, 1, 'prompt1_core', '{"pos": "名词", "semantic_class": "abstract", "definition": "两个人见面。", "primary_collocate": null, "pronunciation": "huì miàn", "ipa": "xweɪ˥˩ mjɛn˥˩", "syllable_count": 2, "sentences": [{"text": "姐姐和男朋友的会面约在咖啡馆。", "target_word": "会面", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这是他们两个人多年来的第一次会面。", "target_word": "会面", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "两个人的会面只有短短五分钟。", "target_word": "会面", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "会面那天，小李紧张得一夜没睡好。", "target_word": "会面", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "老同学的这次会面，让他想起了小时候。", "target_word": "会面", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他们的会面很安静，没有别人在旁边。", "target_word": "会面", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "经过一次会面，两个人成了好朋友。", "target_word": "会面", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "妈妈很想安排一次和老师的会面。", "target_word": "会面", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "昨天的会面很短，两个人只说了几句话。", "target_word": "会面", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "两个人的会面地点选在学校门口。", "target_word": "会面", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "一次会面", "label": "量词"}, {"form": "會面", "label": "繁体"}], "register": "中性", "sense_fingerprint": "会面：两个人之间的见面", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '0f195968-6b0c-4b2a-8e22-a822d564ee90') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (22530, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "会面", "is_correct": true, "explanation": "正确：“姐姐和男朋友的会面”指两人约定的见面，约在咖啡馆符合句意。"}, {"text": "比赛", "is_correct": false, "explanation": "搭配：“男朋友的比赛”不自然，“比赛”不用于个人约见。"}, {"text": "考试", "is_correct": false, "explanation": "语义：考试不是约见的事件，不能约在咖啡馆。"}, {"text": "演出", "is_correct": false, "explanation": "语义：演出一般在剧场举行，不能约在咖啡馆见面。"}], "explanations": {"会面": "正确：“姐姐和男朋友的会面”指两人约定的见面，约在咖啡馆符合句意。", "比赛": "搭配：“男朋友的比赛”不自然，“比赛”不用于个人约见。", "考试": "语义：考试不是约见的事件，不能约在咖啡馆。", "演出": "语义：演出一般在剧场举行，不能约在咖啡馆见面。"}, "sentence_index": 0, "correct_answer": "会面"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "这只杯子昨天会面了。", "explanation": "这里应该用〈摔〉。会面指人与人见面，不能用于物品掉落破碎。"}, {"text": "他冷得会面。", "explanation": "这里应该用〈发抖〉。会面指见面，不能用来形容冷得身体颤抖。"}, {"text": "这只碗的会面很光滑。", "explanation": "这里应该用〈表面〉。会面指两人见面，不能用来指器物的外表。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '5f7505f7-c7aa-4e1c-be2a-f731873138c7') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (22530, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "会面", "is_correct": true, "explanation": "正确：“经过一次会面，两个人成了好朋友”指两人见面后的关系变化，符合句意。"}, {"text": "花园", "is_correct": false, "explanation": "语义：花园是场所，不是事件，“经过一次花园”不通。"}, {"text": "天气", "is_correct": false, "explanation": "语义：天气不能作为“经过一次”的事件，句中不通。"}, {"text": "感冒", "is_correct": false, "explanation": "搭配：“经过”一般接事件，“经过一次感冒”与句意不搭配。"}], "explanations": {"会面": "正确：“经过一次会面，两个人成了好朋友”指两人见面后的关系变化，符合句意。", "花园": "语义：花园是场所，不是事件，“经过一次花园”不通。", "天气": "语义：天气不能作为“经过一次”的事件，句中不通。", "感冒": "搭配：“经过”一般接事件，“经过一次感冒”与句意不搭配。"}, "sentence_index": 6, "correct_answer": "会面"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "厨房里的会面很香。", "explanation": "这里应该用〈饭〉。会面指两人见面，不能用来形容饭菜的香味。"}, {"text": "妈妈的会面很暖和。", "explanation": "这里应该用〈手〉。会面指见面，不能用来形容手的温度。"}, {"text": "他会面得很快。", "explanation": "这里应该用〈跑〉。会面指见面，不能用来形容跑的速度。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '5f7505f7-c7aa-4e1c-be2a-f731873138c7') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (22530, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "他们约好下周一会面过。", "corrected_sentence": "他们约好下周一会面。", "error_description": "体貌错误：「过」表示已发生的经历，不能与将来的「下周一」搭配；应去掉「过」，说「约好下周一会面」。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '5f7505f7-c7aa-4e1c-be2a-f731873138c7') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (22530, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "他们会面了三个次。", "corrected_sentence": "他们会面了三次。", "error_description": "量词错误：动量词「次」前不能加「个」，应说「三次」。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '5f7505f7-c7aa-4e1c-be2a-f731873138c7') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
