INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (22532, 1, 'prompt1_core', '{"pos": "名词", "semantic_class": "concrete", "definition": "钟表是看时间的工具。", "primary_collocate": null, "pronunciation": "zhōng biǎo", "ipa": "tʂʊŋ˥ pjaʊ˨˩˦", "syllable_count": 2, "sentences": [{"text": "我家客厅的墙上有钟表。", "target_word": "钟表", "complexity_tier": "T1", "sentence_source": "generated"}, {"text": "看钟表，现在已经九点了。", "target_word": "钟表", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "孩子在学习怎么看钟表。", "target_word": "钟表", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "没有钟表，我就不知道几点。", "target_word": "钟表", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "他的房间里没有钟表。", "target_word": "钟表", "complexity_tier": "T1", "sentence_source": "generated"}, {"text": "钟表停了，我们不知道时间。", "target_word": "钟表", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "老师教我们读钟表上的数字。", "target_word": "钟表", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "这个商店卖各种便宜的钟表。", "target_word": "钟表", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "我把钟表放在桌子上了。", "target_word": "钟表", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "钟表的声音很吵，我睡不着。", "target_word": "钟表", "complexity_tier": "T2", "sentence_source": "generated"}], "morphological_forms": [{"form": "钟表店", "label": "复合"}, {"form": "钟表匠", "label": "复合"}, {"form": "鐘錶", "label": "繁体"}], "register": "中性", "sense_fingerprint": "用来看几点的日常工具", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '0f195968-6b0c-4b2a-8e22-a822d564ee90') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (22532, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "钟表", "is_correct": true, "explanation": "正确：钟表可以挂在墙上，句中“墙上有钟表”符合语境。"}, {"text": "天空", "is_correct": false, "explanation": "语义：天空不能挂在墙上，“墙上有天空”说不通。"}, {"text": "河流", "is_correct": false, "explanation": "搭配：“墙上”不与“河流”搭配，墙上不会有河流。"}, {"text": "空气", "is_correct": false, "explanation": "语义：空气看不见，也不能挂在墙上，句中说不通。"}], "explanations": {"钟表": "正确：钟表可以挂在墙上，句中“墙上有钟表”符合语境。", "天空": "语义：天空不能挂在墙上，“墙上有天空”说不通。", "河流": "搭配：“墙上”不与“河流”搭配，墙上不会有河流。", "空气": "语义：空气看不见，也不能挂在墙上，句中说不通。"}, "sentence_index": 0, "correct_answer": "钟表"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "他用钟表测量水的温度。", "explanation": "这里应该用〈温度计〉。测温度要用温度计，钟表只用来看时间。"}, {"text": "妈妈每个月都去查钟表的读数，然后交电费。", "explanation": "这里应该用〈电表〉。查表交费用的是计量用电的电表，钟表不计量电。"}, {"text": "这位卖菜的人用钟表称重量。", "explanation": "这里应该用〈秤〉。称重量要用秤，钟表不能用来称东西。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '5f7505f7-c7aa-4e1c-be2a-f731873138c7') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (22532, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "钟表", "is_correct": true, "explanation": "正确：钟表上有数字，老师可以教大家读，符合语境。"}, {"text": "白云", "is_correct": false, "explanation": "语义：白云上没有数字，无法读。"}, {"text": "海浪", "is_correct": false, "explanation": "语义：海浪上没有数字，也读不出什么来，句中说不通。"}, {"text": "树叶", "is_correct": false, "explanation": "搭配：“读……上的数字”一般搭配有刻度或显示的器物，“树叶”不搭配。"}], "explanations": {"钟表": "正确：钟表上有数字，老师可以教大家读，符合语境。", "白云": "语义：白云上没有数字，无法读。", "海浪": "语义：海浪上没有数字，也读不出什么来，句中说不通。", "树叶": "搭配：“读……上的数字”一般搭配有刻度或显示的器物，“树叶”不搭配。"}, "sentence_index": 6, "correct_answer": "钟表"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "我买了一本钟表。", "explanation": "量词错误：这里应该用〈块〉或〈个〉。“本”用于书籍，钟表不用“本”计量。"}, {"text": "妹妹买了一条钟表送给我。", "explanation": "量词错误：这里应该用〈块〉。“条”用于细长或成条的事物，钟表不用“条”。"}, {"text": "爸爸修好了一根钟表。", "explanation": "量词错误：这里应该用〈块〉。“根”用于细长条状的东西，钟表不用“根”。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '5f7505f7-c7aa-4e1c-be2a-f731873138c7') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (22532, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "这是我爷爷钟表，走得很准。", "corrected_sentence": "这是我爷爷的钟表，走得很准。", "error_description": "结构错误：“我爷爷”修饰“钟表”时，中间漏掉了结构助词“的”。正确说法是“我爷爷的钟表”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '5f7505f7-c7aa-4e1c-be2a-f731873138c7') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (22532, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "他买了一把钟表。", "corrected_sentence": "他买了一块钟表。", "error_description": "量词错误：“钟表”应使用量词“块”，“把”用于有柄的器具，不能用来计量钟表。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '5f7505f7-c7aa-4e1c-be2a-f731873138c7') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
