INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (22534, 1, 'prompt1_core', '{"pos": "动词", "semantic_class": "action", "definition": "让别人感到不舒服或生气。", "primary_collocate": null, "pronunciation": "mào fàn", "ipa": "maʊ˥˩ fan˥˩", "syllable_count": 2, "sentences": [{"text": "你这样说话，会冒犯很多人。", "target_word": "冒犯", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他的玩笑冒犯了我，我很生气。", "target_word": "冒犯", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "我怕冒犯朋友，所以没说实话。", "target_word": "冒犯", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "她不想冒犯老板，就笑着点了点头。", "target_word": "冒犯", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这个广告冒犯了很多观众，公司只好道歉。", "target_word": "冒犯", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他没有冒犯过任何人。", "target_word": "冒犯", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "说话要小心，别冒犯邻居。", "target_word": "冒犯", "complexity_tier": "T3", "furigana": "mào fàn", "sentence_source": "generated"}, {"text": "我的邮件冒犯了经理，他很不高兴。", "target_word": "冒犯", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "开玩笑也要注意，不要冒犯别人。", "target_word": "冒犯", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "小孩的问题很直接，但没有冒犯谁的意思。", "target_word": "冒犯", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "冒犯了", "label": "完成体"}, {"form": "冒犯过", "label": "经历体"}], "register": "中性", "sense_fingerprint": "冒犯：让别人不舒服或生气", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'ee5f3f14-cd74-4703-8299-71abdc569da6') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (22534, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "冒犯", "is_correct": true, "explanation": "正确。这样说话会让很多人感到不舒服，这正是“冒犯”。"}, {"text": "惊讶", "is_correct": false, "explanation": "语义：“惊讶”表示吃惊，是不及物动词，不能带“很多人”作宾语，句子不通。"}, {"text": "尊敬", "is_correct": false, "explanation": "语义：“尊敬”表示敬重，不能用来形容这样说话的后果。"}, {"text": "生气", "is_correct": false, "explanation": "配价：“生气”是不及物动词，不能直接带“很多人”作宾语，应说“让很多人生气”。"}], "explanations": {"冒犯": "正确。这样说话会让很多人感到不舒服，这正是“冒犯”。", "惊讶": "语义：“惊讶”表示吃惊，是不及物动词，不能带“很多人”作宾语，句子不通。", "尊敬": "语义：“尊敬”表示敬重，不能用来形容这样说话的后果。", "生气": "配价：“生气”是不及物动词，不能直接带“很多人”作宾语，应说“让很多人生气”。"}, "sentence_index": 0, "correct_answer": "冒犯"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "这个小孩偷了别人的钱，冒犯了学校的规定。", "explanation": "这里应该用〈触犯〉。冒犯指言行让人不舒服，违反规定、法律要用触犯。"}, {"text": "我冒犯了邻居的午休。", "explanation": "这里应该用〈打扰〉。冒犯针对人的感受，影响别人休息要用打扰。"}, {"text": "这次手术冒犯了他的身体。", "explanation": "这里应该用〈伤害〉。冒犯针对人的感受，身体受到的损害要用伤害。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'd7aa4f8e-1625-4992-b8d3-2a8d93671f30') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (22534, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "冒犯", "is_correct": true, "explanation": "正确。“别冒犯邻居”指不要让邻居感到不舒服。"}, {"text": "训练", "is_correct": false, "explanation": "搭配：“训练”多指培养技能，不用于人际言行，不说“训练邻居”。"}, {"text": "欢迎", "is_correct": false, "explanation": "语义：“欢迎”表示热情接待，与“说话要小心”的提醒不符。"}, {"text": "生气", "is_correct": false, "explanation": "配价：“生气”是不及物动词，不能说“别生气邻居”，应说“别对邻居生气”。"}], "explanations": {"冒犯": "正确。“别冒犯邻居”指不要让邻居感到不舒服。", "训练": "搭配：“训练”多指培养技能，不用于人际言行，不说“训练邻居”。", "欢迎": "语义：“欢迎”表示热情接待，与“说话要小心”的提醒不符。", "生气": "配价：“生气”是不及物动词，不能说“别生气邻居”，应说“别对邻居生气”。"}, "sentence_index": 6, "correct_answer": "冒犯"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "他冒犯了这座古老的桥。", "explanation": "这里应该用〈破坏〉。冒犯的对象是人，古桥等物体受损要用破坏。"}, {"text": "大家都冒犯他的才华。", "explanation": "这里应该用〈赞叹〉。冒犯让人不快，称赞别人的才华要用赞叹。"}, {"text": "他仔细冒犯了一下，才做出决定。", "explanation": "这里应该用〈考虑〉。“仔细……一下”后面要接“考虑”，冒犯不能这样用。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'd7aa4f8e-1625-4992-b8d3-2a8d93671f30') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (22534, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "他开玩笑太过分，冒犯得很多同学。", "corrected_sentence": "他开玩笑太过分，冒犯了很多同学。", "error_description": "错误：“冒犯”后要用动态助词“了”表示动作已经发生，不能用补语标记“得”。应为“冒犯了很多同学”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'd7aa4f8e-1625-4992-b8d3-2a8d93671f30') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (22534, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "我从来没冒犯了同事。", "corrected_sentence": "我从来没冒犯过同事。", "error_description": "错误：“从来没”后面要用“过”表示经历，不能用“了”。应为“从来没冒犯过同事”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'd7aa4f8e-1625-4992-b8d3-2a8d93671f30') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
