INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (22536, 1, 'prompt1_core', '{"pos": "名词", "semantic_class": "abstract", "definition": "商务就是买卖东西的事情。", "primary_collocate": null, "pronunciation": "shāng wù", "ipa": "ʂɑŋ˥ u˥˩", "syllable_count": 2, "sentences": [{"text": "他常年在外面忙商务。", "target_word": "商务", "complexity_tier": "T1", "sentence_source": "generated"}, {"text": "我爸爸从事商务工作，常年在外地跟客户打交道。", "target_word": "商务", "complexity_tier": "T3", "furigana": "wǒ bàba cóngshì shāngwù gōngzuò, chángnián zài wàidì gēn kèhù dǎ jiāodao.", "sentence_source": "generated"}, {"text": "这次出国是为了商务，不是玩。", "target_word": "商务", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "商务上的朋友常常一起吃饭。", "target_word": "商务", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "他很懂商务，会跟人谈价钱。", "target_word": "商务", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "她刚学会一点商务知识。", "target_word": "商务", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "商务很忙，他今天没有回家。", "target_word": "商务", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "我想学习商务，以后自己开店。", "target_word": "商务", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "他精通商务，把公司经营得很好，赚了很多钱。", "target_word": "商务", "complexity_tier": "T3", "furigana": "tā jīngtōng shāngwù, bǎ gōngsī jīngyíng de hěn hǎo, zhuànle hěn duō qián.", "sentence_source": "generated"}, {"text": "这位先生来这里办商务。", "target_word": "商务", "complexity_tier": "T2", "sentence_source": "generated"}], "morphological_forms": [{"form": "商务舱", "label": "复合"}, {"form": "商务英语", "label": "复合"}, {"form": "商務", "label": "繁体"}], "register": "中性", "sense_fingerprint": "买卖东西的事情", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '0f195968-6b0c-4b2a-8e22-a822d564ee90') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (22536, 1, 'prompt2_exercises_A', '{"level_1": {"options": [{"text": "商务", "is_correct": true, "explanation": "正确：商务，shāng wù，指买卖东西的事情。"}, {"text": "上午", "is_correct": false, "explanation": "shàng wǔ 与 shāng wù 两个音节的声调都不同，意思是上午。"}, {"text": "尚武", "is_correct": false, "explanation": "shàng wǔ 与 shāng wù 两个音节的声调都不同，意思是崇尚武力。"}, {"text": "晌午", "is_correct": false, "explanation": "shǎng wu 与 shāng wù 声调不同，意思是中午，多用于口语。"}], "explanations": {"商务": "正确：商务，shāng wù，指买卖东西的事情。", "上午": "shàng wǔ 与 shāng wù 两个音节的声调都不同，意思是上午。", "尚武": "shàng wǔ 与 shāng wù 两个音节的声调都不同，意思是崇尚武力。", "晌午": "shǎng wu 与 shāng wù 声调不同，意思是中午，多用于口语。"}, "sentence_index": null, "correct_answer": "商务"}, "level_3": {"options": [{"text": "商务", "is_correct": true, "explanation": "正确：“忙商务”指忙于买卖东西的事情，符合句意。"}, {"text": "感情", "is_correct": false, "explanation": "搭配：“忙”通常接事务，“忙感情”不自然。"}, {"text": "天气", "is_correct": false, "explanation": "语义：天气不是可以忙碌的事务，“忙天气”不通。"}, {"text": "海洋", "is_correct": false, "explanation": "语义：海洋不是事务，句中不能说忙海洋。"}], "explanations": {"商务": "正确：“忙商务”指忙于买卖东西的事情，符合句意。", "感情": "搭配：“忙”通常接事务，“忙感情”不自然。", "天气": "语义：天气不是可以忙碌的事务，“忙天气”不通。", "海洋": "语义：海洋不是事务，句中不能说忙海洋。"}, "sentence_index": 0, "correct_answer": "商务"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "他的商务很好听。", "explanation": "这里应该用〈歌〉。商务指买卖东西的事情，不能用来形容歌曲好听。"}, {"text": "这幅画的商务很美。", "explanation": "这里应该用〈颜色〉。商务指买卖东西的事情，不指画面的色彩。"}, {"text": "那片草地的商务很香。", "explanation": "这里应该用〈花〉。商务指买卖东西的事情，不指花的香味。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '5f7505f7-c7aa-4e1c-be2a-f731873138c7') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (22536, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "商务", "is_correct": true, "explanation": "正确：“商务很忙”指买卖东西的事务很忙，符合句意。"}, {"text": "花园", "is_correct": false, "explanation": "语义：花园不是事务，“花园很忙”不通。"}, {"text": "地震", "is_correct": false, "explanation": "语义：地震是灾害，不能用“很忙”来形容，句中不通。"}, {"text": "感冒", "is_correct": false, "explanation": "搭配：“感冒”不能被“很忙”修饰，二者不搭配。"}], "explanations": {"商务": "正确：“商务很忙”指买卖东西的事务很忙，符合句意。", "花园": "语义：花园不是事务，“花园很忙”不通。", "地震": "语义：地震是灾害，不能用“很忙”来形容，句中不通。", "感冒": "搭配：“感冒”不能被“很忙”修饰，二者不搭配。"}, "sentence_index": 6, "correct_answer": "商务"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "商务哭了一下午。", "explanation": "这里应该用〈孩子〉。商务指买卖东西的事情，不能做“哭”的主语。"}, {"text": "商务在院子里跑。", "explanation": "这里应该用〈小狗〉。商务指买卖东西的事情，不能做“跑”的主语。"}, {"text": "他写的商务很美。", "explanation": "这里应该用〈诗〉。商务指买卖东西的事情，不指写出来供人欣赏的诗。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '5f7505f7-c7aa-4e1c-be2a-f731873138c7') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (22536, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "他常年在外地商务，很少回家。", "corrected_sentence": "他常年在外地做商务，很少回家。", "error_description": "宾语错误：“商务”作名词，前面要加动词“做”，应说“做商务”，不能直接说“在外地商务”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '5f7505f7-c7aa-4e1c-be2a-f731873138c7') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (22536, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "他经常跟外国客户谈一个商务。", "corrected_sentence": "他经常跟外国客户谈一项商务。", "error_description": "量词错误：“商务”指买卖事务，计量应用“项”，“个”一般用于具体的人或物，不用于这类事务。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '5f7505f7-c7aa-4e1c-be2a-f731873138c7') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (22538, 1, 'llm_types_A', '{"synonym_antonym_match": {"relation": "antonym", "options": [{"text": "缩短", "is_correct": true, "explanation": "正确。缩短与延长在时间或长度上意思相反，是反义关系。"}, {"text": "维持", "is_correct": false, "explanation": "维持指保持原状，与延长没有反义关系。"}, {"text": "排列", "is_correct": false, "explanation": "排列指按顺序摆放，与延长不是反义词。"}, {"text": "询问", "is_correct": false, "explanation": "询问指问问题，与延长无关，不构成反义。"}], "correct_answer": "缩短", "explanations": {"缩短": "正确。缩短与延长在时间或长度上意思相反，是反义关系。", "维持": "维持指保持原状，与延长没有反义关系。", "排列": "排列指按顺序摆放，与延长不是反义词。", "询问": "询问指问问题，与延长无关，不构成反义。"}, "sentence_index": 3}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'd7aa4f8e-1625-4992-b8d3-2a8d93671f30') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (22538, 1, 'llm_types_B', '{"synonym_antonym_match": {"relation": "antonym", "options": [{"text": "缩短", "is_correct": true, "explanation": "正确。缩短与延长在时间或距离上意思相反，是反义关系。"}, {"text": "保管", "is_correct": false, "explanation": "保管指妥善收藏，与延长不是反义关系。"}, {"text": "赞美", "is_correct": false, "explanation": "赞美指称赞，与延长没有反义关系。"}, {"text": "发表", "is_correct": false, "explanation": "发表指公开表达意见或作品，与延长不构成反义。"}], "correct_answer": "缩短", "explanations": {"缩短": "正确。缩短与延长在时间或距离上意思相反，是反义关系。", "保管": "保管指妥善收藏，与延长不是反义关系。", "赞美": "赞美指称赞，与延长没有反义关系。", "发表": "发表指公开表达意见或作品，与延长不构成反义。"}, "sentence_index": 9}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'd7aa4f8e-1625-4992-b8d3-2a8d93671f30') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (22538, 1, 'prompt1_core', '{"pos": "动词", "semantic_class": "action", "definition": "让时间或距离变得更长。", "primary_collocate": null, "pronunciation": "yán cháng", "ipa": "jɛn˧˥ ʈʂʰɑŋ˧˥", "syllable_count": 2, "sentences": [{"text": "老师把考试时间延长了十分钟。", "target_word": "延长", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "工人们正在延长这条公路。", "target_word": "延长", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "学校延长了暑假。", "target_word": "延长", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "为了等客人，我们把晚饭的时间延长了一会儿。", "target_word": "延长", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "图书馆想延长开门时间，让学生多看书。", "target_word": "延长", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "经理同意延长我的试用期。", "target_word": "延长", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他想延长这次旅行，多住三天。", "target_word": "延长", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "河水太宽，桥得再延长五十米。", "target_word": "延长", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "请你把合同延长一年，好吗？", "target_word": "延长", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "活动很受欢迎，所以主办方延长了展览时间。", "target_word": "延长", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "延长了", "label": "完成体"}, {"form": "延长过", "label": "经历体"}, {"form": "延长线", "label": "复合词"}], "register": "中性", "sense_fingerprint": "延长：让时间或距离变得更长", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'ee5f3f14-cd74-4703-8299-71abdc569da6') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (22538, 1, 'prompt2_exercises_A', '{"level_1": {"options": [{"text": "延长", "is_correct": true, "explanation": "正确。延长 yán cháng：让时间或距离变得更长。"}, {"text": "绵长", "is_correct": false, "explanation": "mián（第二声）与 yán 声母不同（m/y），绵长意思是长而连续，不表示使时间变长。"}, {"text": "羊肠", "is_correct": false, "explanation": "yáng 与 yán 韵母不同（ang/an），羊肠指羊的肠子，常用于“羊肠小道”，不是延长。"}, {"text": "扬长", "is_correct": false, "explanation": "yáng 与 yán 韵母不同（ang/an），扬长意思是扬起，多用于“扬长而去”，不是延长。"}, {"text": "檐廊", "is_correct": false, "explanation": "láng 与 cháng 声母不同（l/ch），檐廊指房檐下的走廊，不是延长。"}], "explanations": {"延长": "正确。延长 yán cháng：让时间或距离变得更长。", "绵长": "mián（第二声）与 yán 声母不同（m/y），绵长意思是长而连续，不表示使时间变长。", "羊肠": "yáng 与 yán 韵母不同（ang/an），羊肠指羊的肠子，常用于“羊肠小道”，不是延长。", "扬长": "yáng 与 yán 韵母不同（ang/an），扬长意思是扬起，多用于“扬长而去”，不是延长。", "檐廊": "láng 与 cháng 声母不同（l/ch），檐廊指房檐下的走廊，不是延长。"}, "sentence_index": null, "correct_answer": "延长"}, "level_3": {"options": [{"text": "延长", "is_correct": true, "explanation": "正确。“把考试时间延长了十分钟”指让考试时间变长。"}, {"text": "收取", "is_correct": false, "explanation": "搭配：“收取”用于费用，不能说“收取时间”。"}, {"text": "摆脱", "is_correct": false, "explanation": "语义：“摆脱”指脱离某种束缚，时间不能被摆脱，句子说不通。"}, {"text": "剩下", "is_correct": false, "explanation": "配价：“剩下”是不及物动词，不能用“把＋宾语＋剩下”的结构。"}], "explanations": {"延长": "正确。“把考试时间延长了十分钟”指让考试时间变长。", "收取": "搭配：“收取”用于费用，不能说“收取时间”。", "摆脱": "语义：“摆脱”指脱离某种束缚，时间不能被摆脱，句子说不通。", "剩下": "配价：“剩下”是不及物动词，不能用“把＋宾语＋剩下”的结构。"}, "sentence_index": 0, "correct_answer": "延长"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "这次会议的效率延长了一倍。", "explanation": "这里应该用〈提高〉。延长指时间或距离的增加，效率的提升要用提高。"}, {"text": "学校延长了招生规模。", "explanation": "这里应该用〈扩大〉。延长只用于时间或距离，招生规模等范围的增大要用扩大。"}, {"text": "老师延长了我们的安全意识。", "explanation": "这里应该用〈加强〉。延长只用于时间或距离，安全意识等抽象能力的增强要用加强。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'd7aa4f8e-1625-4992-b8d3-2a8d93671f30') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (22538, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "延长", "is_correct": true, "explanation": "正确。“他想延长这次旅行，多住三天”表示让旅行时间变长。"}, {"text": "缩短", "is_correct": false, "explanation": "语义：“缩短旅行”与后文“多住三天”的意思相反。"}, {"text": "取消", "is_correct": false, "explanation": "语义：“取消旅行”就不会多住三天，与后文矛盾。"}, {"text": "收拾", "is_correct": false, "explanation": "搭配：“收拾”多用于行李、房间，不说“收拾旅行”。"}], "explanations": {"延长": "正确。“他想延长这次旅行，多住三天”表示让旅行时间变长。", "缩短": "语义：“缩短旅行”与后文“多住三天”的意思相反。", "取消": "语义：“取消旅行”就不会多住三天，与后文矛盾。", "收拾": "搭配：“收拾”多用于行李、房间，不说“收拾旅行”。"}, "sentence_index": 6, "correct_answer": "延长"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "工厂的生产成本延长了三成。", "explanation": "这里应该用〈增加〉。延长只用于时间或距离，成本等数量的增加要用增加。"}, {"text": "寒流让房间的气温延长了五度。", "explanation": "这里应该用〈降低〉。气温的下降要用降低，延长只用于时间或距离。"}, {"text": "他的努力延长了成绩。", "explanation": "这里应该用〈提升〉。成绩的提高要用提升，延长只用于时间或距离。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'd7aa4f8e-1625-4992-b8d3-2a8d93671f30') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (22538, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "我们把晚会的时间延长十点。", "corrected_sentence": "我们把晚会的时间延长到十点。", "error_description": "错误：“十点”是时间点，不能直接作延长的时长补足语。表示延长后的终点要用“延长到……”，应为“延长到十点”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'd7aa4f8e-1625-4992-b8d3-2a8d93671f30') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (22538, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "工人们把这条公路延长了一条。", "corrected_sentence": "工人们把这条公路延长了一公里。", "error_description": "错误：表示延长距离的数量词应为“一公里”。“一条”是公路的量词，不能用来计量延长的长度。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'd7aa4f8e-1625-4992-b8d3-2a8d93671f30') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
