INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (22540, 1, 'prompt1_core', '{"pos": "名词", "semantic_class": "abstract", "definition": "生活节奏就是每天做事情的速度，像快快的或者慢慢的。", "primary_collocate": null, "pronunciation": "shēng huó jié zòu", "ipa": "ʂɤŋ˥ xuɔ˧˥ tɕjɛ˧˥ tsoʊ˥˩", "syllable_count": 4, "sentences": [{"text": "我喜欢慢一点的生活节奏。", "target_word": "生活节奏", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他的生活节奏太快，没时间吃早饭。", "target_word": "生活节奏", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "农村的生活节奏比城市慢。", "target_word": "生活节奏", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "每天上课、打球、睡觉，这是我的生活节奏。", "target_word": "生活节奏", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "你的生活节奏怎么样，忙不忙？", "target_word": "生活节奏", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "工作多了以后，我得调整生活节奏。", "target_word": "生活节奏", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "新同事很快就习惯了公司的生活节奏。", "target_word": "生活节奏", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "快乐的假期让我的生活节奏变慢了。", "target_word": "生活节奏", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他想加快生活节奏，多做一点事。", "target_word": "生活节奏", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "夏天太热，大家的生活节奏都慢下来了。", "target_word": "生活节奏", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [], "register": "中性", "sense_fingerprint": "生活节奏：每天做事情的快慢", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'ee5f3f14-cd74-4703-8299-71abdc569da6') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (22540, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "生活节奏", "is_correct": true, "explanation": "正确：“慢一点的”形容节奏的快慢，与“生活节奏”相配。"}, {"text": "工资", "is_correct": false, "explanation": "搭配：“慢一点”说速度，工资没有快慢之分。"}, {"text": "体重", "is_correct": false, "explanation": "语义：体重是人或物的重量，不能用“慢一点”来形容。"}, {"text": "字体", "is_correct": false, "explanation": "语义：字体是字的样式，没有快慢之分。"}], "explanations": {"生活节奏": "正确：“慢一点的”形容节奏的快慢，与“生活节奏”相配。", "工资": "搭配：“慢一点”说速度，工资没有快慢之分。", "体重": "语义：体重是人或物的重量，不能用“慢一点”来形容。", "字体": "语义：字体是字的样式，没有快慢之分。"}, "sentence_index": 0, "correct_answer": "生活节奏"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "这首曲子的生活节奏很快，听起来很带劲。", "explanation": "这里应该用〈节拍〉。节拍指音乐的拍子，生活节奏指人每天做事的快慢，不用来形容曲子。"}, {"text": "她迈着轻快的生活节奏走进教室。", "explanation": "这里应该用〈步伐〉。步伐指走路的脚步，生活节奏不用来描述走路的样子。"}, {"text": "这支舞很有生活节奏，每个动作都很整齐。", "explanation": "这里应该用〈节奏感〉。节奏感指舞蹈或音乐的节拍感，生活节奏不用来形容舞蹈。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'd7aa4f8e-1625-4992-b8d3-2a8d93671f30') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (22540, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "生活节奏", "is_correct": true, "explanation": "正确：“习惯了”指适应公司的日常节奏和方式，与“生活节奏”相配。"}, {"text": "股价", "is_correct": false, "explanation": "搭配：“习惯了”说的是环境或做事方式，不说股价。"}, {"text": "身高", "is_correct": false, "explanation": "体貌：身高是人的体形特征，不能说习惯了公司的身高。"}, {"text": "年龄", "is_correct": false, "explanation": "语义：年龄不会随公司环境改变，也不存在“习惯”的问题。"}], "explanations": {"生活节奏": "正确：“习惯了”指适应公司的日常节奏和方式，与“生活节奏”相配。", "股价": "搭配：“习惯了”说的是环境或做事方式，不说股价。", "身高": "体貌：身高是人的体形特征，不能说习惯了公司的身高。", "年龄": "语义：年龄不会随公司环境改变，也不存在“习惯”的问题。"}, "sentence_index": 6, "correct_answer": "生活节奏"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "他这一年的生活节奏长高了五厘米。", "explanation": "这里应该用〈身高〉。身高指人的身体高度，可以说“长高了五厘米”；生活节奏是日常活动的快慢规律，不能用来计量身高。"}, {"text": "这碗汤的生活节奏很鲜。", "explanation": "这里应该用〈味道〉。味道指食物的滋味，可以说“很鲜”；生活节奏不用来形容食物的滋味。"}, {"text": "这里的生活节奏太烫了。", "explanation": "这里应该用〈水温〉。水温指水的冷热，可以说“太烫了”；生活节奏不能用“烫”来形容。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'd7aa4f8e-1625-4992-b8d3-2a8d93671f30') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (22540, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "她慢慢适合了这里的生活节奏。", "corrected_sentence": "她慢慢适应了这里的生活节奏。", "error_description": "动词错误：说人对生活节奏的适应应用“适应”，“适合”指东西符合某种需要或条件，不能用于人对生活节奏的适应。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'd7aa4f8e-1625-4992-b8d3-2a8d93671f30') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (22540, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "她想过一条平静的生活节奏。", "corrected_sentence": "她想过一种平静的生活节奏。", "error_description": "量词错误：“生活节奏”应用量词“种”，不用“条”，应说“一种平静的生活节奏”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'd7aa4f8e-1625-4992-b8d3-2a8d93671f30') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
