INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (22558, 1, 'prompt1_core', '{"pos": "动词", "semantic_class": "action", "definition": "把心思放在重要的事情上。", "primary_collocate": null, "pronunciation": "zhù zhòng", "ipa": "ʈʂu˥˩ ʈʂʊŋ˥˩", "syllable_count": 2, "sentences": [{"text": "学外语要注重听和说。", "target_word": "注重", "complexity_tier": "T1", "sentence_source": "generated"}, {"text": "写文章时，他注重细节。", "target_word": "注重", "complexity_tier": "T1", "sentence_source": "generated"}, {"text": "我们应该注重身体健康。", "target_word": "注重", "complexity_tier": "T1", "sentence_source": "generated"}, {"text": "她做事注重效率，从不拖拉。", "target_word": "注重", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "这次比赛，教练更注重团队合作。", "target_word": "注重", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "他说话很注重方式，不会让人难过。", "target_word": "注重", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "孩子学习时，要注重方法，不要只靠时间。", "target_word": "注重", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他做事注重每一个小细节，从不马虎。", "target_word": "注重", "complexity_tier": "T3", "furigana": "zhù zhòng", "sentence_source": "generated"}, {"text": "工作时，我们要注重安全，别着急。", "target_word": "注重", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "老板注重员工的想法，所以大家都愿意说话。", "target_word": "注重", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "注重了", "label": "体标"}, {"form": "注重过", "label": "体标"}], "register": "中性", "sense_fingerprint": "注重：把心思和精力放在重要的方面", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'ee5f3f14-cd74-4703-8299-71abdc569da6') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (22558, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "注重", "is_correct": true, "explanation": "正确。“注重听和说”指把心思放在听和说的训练上，符合“把心思放在重要的事情上”的意思。"}, {"text": "忘记", "is_correct": false, "explanation": "语义：“忘记”与“要……”的积极要求相反，句子语义不通。"}, {"text": "拖延", "is_correct": false, "explanation": "语义：“拖延”表示推迟，与“把心思放在重要的事情上”相反。"}, {"text": "违反", "is_correct": false, "explanation": "搭配：“违反”带的是规定或规则，不能说“违反听和说”。"}], "explanations": {"注重": "正确。“注重听和说”指把心思放在听和说的训练上，符合“把心思放在重要的事情上”的意思。", "忘记": "语义：“忘记”与“要……”的积极要求相反，句子语义不通。", "拖延": "语义：“拖延”表示推迟，与“把心思放在重要的事情上”相反。", "违反": "搭配：“违反”带的是规定或规则，不能说“违反听和说”。"}, "sentence_index": 0, "correct_answer": "注重"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "他在路上突然注重一辆车，一直盯着看。", "explanation": "这里应该用〈注意〉（注意到一辆车）。注重表示长期看重，不能描述路上突然留意到某物。"}, {"text": "学生在外面要注重陌生人，别跟他们走。", "explanation": "这里应该用〈警惕〉。警惕指提高戒备、防备危险；“注重陌生人”不表示这个意思。"}, {"text": "过马路要注重车辆，别分心。", "explanation": "这里应该用〈留神〉。留神指小心留意眼前的情况；注重表示长期看重的事，不适用于过马路时的即时提醒。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'd7aa4f8e-1625-4992-b8d3-2a8d93671f30') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (22558, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "注重", "is_correct": true, "explanation": "正确。“注重方法”与“不要只靠时间”形成对比，符合“把心思放在重要的事情上”的定义。"}, {"text": "嘲笑", "is_correct": false, "explanation": "语义：“嘲笑”表示讥笑，与“要”所表达的积极要求相反，句子语义不通。"}, {"text": "咬", "is_correct": false, "explanation": "搭配：“咬”的对象多是物体或身体部位，不能说“咬方法”。"}, {"text": "鼓掌", "is_correct": false, "explanation": "搭配：“鼓掌”是动作，不能与“方法”搭配，说“鼓掌方法”不通。"}], "explanations": {"注重": "正确。“注重方法”与“不要只靠时间”形成对比，符合“把心思放在重要的事情上”的定义。", "嘲笑": "语义：“嘲笑”表示讥笑，与“要”所表达的积极要求相反，句子语义不通。", "咬": "搭配：“咬”的对象多是物体或身体部位，不能说“咬方法”。", "鼓掌": "搭配：“鼓掌”是动作，不能与“方法”搭配，说“鼓掌方法”不通。"}, "sentence_index": 6, "correct_answer": "注重"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "他注重碗里的油污，洗了很久才洗干净。", "explanation": "这里应该用〈清除〉（清除油污）。注重表示看重某事，不能表示去掉油污。"}, {"text": "我在窗前注重一朵白云，看了很久。", "explanation": "这里应该用〈欣赏〉（欣赏一朵白云）。注重表示看重某事，不能表示观赏景物。"}, {"text": "她注重着窗外的雪，忘了吃饭。", "explanation": "这里应该用〈凝望〉。注重表示心理上的看重，不能表示目光持续地望向窗外。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'd7aa4f8e-1625-4992-b8d3-2a8d93671f30') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (22558, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "学习外语应该注重了口语。", "corrected_sentence": "学习外语应该注重口语。", "error_description": "“了”表示已完成，与“应该”表示的应然语气不符，应去掉“了”，说“应该注重口语”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'd7aa4f8e-1625-4992-b8d3-2a8d93671f30') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (22558, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "他的注重细节。", "corrected_sentence": "他很注重细节。", "error_description": "结构错误：“的”不能放在“他”与动词“注重”之间代替副词，句子因此缺少完整谓语；应改用程度副词“很”，说“他很注重细节”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'd7aa4f8e-1625-4992-b8d3-2a8d93671f30') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (22562, 1, 'llm_types_A', '{}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'aba9b977-9c6a-4780-927e-2733c92d52a2') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (22562, 1, 'llm_types_B', '{}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'aba9b977-9c6a-4780-927e-2733c92d52a2') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (22562, 1, 'prompt1_core', '{"pos": "名词", "semantic_class": "abstract", "definition": "情境就是一个人在做事情时，周围的样子和情况。", "primary_collocate": null, "pronunciation": "qíng jìng", "ipa": "tɕʰiŋ˧˥ tɕiŋ˥˩", "syllable_count": 2, "sentences": [{"text": "在安静的情境里，孩子更容易学习。", "target_word": "情境", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "老师为学生创设了一个下雪天的情境。", "target_word": "情境", "complexity_tier": "T3", "furigana": "lǎo shī wèi xué shēng chuàng shè le yí ge xià xuě tiān de qíng jìng 。", "sentence_source": "generated"}, {"text": "这个相似的情境让他想起了小时候的事。", "target_word": "情境", "complexity_tier": "T3", "furigana": "zhè ge xiāng sì de qíng jìng ràng tā xiǎng qǐ le xiǎo shí hou de shì 。", "sentence_source": "generated"}, {"text": "老师请大家说说自己做作业时的情境。", "target_word": "情境", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "比赛的情境太紧张，他一句话也说不出来。", "target_word": "情境", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "请你描述一下当时的情境。", "target_word": "情境", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "在这样的情境下，谁都会害怕。", "target_word": "情境", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "孩子们在游戏情境中学会了说英语。", "target_word": "情境", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "我喜欢在轻松的情境里工作。", "target_word": "情境", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "人在陌生的情境里，常常会变得拘谨。", "target_word": "情境", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "种", "label": "量词"}], "register": "通用", "sense_fingerprint": "人做事时周围的样子和情况", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '397a99f4-7813-4bc2-8e8d-66e04969afa9') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (22562, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "颜色", "is_correct": false, "explanation": "搭配：“安静”可以修饰环境或声音，不能修饰颜色，“安静的颜色”不通。"}, {"text": "气味", "is_correct": false, "explanation": "搭配：“安静”不能修饰气味，“安静的气味”不成立。"}, {"text": "脾气", "is_correct": false, "explanation": "语义：脾气指人的性情，不是孩子学习所处的场所，“在安静的脾气里”文意不通。"}, {"text": "情境", "is_correct": true, "explanation": "情境指人做事时周围的样子和情况，这里指孩子学习时安静的周围情况，符合语境。"}], "explanations": {"颜色": "搭配：“安静”可以修饰环境或声音，不能修饰颜色，“安静的颜色”不通。", "气味": "搭配：“安静”不能修饰气味，“安静的气味”不成立。", "脾气": "语义：脾气指人的性情，不是孩子学习所处的场所，“在安静的脾气里”文意不通。", "情境": "情境指人做事时周围的样子和情况，这里指孩子学习时安静的周围情况，符合语境。"}, "sentence_index": 0, "correct_answer": "情境"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "我们要保护好地球的情境，不能乱扔垃圾。", "explanation": "这里应该用〈环境〉。保护的是自然界的环境；情境指人做事时周围的情况，不用于说大自然。"}, {"text": "他今天的情境很好，一直在笑。", "explanation": "这里应该用〈心情〉。说人的内心感受要用心情；情境指外部周围的情况，不指人的情绪。"}, {"text": "他在公司的情境很高，大家都很尊敬他。", "explanation": "这里应该用〈地位〉。说在公司的身份高低要用地位；情境指周围的样子和情况，不用于说人的社会地位。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'aba9b977-9c6a-4780-927e-2733c92d52a2') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (22562, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "口味", "is_correct": false, "explanation": "搭配：“口味”指食物或饮食的偏好，不能用“在…下”说明让人害怕的情况。"}, {"text": "身材", "is_correct": false, "explanation": "体貌：身材描述人的体型，不能说明让人害怕的周围情况，“在这样的身材下”不通。"}, {"text": "头发", "is_correct": false, "explanation": "搭配：头发是身体部位，不能作为“在…下”的情况，“在这样的头发下”不成立。"}, {"text": "情境", "is_correct": true, "explanation": "情境指人做事时周围的样子和情况，这里指让人害怕的周围情况，符合语境。"}], "explanations": {"口味": "搭配：“口味”指食物或饮食的偏好，不能用“在…下”说明让人害怕的情况。", "身材": "体貌：身材描述人的体型，不能说明让人害怕的周围情况，“在这样的身材下”不通。", "头发": "搭配：头发是身体部位，不能作为“在…下”的情况，“在这样的头发下”不成立。", "情境": "情境指人做事时周围的样子和情况，这里指让人害怕的周围情况，符合语境。"}, "sentence_index": 6, "correct_answer": "情境"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "今天的情境很晴朗，适合去郊游。", "explanation": "这里应该用〈天气〉。晴朗形容天气；情境指人做事时周围的样子和情况，不用于说天气。"}, {"text": "这个孩子的情境很开朗，喜欢和大家一起玩。", "explanation": "这里应该用〈性格〉。开朗形容的是性格；情境指周围的样子和情况，不用于形容人的性格。"}, {"text": "这个包的情境很结实。", "explanation": "这里应该用〈材料〉。说物品结不结实要看它的材料；情境指人做事时周围的样子和情况，不用于形容物品。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'aba9b977-9c6a-4780-927e-2733c92d52a2') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (22562, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "我们在游戏里创造了一件有趣的情境。", "corrected_sentence": "我们在游戏里创造了一种有趣的情境。", "error_description": "量词错误：“情境”应用量词“种”，不能用“件”（件多用于事情、物品）。正确说法是“一种有趣的情境”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'aba9b977-9c6a-4780-927e-2733c92d52a2') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (22562, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "这是一个让人放松情境。", "corrected_sentence": "这是一个让人放松的情境。", "error_description": "“的”缺失：“让人放松”修饰“情境”，中间要加“的”，应说“让人放松的情境”，不能省略“的”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'aba9b977-9c6a-4780-927e-2733c92d52a2') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
