INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (22572, 1, 'prompt1_core', '{"pos": "动词", "semantic_class": "action", "definition": "让一个东西或事情开始有。", "primary_collocate": null, "pronunciation": "jiàn lì", "ipa": "tɕjɛn˥˩ li˥˩", "syllable_count": 2, "sentences": [{"text": "他们在这里建立了一家公司。", "target_word": "建立", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "好朋友要互相信任，才能建立友谊。", "target_word": "建立", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "新同学之间慢慢建立了友谊。", "target_word": "建立", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这个国家是一九四九年建立的。", "target_word": "建立", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "我们要建立好的学习习惯。", "target_word": "建立", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "公司想和你们建立长期的关系。", "target_word": "建立", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "孩子要先建立自信。", "target_word": "建立", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他们建立了一个学习小组。", "target_word": "建立", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "两国在去年建立了外交关系。", "target_word": "建立", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "要建立信任，需要很长时间。", "target_word": "建立", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "建立了", "label": "体标"}, {"form": "建立过", "label": "体标"}, {"form": "建立起来", "label": "复合"}], "register": "书面", "sense_fingerprint": "使机构、关系、制度等开始存在", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'e5d813a3-5c7c-4c35-a022-bcb120b67276') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (22572, 1, 'prompt2_exercises_A', '{"level_1": {"options": [{"text": "简历", "is_correct": false, "explanation": "简历 jiǎn lì 与 建立 jiàn lì 第一个音节声调不同（三声与四声），意思是个人的工作与学习经历材料"}, {"text": "站立", "is_correct": false, "explanation": "站立 zhàn lì 与 建立 jiàn lì 声母不同（zh 与 j），意思是直立站着"}, {"text": "建立", "is_correct": true, "explanation": "正确。建立 jiàn lì，意思是使机构、关系、制度等开始存在"}, {"text": "尖利", "is_correct": false, "explanation": "尖利 jiān lì 与 建立 jiàn lì 第一个音节声调不同（一声与四声），意思是锋利"}, {"text": "建议", "is_correct": false, "explanation": "建议 jiàn yì 与 建立 jiàn lì 第二个音节声母不同（y 与 l），意思是提出意见"}], "explanations": {"简历": "简历 jiǎn lì 与 建立 jiàn lì 第一个音节声调不同（三声与四声），意思是个人的工作与学习经历材料", "站立": "站立 zhàn lì 与 建立 jiàn lì 声母不同（zh 与 j），意思是直立站着", "建立": "正确。建立 jiàn lì，意思是使机构、关系、制度等开始存在", "尖利": "尖利 jiān lì 与 建立 jiàn lì 第一个音节声调不同（一声与四声），意思是锋利", "建议": "建议 jiàn yì 与 建立 jiàn lì 第二个音节声母不同（y 与 l），意思是提出意见"}, "sentence_index": null, "correct_answer": "建立"}, "level_3": {"options": [{"text": "修建", "is_correct": false, "explanation": "搭配：「修建」多用于建筑、道路等，不用来说开办公司"}, {"text": "建立", "is_correct": true, "explanation": "正确。建立指使机构开始存在，与“一家公司”搭配"}, {"text": "喜欢", "is_correct": false, "explanation": "语义：「喜欢」表示情感，不能表示开办一家公司"}, {"text": "吃", "is_correct": false, "explanation": "语义：「吃」是进食动作，不能指开办公司"}], "explanations": {"修建": "搭配：「修建」多用于建筑、道路等，不用来说开办公司", "建立": "正确。建立指使机构开始存在，与“一家公司”搭配", "喜欢": "语义：「喜欢」表示情感，不能表示开办一家公司", "吃": "语义：「吃」是进食动作，不能指开办公司"}, "sentence_index": 0, "correct_answer": "建立"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "这座桥是去年建立的。", "explanation": "这里应该用〈建造〉。建立指使机构、关系、制度开始存在，桥梁等建筑要说〈建造〉"}, {"text": "这座楼是他建立的。", "explanation": "这里应该用〈建造〉。建立指使机构、关系、制度开始存在，楼房等实物要说〈建造〉"}, {"text": "工人们已经建立好了那条管道。", "explanation": "这里应该用〈铺设〉。管道等线状设施要说〈铺设〉，不说建立"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'dc0cc312-6c8a-4816-81d1-52075941a40b') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (22572, 1, 'prompt2_exercises_B', '{"level_1": {"options": [{"text": "奖励", "is_correct": false, "explanation": "奖励 jiǎng lì 与 建立 jiàn lì 第一个音节韵母不同（ang 与 an）且声调不同，意思是对好的表现给予鼓励或奖赏"}, {"text": "建立", "is_correct": true, "explanation": "正确。建立 jiàn lì，意思是使机构、关系、制度等开始存在"}, {"text": "便利", "is_correct": false, "explanation": "便利 biàn lì 与 建立 jiàn lì 第一个音节声母不同（b 与 j），意思是方便"}, {"text": "近利", "is_correct": false, "explanation": "近利 jìn lì 与 建立 jiàn lì 第一个音节韵母不同（in 与 an），意思是眼前的利益"}], "explanations": {"奖励": "奖励 jiǎng lì 与 建立 jiàn lì 第一个音节韵母不同（ang 与 an）且声调不同，意思是对好的表现给予鼓励或奖赏", "建立": "正确。建立 jiàn lì，意思是使机构、关系、制度等开始存在", "便利": "便利 biàn lì 与 建立 jiàn lì 第一个音节声母不同（b 与 j），意思是方便", "近利": "近利 jìn lì 与 建立 jiàn lì 第一个音节韵母不同（in 与 an），意思是眼前的利益"}, "sentence_index": null, "correct_answer": "建立"}, "level_3": {"options": [{"text": "拆除", "is_correct": false, "explanation": "搭配：「拆除」多用于建筑、设施，不与“自信”搭配"}, {"text": "建立", "is_correct": true, "explanation": "正确。建立自信指使自信开始存在，与“孩子要先”的语境相符"}, {"text": "喝", "is_correct": false, "explanation": "语义：「喝」的对象应是饮品，不能与“自信”搭配"}, {"text": "搬", "is_correct": false, "explanation": "语义：「搬」指移动具体的物体，不能用于“自信”"}], "explanations": {"拆除": "搭配：「拆除」多用于建筑、设施，不与“自信”搭配", "建立": "正确。建立自信指使自信开始存在，与“孩子要先”的语境相符", "喝": "语义：「喝」的对象应是饮品，不能与“自信”搭配", "搬": "语义：「搬」指移动具体的物体，不能用于“自信”"}, "sentence_index": 6, "correct_answer": "建立"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "院子里建立了一棵大树。", "explanation": "这里应该用〈种植〉。建立不用于栽种植物"}, {"text": "他很快建立好了冰箱。", "explanation": "这里应该用〈安装〉。建立指使机构、关系、制度开始存在，不用于装配电器，冰箱要说〈安装〉。"}, {"text": "这家工厂建立汽车。", "explanation": "这里应该用〈生产〉。建立指使机构等开始存在，产品的制造要说〈生产〉"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'dc0cc312-6c8a-4816-81d1-52075941a40b') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (22572, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "我们终于建立了起彼此的信任。", "corrected_sentence": "我们终于建立起了彼此的信任。", "error_description": "“建立了起”错误：趋向补语“起”应紧跟动词“建立”，“了”放在“起”之后，应为“建立起了彼此的信任”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'dc0cc312-6c8a-4816-81d1-52075941a40b') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (22572, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "两国曾经建立了过外交关系。", "corrected_sentence": "两国曾经建立过外交关系。", "error_description": "“了”与“过”不能同时用于同一动词，应只用经历体“过”，应为“建立过外交关系”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'dc0cc312-6c8a-4816-81d1-52075941a40b') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
