INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (22584, 1, 'prompt1_core', '{"pos": "名词", "semantic_class": "concrete", "definition": "机器。", "primary_collocate": null, "pronunciation": "jī xiè", "ipa": "tɕi˥ ɕjɛ˥˩", "syllable_count": 2, "sentences": [{"text": "这台机械已经用了二十年。", "target_word": "机械", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "工厂买了几台新机械。", "target_word": "机械", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "他每天都要检查这些机械。", "target_word": "机械", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "机械一旦坏了，整个车间都要停工。", "target_word": "机械", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "王师傅很会修理各种机械。", "target_word": "机械", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "修路需要很多大型机械。", "target_word": "机械", "complexity_tier": "T1", "sentence_source": "generated"}, {"text": "他把机械擦得干干净净。", "target_word": "机械", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这种机械用电，不用烧油。", "target_word": "机械", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "请不要碰这些机械，很危险。", "target_word": "机械", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "现代工厂里，机械代替了很多人工。", "target_word": "机械", "complexity_tier": "T2", "sentence_source": "generated"}], "morphological_forms": [{"form": "台", "label": "量词"}, {"form": "機械", "label": "繁体"}, {"form": "机械化", "label": "复合"}], "register": "中性", "sense_fingerprint": "机器，工厂和工地使用的设备", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '9524b76e-1a79-47e4-a085-bd4ad66e3a29') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (22584, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "机械", "is_correct": true, "explanation": "正确。“这台机械已经用了二十年”，机器可以被使用。"}, {"text": "节目", "is_correct": false, "explanation": "搭配：“用了二十年”不能用于“节目”，节目不能被“使用”。"}, {"text": "晚会", "is_correct": false, "explanation": "语义：晚会是活动，不能被使用二十年，句意不通。"}, {"text": "戏剧", "is_correct": false, "explanation": "搭配：“戏剧”不能与“用了”搭配，戏剧不是可以被使用的器具。"}], "explanations": {"机械": "正确。“这台机械已经用了二十年”，机器可以被使用。", "节目": "搭配：“用了二十年”不能用于“节目”，节目不能被“使用”。", "晚会": "语义：晚会是活动，不能被使用二十年，句意不通。", "戏剧": "搭配：“戏剧”不能与“用了”搭配，戏剧不是可以被使用的器具。"}, "sentence_index": 0, "correct_answer": "机械"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "工厂买了几只新机械。", "explanation": "量词错误：“机械”应用〈台〉计量，〈只〉多用于动物或成对物品中的一个。"}, {"text": "这个政府机械有很多工作人员。", "explanation": "〈机关〉指政府或团体的办事部门，“机械”是机器装置，这里应该用〈机关〉。"}, {"text": "他终于抓住了一个重要的机械。", "explanation": "〈机遇〉指有利的时机，“机械”是机器装置，这里应该用〈机遇〉。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'e4de3497-1c82-451f-b029-dd10cdee55f8') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (22584, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "机械", "is_correct": true, "explanation": "正确。“把机械擦得干干净净”，机器可以被擦拭。"}, {"text": "空气", "is_correct": false, "explanation": "搭配：“擦”不能用于“空气”，“把空气擦得干干净净”不是常用说法。"}, {"text": "时间", "is_correct": false, "explanation": "语义：时间不能被擦拭，句意不通。"}, {"text": "感情", "is_correct": false, "explanation": "语义：感情是抽象的，不能被擦拭，与“擦得干干净净”不符。"}], "explanations": {"机械": "正确。“把机械擦得干干净净”，机器可以被擦拭。", "空气": "搭配：“擦”不能用于“空气”，“把空气擦得干干净净”不是常用说法。", "时间": "语义：时间不能被擦拭，句意不通。", "感情": "语义：感情是抽象的，不能被擦拭，与“擦得干干净净”不符。"}, "sentence_index": 6, "correct_answer": "机械"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "工人们都在机械里吃午饭。", "explanation": "“机械”是器械，不能作为吃饭的场所，这里应该用〈车间〉。"}, {"text": "这个机械有三百名员工。", "explanation": "〈机构〉才指有员工的组织。“机械”是机器装置，没有员工，这里应该用〈机构〉。"}, {"text": "这是一次难得的机械。", "explanation": "〈机会〉与“机械”字形相近，这里是“难得的机会”，应该用〈机会〉。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'e4de3497-1c82-451f-b029-dd10cdee55f8') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (22584, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "这只机械需要定期加油。", "corrected_sentence": "这台机械需要定期加油。", "error_description": "量词错误：“机械”应用“台”计量，“只”多用于动物，应把“这只”改为“这台”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'e4de3497-1c82-451f-b029-dd10cdee55f8') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (22584, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "他每天都要擦这台机械们。", "corrected_sentence": "他每天都要擦这台机械。", "error_description": "词尾错误：“机械”指机器，是物件，不能加复数词尾“们”，应说“这台机械”，不说“这台机械们”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'e4de3497-1c82-451f-b029-dd10cdee55f8') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
