INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (22586, 1, 'prompt1_core', '{"pos": "动词", "semantic_class": "action", "definition": "把东西或人安排到某个地方去做事。", "primary_collocate": null, "pronunciation": "bù shǔ", "ipa": "pu˥˩ ʂu˨˩˦", "syllable_count": 2, "sentences": [{"text": "队长把队员部署到了山上。", "target_word": "部署", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "老板在店里部署了三个服务员。", "target_word": "部署", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "校长把每个班的学生部署到了操场。", "target_word": "部署", "complexity_tier": "T3", "furigana": "bù shǔ", "sentence_source": "generated"}, {"text": "我们先部署人手，再开始工作。", "target_word": "部署", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "经理把新来的人部署在门口。", "target_word": "部署", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "比赛前，教练部署好了每个球员的位置。", "target_word": "部署", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他们在河边部署了几个人看着水位。", "target_word": "部署", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "教练把队员部署到了北门。", "target_word": "部署", "complexity_tier": "T3", "furigana": "bù shǔ", "sentence_source": "generated"}, {"text": "公司把设备部署到各个办公室。", "target_word": "部署", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "活动开始前，主办方部署了十名工作人员。", "target_word": "部署", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "部署了", "label": "体标"}, {"form": "部署过", "label": "体标"}], "register": "书面", "sense_fingerprint": "把人或东西安排到某处去做事", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '18aff8d4-1977-42b5-860c-4182eae13c5e') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (22586, 1, 'prompt2_exercises_A', '{"level_1": {"options": [{"text": "部署", "is_correct": true, "explanation": "部署：把人力、设备安排到一定的岗位或地点。"}, {"text": "步数", "is_correct": false, "explanation": "shù（第四声）与 shǔ（第三声）声调不同，“步数”指走路的次数。"}, {"text": "不熟", "is_correct": false, "explanation": "shú（第二声）与 shǔ（第三声）声调不同，“不熟”指不熟悉。"}, {"text": "捕鼠", "is_correct": false, "explanation": "bǔ（第三声）与 bù（第四声）声调不同，“捕鼠”指捉老鼠。"}, {"text": "部数", "is_correct": false, "explanation": "shù（第四声）与 shǔ（第三声）声调不同，“部数”指印刷的份数。"}], "explanations": {"部署": "部署：把人力、设备安排到一定的岗位或地点。", "步数": "shù（第四声）与 shǔ（第三声）声调不同，“步数”指走路的次数。", "不熟": "shú（第二声）与 shǔ（第三声）声调不同，“不熟”指不熟悉。", "捕鼠": "bǔ（第三声）与 bù（第四声）声调不同，“捕鼠”指捉老鼠。", "部数": "shù（第四声）与 shǔ（第三声）声调不同，“部数”指印刷的份数。"}, "sentence_index": null, "correct_answer": "部署"}, "level_3": {"options": [{"text": "部署", "is_correct": true, "explanation": "部署：把队员安排到山上去做事，句意通顺。"}, {"text": "扔", "is_correct": false, "explanation": "语义：“扔”指抛掷，不表示有计划地安排人员。"}, {"text": "撞", "is_correct": false, "explanation": "语义：“撞”表示碰撞，与安排队员去做事无关。"}, {"text": "栽", "is_correct": false, "explanation": "搭配：“栽”的宾语多为树苗、花草，不能用于队员。"}], "explanations": {"部署": "部署：把队员安排到山上去做事，句意通顺。", "扔": "语义：“扔”指抛掷，不表示有计划地安排人员。", "撞": "语义：“撞”表示碰撞，与安排队员去做事无关。", "栽": "搭配：“栽”的宾语多为树苗、花草，不能用于队员。"}, "sentence_index": 0, "correct_answer": "部署"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "大学部署了三名新生。", "explanation": "这里应该用〈录取〉。录取指接收新生入学，部署用于安排人力、设备到岗位，不用于学生。"}, {"text": "公司部署了一次员工旅游。", "explanation": "这里应该用〈组织〉。组织用于策划活动，部署用于把人或设备安排到某个地方去做事。"}, {"text": "作家把这篇文章部署了三遍。", "explanation": "这里应该用〈修改〉。修改指改动文字内容，部署用于把人或东西安排到某个地方去做事，不用于文章。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '6cb03430-2c85-4101-a555-ba294ac0068a') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (22586, 1, 'prompt2_exercises_B', '{"level_1": {"options": [{"text": "部署", "is_correct": true, "explanation": "部署：把人或物安排到某个地方去做事。"}, {"text": "不输", "is_correct": false, "explanation": "shū（第一声）与 shǔ（第三声）声调不同，“不输”意思是不落后。"}, {"text": "不许", "is_correct": false, "explanation": "xǔ 与 shǔ 声母不同（x 与 sh），“不许”意思是不允许。"}, {"text": "副署", "is_correct": false, "explanation": "fù 与 bù 声母不同（f 与 b），“副署”指在文件上签字确认。"}, {"text": "部书", "is_correct": false, "explanation": "shū（第一声）与 shǔ（第三声）声调不同，“部书”指一部书。"}], "explanations": {"部署": "部署：把人或物安排到某个地方去做事。", "不输": "shū（第一声）与 shǔ（第三声）声调不同，“不输”意思是不落后。", "不许": "xǔ 与 shǔ 声母不同（x 与 sh），“不许”意思是不允许。", "副署": "fù 与 bù 声母不同（f 与 b），“副署”指在文件上签字确认。", "部书": "shū（第一声）与 shǔ（第三声）声调不同，“部书”指一部书。"}, "sentence_index": null, "correct_answer": "部署"}, "level_3": {"options": [{"text": "部署", "is_correct": true, "explanation": "部署：把几个人安排到河边看水位，句意通顺。"}, {"text": "拆", "is_correct": false, "explanation": "搭配：“拆”的对象多是建筑、器物，不能说拆人。"}, {"text": "卖", "is_correct": false, "explanation": "语义：“卖”表示买卖，与让人看水位无关。"}, {"text": "唱", "is_correct": false, "explanation": "语义：“唱”指歌唱，不能用来安排人员看水位。"}], "explanations": {"部署": "部署：把几个人安排到河边看水位，句意通顺。", "拆": "搭配：“拆”的对象多是建筑、器物，不能说拆人。", "卖": "语义：“卖”表示买卖，与让人看水位无关。", "唱": "语义：“唱”指歌唱，不能用来安排人员看水位。"}, "sentence_index": 6, "correct_answer": "部署"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "店主在橱窗里部署了一排花。", "explanation": "这里应该用〈摆放〉。摆放用于陈列物品，部署用于把人力、设备安排到岗位去做事。"}, {"text": "学校部署了一门新课程。", "explanation": "这里应该用〈设置〉。设置用于开设课程、设立机构，部署不用于课程。"}, {"text": "政府部署了一批灾民。", "explanation": "这里应该用〈安置〉。安置是给人安排住处和生活，部署用于安排人力、设备到岗位，不用于灾民。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '6cb03430-2c85-4101-a555-ba294ac0068a') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (22586, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "教练把新队员部署了到北区。", "corrected_sentence": "教练把新队员部署到了北区。", "error_description": "“了”应放在补语“到”之后。应说“部署到了北区”，不能说“部署了到北区”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '6cb03430-2c85-4101-a555-ba294ac0068a') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (22586, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "救援队把物资部署了灾区。", "corrected_sentence": "救援队把物资部署到了灾区。", "error_description": "“部署”后漏掉处所补语“到”。应说“部署到了灾区”，不能说“部署了灾区”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '6cb03430-2c85-4101-a555-ba294ac0068a') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
