INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (22588, 1, 'prompt1_core', '{"pos": "名词", "semantic_class": "concrete", "definition": "在好几个国家都开公司做事的大企业。", "primary_collocate": null, "pronunciation": "kuà guó qǐ yè", "ipa": "kʰua˥˩ kwo˧˥ tɕʰi˨˩˦ jɛ˥˩", "syllable_count": 4, "sentences": [{"text": "在好几个国家开分公司的大企业叫跨国企业。", "target_word": "跨国企业", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "我叔叔在一家跨国企业上班。", "target_word": "跨国企业", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这家跨国企业在中国和日本都有公司。", "target_word": "跨国企业", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "跨国企业的员工来自很多国家。", "target_word": "跨国企业", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "小王想去跨国企业工作，因为可以去国外。", "target_word": "跨国企业", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "有的跨国企业比一个小国家还有钱。", "target_word": "跨国企业", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这家跨国企业在三个国家招人。", "target_word": "跨国企业", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "跨国企业的产品世界各地都能买到。", "target_word": "跨国企业", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "那家跨国企业最近在印度开了新工厂。", "target_word": "跨国企业", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "跨国企业的会议常常用英语开。", "target_word": "跨国企业", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "家", "label": "量词"}, {"form": "跨國企業", "label": "繁体"}], "register": "中性", "sense_fingerprint": "在好几个国家开公司做事的大企业", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '18aff8d4-1977-42b5-860c-4182eae13c5e') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (22588, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "跨国企业", "is_correct": true, "explanation": "正确答案：在好几个国家开分公司的大企业就叫跨国企业。"}, {"text": "博物馆", "is_correct": false, "explanation": "语义：博物馆不是开分公司的企业，句意不通。"}, {"text": "小企业", "is_correct": false, "explanation": "语义：“小企业”与句中的“大企业”相矛盾，且不符合在多国开分公司的特征。"}, {"text": "大款", "is_correct": false, "explanation": "语域：“大款”是口语词，指有钱人，与本句的书面语体不合。"}], "explanations": {"跨国企业": "正确答案：在好几个国家开分公司的大企业就叫跨国企业。", "博物馆": "语义：博物馆不是开分公司的企业，句意不通。", "小企业": "语义：“小企业”与句中的“大企业”相矛盾，且不符合在多国开分公司的特征。", "大款": "语域：“大款”是口语词，指有钱人，与本句的书面语体不合。"}, "sentence_index": 0, "correct_answer": "跨国企业"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "他父亲在一头跨国企业当经理。", "explanation": "这里应该用〈家〉。“头”用于牲畜，企业应用量词“家”。"}, {"text": "我在一张跨国企业实习过。", "explanation": "这里应该用〈家〉。“张”用于纸张、桌子等，企业应用量词“家”。"}, {"text": "妈妈买了一把跨国企业。", "explanation": "这里应该用〈家〉。“把”用于有柄的物品，企业应用量词“家”。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '6cb03430-2c85-4101-a555-ba294ac0068a') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (22588, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "跨国企业", "is_correct": true, "explanation": "正确答案：这家企业在三个国家招人，主语应是企业。"}, {"text": "小孩", "is_correct": false, "explanation": "语义：小孩不能在三个国家招人，句意不通。"}, {"text": "老虎", "is_correct": false, "explanation": "语义：老虎不能在三个国家招人，句意不通。"}, {"text": "胖子", "is_correct": false, "explanation": "体貌：“胖子”描述人的体型，不能用来指企业，句意不通。"}], "explanations": {"跨国企业": "正确答案：这家企业在三个国家招人，主语应是企业。", "小孩": "语义：小孩不能在三个国家招人，句意不通。", "老虎": "语义：老虎不能在三个国家招人，句意不通。", "胖子": "体貌：“胖子”描述人的体型，不能用来指企业，句意不通。"}, "sentence_index": 6, "correct_answer": "跨国企业"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "这家跨国企业是一家医院。", "explanation": "语义矛盾：“这家跨国企业是一家医院”自相矛盾，跨国企业是经营性公司，不能是医院。"}, {"text": "这家跨国企业是一位律师。", "explanation": "语义矛盾：跨国企业是公司，不能等同于“一位律师”这类个人从业者。"}, {"text": "这家跨国企业是一首歌。", "explanation": "语义矛盾：跨国企业是公司，不能是“一首歌”这类作品。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '6cb03430-2c85-4101-a555-ba294ac0068a') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (22588, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "我妹妹去年进了一只跨国企业。", "corrected_sentence": "我妹妹去年进了一家跨国企业。", "error_description": "量词错误：“企业”应用量词“家”，“只”用于动物、成对器官等，不能用来计量企业。正确说法是“一家跨国企业”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '6cb03430-2c85-4101-a555-ba294ac0068a') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (22588, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "许多跨国企业们都在招聘懂外语的人。", "corrected_sentence": "许多跨国企业都在招聘懂外语的人。", "error_description": "词缀错误：“们”只能加在指人的名词后，“企业”不能加“们”。正确说法是“许多跨国企业”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '6cb03430-2c85-4101-a555-ba294ac0068a') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
