INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (22590, 1, 'prompt1_core', '{"pos": "动词", "semantic_class": "action", "definition": "用力撞上去，比如大浪撞到石头上。", "primary_collocate": null, "pronunciation": "chōng jī", "ipa": "tʂʰʊŋ˥ tɕi˥", "syllable_count": 2, "sentences": [{"text": "大浪冲击着岸边的石头。", "target_word": "冲击", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "海水不停地冲击岩石。", "target_word": "冲击", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "洪水冲击了河边的小桥。", "target_word": "冲击", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "风浪冲击过这座小岛很多次。", "target_word": "冲击", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "大雨后，河水冲击着桥墩。", "target_word": "冲击", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "海浪冲击船身，船摇得很厉害。", "target_word": "冲击", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "巨大的水流冲击着堤坝。", "target_word": "冲击", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "水流冲击了他的腿，他差点站不稳。", "target_word": "冲击", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "瀑布冲击着下面的水潭。", "target_word": "冲击", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "大浪一次次冲击海边的礁石。", "target_word": "冲击", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "冲击了", "label": "体标"}, {"form": "冲击着", "label": "体标"}, {"form": "冲击过", "label": "体标"}, {"form": "衝擊", "label": "繁体"}], "register": "中性", "sense_fingerprint": "水流、海浪等用力撞向某物", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '18aff8d4-1977-42b5-860c-4182eae13c5e') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (22590, 1, 'prompt2_exercises_A', '{"level_1": {"options": [{"text": "冲击", "is_correct": true, "explanation": "正确答案：冲击 chōng jī，指水流、海浪等用力撞向某物。"}, {"text": "重击", "is_correct": false, "explanation": "chóng（第二声）与 chōng（第一声）声调不同，意思是猛烈地打一下。"}, {"text": "冲剂", "is_correct": false, "explanation": "jì（第四声）与 jī（第一声）声调不同，意思是可以用水冲服的颗粒药剂。"}, {"text": "轰击", "is_correct": false, "explanation": "hōng（h）与 chōng（ch）声母不同，意思是用炮火猛烈攻击。"}], "explanations": {"冲击": "正确答案：冲击 chōng jī，指水流、海浪等用力撞向某物。", "重击": "chóng（第二声）与 chōng（第一声）声调不同，意思是猛烈地打一下。", "冲剂": "jì（第四声）与 jī（第一声）声调不同，意思是可以用水冲服的颗粒药剂。", "轰击": "hōng（h）与 chōng（ch）声母不同，意思是用炮火猛烈攻击。"}, "sentence_index": null, "correct_answer": "冲击"}, "level_3": {"options": [{"text": "冲击", "is_correct": true, "explanation": "正确答案：大浪用力撞向岸边的石头，符合句意。"}, {"text": "唱", "is_correct": false, "explanation": "配价：“唱”要求歌曲等作宾语，不能带“石头”作宾语。"}, {"text": "批评", "is_correct": false, "explanation": "语义：大浪不能批评石头，此处搭配不通，句意不通。"}, {"text": "赞美", "is_correct": false, "explanation": "语义：“赞美”针对人或作品，大浪不能赞美石头，句意不通。"}], "explanations": {"冲击": "正确答案：大浪用力撞向岸边的石头，符合句意。", "唱": "配价：“唱”要求歌曲等作宾语，不能带“石头”作宾语。", "批评": "语义：大浪不能批评石头，此处搭配不通，句意不通。", "赞美": "语义：“赞美”针对人或作品，大浪不能赞美石头，句意不通。"}, "sentence_index": 0, "correct_answer": "冲击"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "警察决心冲击网络诈骗行为。", "explanation": "这里应该用〈打击〉。冲击表示用力撞上去，严厉查处违法行为要说〈打击〉。"}, {"text": "大浪给礁石带来了一根冲击。", "explanation": "这里应该用〈次〉。“冲击”计量用“次”，“根”用于细长物体。"}, {"text": "他给我冲击了一杯牛奶。", "explanation": "这里应该用〈冲泡〉。“冲击”指猛烈撞击，不能用来调制饮品；冲牛奶要说〈冲泡〉。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '6cb03430-2c85-4101-a555-ba294ac0068a') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (22590, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "冲击", "is_correct": true, "explanation": "正确答案：巨大的水流用力撞向堤坝，符合句意。"}, {"text": "粉刷", "is_correct": false, "explanation": "语义：“粉刷”指涂抹墙面，水流不能粉刷堤坝，句意不通。"}, {"text": "拥有", "is_correct": false, "explanation": "配价：“拥有”要求带所有物作宾语，“水流拥有堤坝”不通。"}, {"text": "演讲", "is_correct": false, "explanation": "语义：水流不会演讲，此处搭配不通，句意不通。"}], "explanations": {"冲击": "正确答案：巨大的水流用力撞向堤坝，符合句意。", "粉刷": "语义：“粉刷”指涂抹墙面，水流不能粉刷堤坝，句意不通。", "拥有": "配价：“拥有”要求带所有物作宾语，“水流拥有堤坝”不通。", "演讲": "语义：水流不会演讲，此处搭配不通，句意不通。"}, "sentence_index": 6, "correct_answer": "冲击"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "大浪冲击着一盘棋。", "explanation": "这里应该用〈下〉。冲击的撞击义只能用于有形实物，下一盘棋要说〈下〉。"}, {"text": "大浪冲击着一首歌。", "explanation": "这里应该用〈唱〉。冲击的撞击义只能用于有形实物，歌曲要说〈唱〉。"}, {"text": "大浪冲击着一阵笑声。", "explanation": "这里应该用〈听见〉。冲击的撞击义只能用于有形实物，声音要说〈听见〉。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '6cb03430-2c85-4101-a555-ba294ac0068a') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (22590, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "台风过后，海浪猛烈地冲击了着礁石。", "corrected_sentence": "台风过后，海浪猛烈地冲击着礁石。", "error_description": "体标重复：“了”与“着”不能同时用在动词后，应只保留“着”，说“冲击着礁石”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '6cb03430-2c85-4101-a555-ba294ac0068a') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (22590, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "这块礁石从没被大浪冲击。", "corrected_sentence": "这块礁石从没被大浪冲击过。", "error_description": "体标缺失：“从没”表示有过的经历，句末须加“过”，应说“从没被大浪冲击过”，不能省略“过”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '6cb03430-2c85-4101-a555-ba294ac0068a') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
