INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (22606, 1, 'prompt1_core', '{"pos": "动词", "semantic_class": "action", "definition": "让一个事情动起来，比如让一个公司或一个商店工作。", "primary_collocate": null, "pronunciation": "yùn yíng", "ipa": "/yn˥˩ iŋ˧˥/", "syllable_count": 2, "sentences": [{"text": "他在网上运营一家小店。", "target_word": "运营", "complexity_tier": "T1", "sentence_source": "generated"}, {"text": "姐姐想运营一家自己的公司。", "target_word": "运营", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "她每天用手机运营这家咖啡店。", "target_word": "运营", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "我们一起运营这个学习网站。", "target_word": "运营", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "他已经运营这家店五年了。", "target_word": "运营", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "他把这家小店运营得很好。", "target_word": "运营", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "爸爸运营着一家面包店。", "target_word": "运营", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "她不会运营一家大公司。", "target_word": "运营", "complexity_tier": "T1", "sentence_source": "generated"}, {"text": "谁来运营这个新商店？", "target_word": "运营", "complexity_tier": "T1", "sentence_source": "generated"}, {"text": "我想学习怎么运营一家餐馆。", "target_word": "运营", "complexity_tier": "T2", "sentence_source": "generated"}], "morphological_forms": [{"form": "运营了", "label": "体标"}, {"form": "运营着", "label": "体标"}, {"form": "運營", "label": "繁体"}], "register": "中性", "sense_fingerprint": "运营：让公司或商店动起来、开始工作", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '18aff8d4-1977-42b5-860c-4182eae13c5e') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (22606, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "运营", "is_correct": true, "explanation": "运营：让网店动起来、开始工作，与“在网上”搭配，句意通顺。"}, {"text": "修理", "is_correct": false, "explanation": "搭配：“修理”针对器物，不能说修理“一家小店”。"}, {"text": "生产", "is_correct": false, "explanation": "语义：“生产”指制造产品，与在网上开店不符。"}, {"text": "翻译", "is_correct": false, "explanation": "配价：“翻译”需要文字作宾语，不能接“一家小店”。"}], "explanations": {"运营": "运营：让网店动起来、开始工作，与“在网上”搭配，句意通顺。", "修理": "搭配：“修理”针对器物，不能说修理“一家小店”。", "生产": "语义：“生产”指制造产品，与在网上开店不符。", "翻译": "配价：“翻译”需要文字作宾语，不能接“一家小店”。"}, "sentence_index": 0, "correct_answer": "运营"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "班主任运营全班学生。", "explanation": "这里应该用〈管理〉。运营用于店铺、公司、网站等项目，管理人和班级要用管理。"}, {"text": "服务员运营了客人。", "explanation": "这里应该用〈接待〉。接待是招待来客，运营用于让店铺、公司等动起来。"}, {"text": "工人运营了屋顶。", "explanation": "这里应该用〈修补〉。修补是修理损坏的部分，运营用于店铺、公司、网站等项目。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '6cb03430-2c85-4101-a555-ba294ac0068a') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (22606, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "运营", "is_correct": true, "explanation": "运营：让面包店持续经营，与“着”搭配，句意通顺。"}, {"text": "吃", "is_correct": false, "explanation": "语义：“吃”指进食，不能指经营店铺。"}, {"text": "洗", "is_correct": false, "explanation": "搭配：“洗”的宾语是衣物、器皿，不能说洗一家店铺。"}, {"text": "唱", "is_correct": false, "explanation": "语义：“唱”指歌唱，与经营店铺无关。"}], "explanations": {"运营": "运营：让面包店持续经营，与“着”搭配，句意通顺。", "吃": "语义：“吃”指进食，不能指经营店铺。", "洗": "搭配：“洗”的宾语是衣物、器皿，不能说洗一家店铺。", "唱": "语义：“唱”指歌唱，与经营店铺无关。"}, "sentence_index": 6, "correct_answer": "运营"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "妈妈运营了一盘菜。", "explanation": "这里应该用〈炒〉。炒指烹调菜肴，运营用于店铺、公司等项目。"}, {"text": "孩子们运营了作业。", "explanation": "这里应该用〈完成〉。运营用于店铺、公司、网站等项目，作业要说〈完成〉。"}, {"text": "教练运营了运动员。", "explanation": "这里应该用〈训练〉。训练是培养人的能力，运营不用于人员。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '6cb03430-2c85-4101-a555-ba294ac0068a') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (22606, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "她把这家网店运营很稳定。", "corrected_sentence": "她把这家网店运营得很稳定。", "error_description": "动词后的补语前漏掉“得”。应说“运营得很稳定”，不能说“运营很稳定”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '6cb03430-2c85-4101-a555-ba294ac0068a') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (22606, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "她运营过着这家小店。", "corrected_sentence": "她运营过这家小店。", "error_description": "“过”和“着”不能同时用在动词后。应去掉“着”，说“运营过这家小店”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '6cb03430-2c85-4101-a555-ba294ac0068a') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
