INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (22612, 1, 'llm_types_B', '{}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '05846cff-3c11-453f-ad46-1f4aba5d454b') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (22612, 1, 'prompt1_core', '{"pos": "形容词", "semantic_class": "property", "definition": "总是这样做，就像每天刷牙一样。", "primary_collocate": null, "pronunciation": "xí guàn xìng", "ipa": "ɕi³⁵ kuan⁵¹ ɕiŋ⁵¹", "syllable_count": 3, "sentences": [{"text": "每天早上喝水是我习惯性的动作。", "target_word": "习惯性", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他一进门就习惯性地换鞋。", "target_word": "习惯性", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "我习惯性地先刷牙，再洗脸。", "target_word": "习惯性", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "一上车，她就习惯性地系好安全带。", "target_word": "习惯性", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "奶奶习惯性地早起，六点就醒了。", "target_word": "习惯性", "complexity_tier": "T3", "furigana": "xí guàn xìng", "sentence_source": "generated"}, {"text": "我习惯性地检查门有没有锁好。", "target_word": "习惯性", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他习惯性地点头，其实没有听懂。", "target_word": "习惯性", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "走进教室，学生习惯性地找自己的座位。", "target_word": "习惯性", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "睡觉前，她习惯性地看一会儿书。", "target_word": "习惯性", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他习惯性地说“谢谢”，对谁都很有礼貌。", "target_word": "习惯性", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "習慣性", "label": "繁体"}], "register": "中性", "sense_fingerprint": "习惯性：不用想、总是那样做的日常动作", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '1855a062-bf45-40b1-b6fc-d75bbeb6ed1d') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (22612, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "习惯性", "is_correct": true, "explanation": "正确。“每天早上喝水是我习惯性的动作”指不用想、每天如此的日常动作。"}, {"text": "偶然", "is_correct": false, "explanation": "语义：“偶然”指偶尔发生，与“每天早上”的日常重复矛盾。"}, {"text": "特殊", "is_correct": false, "explanation": "语义：“特殊”指与众不同，不能说每天早上喝水是特殊的动作。"}, {"text": "高大", "is_correct": false, "explanation": "搭配：“高大”形容身材或体型，不能修饰“动作”。"}], "explanations": {"习惯性": "正确。“每天早上喝水是我习惯性的动作”指不用想、每天如此的日常动作。", "偶然": "语义：“偶然”指偶尔发生，与“每天早上”的日常重复矛盾。", "特殊": "语义：“特殊”指与众不同，不能说每天早上喝水是特殊的动作。", "高大": "搭配：“高大”形容身材或体型，不能修饰“动作”。"}, "sentence_index": 0, "correct_answer": "习惯性"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "他习惯性地在火车站偶遇了多年未见的老同学。", "explanation": "这里应该用〈偶然〉。习惯性指长期重复形成的行为，不能描述一次巧遇。"}, {"text": "这是习惯性的筷子。", "explanation": "这里应该用〈一次性〉。习惯性形容行为或倾向，不修饰筷子这类物品。"}, {"text": "我习惯性地第一次来到这里，对一切都很陌生。", "explanation": "这里应该用〈初次〉。习惯性指长期重复形成的行为，不能描述第一次到某地的经历。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '05846cff-3c11-453f-ad46-1f4aba5d454b') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (22612, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "习惯性", "is_correct": true, "explanation": "正确。“他习惯性地点头”指无意识的日常反应，与“其实没有听懂”相符。"}, {"text": "漆黑", "is_correct": false, "explanation": "搭配：“漆黑”形容颜色或光线昏暗，不能修饰点头的方式。"}, {"text": "矮小", "is_correct": false, "explanation": "体貌：“矮小”形容身材，不能修饰点头的方式。"}, {"text": "漂亮", "is_correct": false, "explanation": "搭配：“漂亮”多形容外貌或做事出色，不说“漂亮地点头”。"}], "explanations": {"习惯性": "正确。“他习惯性地点头”指无意识的日常反应，与“其实没有听懂”相符。", "漆黑": "搭配：“漆黑”形容颜色或光线昏暗，不能修饰点头的方式。", "矮小": "体貌：“矮小”形容身材，不能修饰点头的方式。", "漂亮": "搭配：“漂亮”多形容外貌或做事出色，不说“漂亮地点头”。"}, "sentence_index": 6, "correct_answer": "习惯性"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "她习惯性戒掉烟瘾。", "explanation": "这里应该用〈决心〉。习惯性指不用想、重复形成的行为，不能表示有意的决心。"}, {"text": "他习惯性地在十年前登上了月球。", "explanation": "这里应该用〈历史性〉。习惯性指长期重复的行为，不能描述只发生一次的历史事件。"}, {"text": "他习惯性地在去年获得了诺贝尔奖。", "explanation": "这里应该用〈首次获奖〉。习惯性指经常重复形成的行为，不能描述只发生一次的荣誉。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '05846cff-3c11-453f-ad46-1f4aba5d454b') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (22612, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "我习惯性的关掉电脑。", "corrected_sentence": "我习惯性地关掉电脑。", "error_description": "错误：“习惯性”修饰动词“关”，作状语时应用“地”，不能用“的”。正确说法：“我习惯性地关掉电脑。”", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '05846cff-3c11-453f-ad46-1f4aba5d454b') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (22612, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "她习惯性的揉揉眼睛，像是没睡好。", "corrected_sentence": "她习惯性地揉揉眼睛，像是没睡好。", "error_description": "错误：“习惯性”作状语修饰动词“揉”，应用“地”，不能用“的”。正确说法：“她习惯性地揉揉眼睛，像是没睡好。”", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '05846cff-3c11-453f-ad46-1f4aba5d454b') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
