INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (22634, 1, 'prompt1_core', '{"pos": "名词", "semantic_class": "abstract", "definition": "最重要的部分。", "primary_collocate": null, "pronunciation": "hé xīn", "ipa": "xɤ˧˥ ɕin˥", "syllable_count": 2, "sentences": [{"text": "这个问题的核心是钱。", "target_word": "核心", "complexity_tier": "T1", "sentence_source": "generated"}, {"text": "他是我们队的核心。", "target_word": "核心", "complexity_tier": "T1", "sentence_source": "generated"}, {"text": "学习的核心是多练习。", "target_word": "核心", "complexity_tier": "T1", "sentence_source": "generated"}, {"text": "这本书的核心是爱，不是钱。", "target_word": "核心", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "请说一下你们计划的核心。", "target_word": "核心", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "老师让我们找出这段话的核心。", "target_word": "核心", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "公司的核心是好产品。", "target_word": "核心", "complexity_tier": "T1", "sentence_source": "generated"}, {"text": "爷爷是我们这个家的核心。", "target_word": "核心", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "核心问题解决了，别的都好办。", "target_word": "核心", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "做这件事的核心是不要放弃。", "target_word": "核心", "complexity_tier": "T2", "sentence_source": "generated"}], "morphological_forms": [{"form": "核心问题", "label": "复合"}, {"form": "核心力量", "label": "复合"}], "register": "中性", "sense_fingerprint": "核心|abstract|最重要的部分", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'c39c2f0b-1c7d-4288-9529-c42fc1d1b19a') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (22634, 1, 'prompt2_exercises_A', '{"level_1": {"options": [{"text": "核心", "is_correct": true, "explanation": "核心（hé xīn）指最重要的部分，是正确答案。"}, {"text": "贺信", "is_correct": false, "explanation": "hè xìn（第四声、第四声）与 hé xīn 声调全部不同，意思是贺信。"}, {"text": "合金", "is_correct": false, "explanation": "jīn（第一声）与 xīn（第一声）声母不同（j 与 x），意思是合金。"}, {"text": "寒心", "is_correct": false, "explanation": "hán（第二声）与 hé（第二声）韵母不同（an 与 e），意思是令人寒心。"}], "explanations": {"核心": "核心（hé xīn）指最重要的部分，是正确答案。", "贺信": "hè xìn（第四声、第四声）与 hé xīn 声调全部不同，意思是贺信。", "合金": "jīn（第一声）与 xīn（第一声）声母不同（j 与 x），意思是合金。", "寒心": "hán（第二声）与 hé（第二声）韵母不同（an 与 e），意思是令人寒心。"}, "sentence_index": null, "correct_answer": "核心"}, "level_3": {"options": [{"text": "核心", "is_correct": true, "explanation": "正确：“核心”指最重要的部分，与“这个问题的……是钱”搭配通顺。"}, {"text": "颜色", "is_correct": false, "explanation": "语义：“颜色”不指问题中最重要的部分，“这个问题的颜色是钱”说不通。"}, {"text": "外套", "is_correct": false, "explanation": "语义：“外套”是衣物，不能作为“这个问题”的组成部分。"}, {"text": "旋律", "is_correct": false, "explanation": "搭配：“旋律”一般只说音乐，不说“问题的旋律”。"}], "explanations": {"核心": "正确：“核心”指最重要的部分，与“这个问题的……是钱”搭配通顺。", "颜色": "语义：“颜色”不指问题中最重要的部分，“这个问题的颜色是钱”说不通。", "外套": "语义：“外套”是衣物，不能作为“这个问题”的组成部分。", "旋律": "搭配：“旋律”一般只说音乐，不说“问题的旋律”。"}, "sentence_index": 0, "correct_answer": "核心"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "这台电脑的处理器是四核心的。", "explanation": "这里的“核心”指处理器中的运算单元，是另一个义项，与“最重要的部分”不同。"}, {"text": "这个苹果的核心很酸。", "explanation": "这里的“核心”指果实中间包裹种子的部分，是另一个义项，与“最重要的部分”不同。"}, {"text": "教室的核心挂着一面国旗。", "explanation": "这里应该用〈中央〉。“核心”不指空间中间位置，说房间中央要用“中央”。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '691f3f1c-d45d-444e-963e-277b3753efa6') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (22634, 1, 'prompt2_exercises_B', '{"level_1": {"options": [{"text": "核心", "is_correct": true, "explanation": "核心（hé xīn）指最重要的部分，是正确答案。"}, {"text": "恒心", "is_correct": false, "explanation": "héng（第二声）与 hé（第二声）韵母不同（eng 与 e），意思是坚持不懈的意志。"}, {"text": "红心", "is_correct": false, "explanation": "hóng（第二声）与 hé（第二声）韵母不同（ong 与 e），意思是红色的中心或忠心。"}, {"text": "湖心", "is_correct": false, "explanation": "hú（第二声）与 hé（第二声）韵母不同（u 与 e），意思是湖的中央部分。"}], "explanations": {"核心": "核心（hé xīn）指最重要的部分，是正确答案。", "恒心": "héng（第二声）与 hé（第二声）韵母不同（eng 与 e），意思是坚持不懈的意志。", "红心": "hóng（第二声）与 hé（第二声）韵母不同（ong 与 e），意思是红色的中心或忠心。", "湖心": "hú（第二声）与 hé（第二声）韵母不同（u 与 e），意思是湖的中央部分。"}, "sentence_index": null, "correct_answer": "核心"}, "level_3": {"options": [{"text": "核心", "is_correct": true, "explanation": "正确：“核心”指最重要的部分，与“公司的……是好产品”搭配通顺。"}, {"text": "天气", "is_correct": false, "explanation": "语义：“天气”不能指公司最重要的部分，“公司的天气是好产品”说不通。"}, {"text": "体温", "is_correct": false, "explanation": "搭配：“体温”只用于人或动物，不说“公司的体温”。"}, {"text": "心跳", "is_correct": false, "explanation": "语义：“心跳”指心脏的搏动，不能指公司的组成部分，“公司的心跳是好产品”说不通。"}], "explanations": {"核心": "正确：“核心”指最重要的部分，与“公司的……是好产品”搭配通顺。", "天气": "语义：“天气”不能指公司最重要的部分，“公司的天气是好产品”说不通。", "体温": "搭配：“体温”只用于人或动物，不说“公司的体温”。", "心跳": "语义：“心跳”指心脏的搏动，不能指公司的组成部分，“公司的心跳是好产品”说不通。"}, "sentence_index": 6, "correct_answer": "核心"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "那个团队有一只核心。", "explanation": "这里应该用〈个〉。“核心”的量词是“个”，用“只”不对。"}, {"text": "这篇文章有一条核心。", "explanation": "这里应该用〈个〉。“核心”的量词是“个”，用“条”不对。"}, {"text": "这家公司有一张核心。", "explanation": "这里应该用〈个〉。“核心”的量词是“个”，用“张”不对。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '691f3f1c-d45d-444e-963e-277b3753efa6') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (22634, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "她是这个班的一只核心。", "corrected_sentence": "她是这个班的核心。", "error_description": "错误：“核心”前加了量词“只”。“只”不用于“核心”，且这里不需要数量词，应说“她是这个班的核心”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '691f3f1c-d45d-444e-963e-277b3753efa6') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (22634, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "这次比赛的核心了是速度。", "corrected_sentence": "这次比赛的核心是速度。", "error_description": "错误：“了”附在名词“核心”后。“了”是动态助词，不能用在名词后，应说“这次比赛的核心是速度”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '691f3f1c-d45d-444e-963e-277b3753efa6') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
