INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (22642, 1, 'prompt1_core', '{"pos": "名词", "semantic_class": "abstract", "definition": "策略就是你想好怎么做一件事的办法。", "primary_collocate": null, "pronunciation": "cè lüè", "ipa": "tsʰɤ˥˩ lɥœ˥˩", "syllable_count": 2, "sentences": [{"text": "公司换了新的销售策略。", "target_word": "策略", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "好的学习策略能节省时间。", "target_word": "策略", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "比赛前，教练和队员讨论了策略。", "target_word": "策略", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "这个策略很简单，但是很有用。", "target_word": "策略", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "他改变策略，先从容易的题开始。", "target_word": "策略", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "我们需要一个长期的发展策略。", "target_word": "策略", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "对手的策略让我们很意外。", "target_word": "策略", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "她用了一种聪明的策略说服老板。", "target_word": "策略", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "策略不对，再努力也没有用。", "target_word": "策略", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "这家店的价格策略吸引了很多客人。", "target_word": "策略", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "种", "label": "量词"}, {"form": "个", "label": "量词"}], "register": "中性", "sense_fingerprint": "名词：为做成一件事事先想好的办法、方案", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'ca85f957-df35-4d8f-af57-1db695739dd7') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (22642, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "颜色", "is_correct": false, "explanation": "语义：“销售颜色”不构成经营概念，颜色不是可以换的经营办法。"}, {"text": "手势", "is_correct": false, "explanation": "搭配：“销售手势”不成立，“手势”与“销售”这类经营活动搭配不上。"}, {"text": "策略", "is_correct": true, "explanation": "正确：“策略”指为做成事情事先想好的办法，与“新的销售”相合。"}, {"text": "厨房", "is_correct": false, "explanation": "语义：“厨房”是场所，不能修饰“销售”这种经营活动。"}], "explanations": {"颜色": "语义：“销售颜色”不构成经营概念，颜色不是可以换的经营办法。", "手势": "搭配：“销售手势”不成立，“手势”与“销售”这类经营活动搭配不上。", "策略": "正确：“策略”指为做成事情事先想好的办法，与“新的销售”相合。", "厨房": "语义：“厨房”是场所，不能修饰“销售”这种经营活动。"}, "sentence_index": 0, "correct_answer": "策略"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "他把这个策略装进了书包。", "explanation": "这里“策略”是抽象的办法，不是能被装进书包的具体物品，“装进书包”的对象应是具体的东西。"}, {"text": "这台策略很好。", "explanation": "这里应该用〈个〉或〈种〉作量词。〈台〉用于机器、设备等具体物件，“策略”是抽象的办法，不能用“台”计量。"}, {"text": "策略一起床就吃早饭了。", "explanation": "这里“策略”是抽象的办法，不能主动做“吃早饭”这样的动作。应换成一个能吃早饭的人。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'c290b81d-0dcb-45a5-b379-91fe24a99a2f') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (22642, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "味道", "is_correct": false, "explanation": "语义：“味道”指气味或滋味，与“对手的……让我们很意外”的语境不合。"}, {"text": "钥匙", "is_correct": false, "explanation": "语义：“钥匙”是具体物品，“对手的钥匙让我们很意外”没有道理，与“策略”的语境不合。"}, {"text": "策略", "is_correct": true, "explanation": "正确：“策略”指对手做事的办法，“对手的策略让我们很意外”语义通顺。"}, {"text": "手套", "is_correct": false, "explanation": "语义：“手套”是具体的物品，不能让人意外地影响比赛的走势。"}], "explanations": {"味道": "语义：“味道”指气味或滋味，与“对手的……让我们很意外”的语境不合。", "钥匙": "语义：“钥匙”是具体物品，“对手的钥匙让我们很意外”没有道理，与“策略”的语境不合。", "策略": "正确：“策略”指对手做事的办法，“对手的策略让我们很意外”语义通顺。", "手套": "语义：“手套”是具体的物品，不能让人意外地影响比赛的走势。"}, "sentence_index": 6, "correct_answer": "策略"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "这家店的价格策略很开心。", "explanation": "这里“策略”是抽象的办法，“开心”描述人的心情，不能用来形容办法。应换成形容办法的词，如“好”。"}, {"text": "这家店的价格策略被踢了一脚。", "explanation": "这里“策略”是抽象的办法，不是能被踢的具体物品，把它当作〈实物〉来用是错误的。"}, {"text": "这家店的价格策略很好吃。", "explanation": "这里“策略”是抽象的办法，把它看成〈食物〉来形容不对，“好吃”只能用于食物。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'c290b81d-0dcb-45a5-b379-91fe24a99a2f') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (22642, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "他制定了一把学习策略。", "corrected_sentence": "他制定了一个学习策略。", "error_description": "错误：“策略”的量词应是“个”或“种”，不能用“把”。应说“他制定了一个学习策略。”", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'c290b81d-0dcb-45a5-b379-91fe24a99a2f') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (22642, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "教练改变了比赛的策略们。", "corrected_sentence": "教练改变了比赛的策略。", "error_description": "错误：“策略”是抽象名词，后面不能加“们”表示复数。应说“教练改变了比赛的策略。”", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'c290b81d-0dcb-45a5-b379-91fe24a99a2f') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
