INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (22644, 1, 'prompt1_core', '{"pos": "动词", "semantic_class": "action", "definition": "两个东西碰到一起。", "primary_collocate": null, "pronunciation": "pèng zhuàng", "ipa": "/pʰɤŋ˥˩ ʈʂwaŋ˥˩/", "syllable_count": 2, "sentences": [{"text": "两个杯子碰撞，发出声音。", "target_word": "碰撞", "complexity_tier": "T1", "sentence_source": "generated"}, {"text": "小球和小球碰撞了一下。", "target_word": "碰撞", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "两辆车在路上碰撞了。", "target_word": "碰撞", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "孩子们玩的玩具车互相碰撞。", "target_word": "碰撞", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "他的手机和钥匙碰撞，响了一声。", "target_word": "碰撞", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "两只船在河上轻轻碰撞着。", "target_word": "碰撞", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "请小心，别让瓶子互相碰撞。", "target_word": "碰撞", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "风一吹，树枝就互相碰撞。", "target_word": "碰撞", "complexity_tier": "T3", "furigana": "fēng yī chuī, shùzhī jiù hùxiāng pèngzhuàng.", "sentence_source": "generated"}, {"text": "两块石头碰撞，火花一下就出来了。", "target_word": "碰撞", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "她把两个小球放在一起，让它们碰撞。", "target_word": "碰撞", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "碰撞了", "label": "体标"}, {"form": "碰撞着", "label": "体标"}], "register": "中性", "sense_fingerprint": "碰撞：两个东西碰到一起", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '18aff8d4-1977-42b5-860c-4182eae13c5e') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (22644, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "碰撞", "is_correct": true, "explanation": "正确：“碰撞”指两个杯子相互接触，与“发出声音”的句意相合。"}, {"text": "思考", "is_correct": false, "explanation": "语义：“思考”是人的脑力活动，杯子不能思考，句意不通。"}, {"text": "驾驶", "is_correct": false, "explanation": "配价：“驾驶”是及物动词，须带交通工具作宾语，“两个杯子驾驶”不成立。"}, {"text": "睡觉", "is_correct": false, "explanation": "语义：“睡觉”是人或动物的休息行为，杯子不会睡觉。"}], "explanations": {"碰撞": "正确：“碰撞”指两个杯子相互接触，与“发出声音”的句意相合。", "思考": "语义：“思考”是人的脑力活动，杯子不能思考，句意不通。", "驾驶": "配价：“驾驶”是及物动词，须带交通工具作宾语，“两个杯子驾驶”不成立。", "睡觉": "语义：“睡觉”是人或动物的休息行为，杯子不会睡觉。"}, "sentence_index": 0, "correct_answer": "碰撞"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "我们在工作中碰撞了很多困难。", "explanation": "这里应该用〈遇到〉。碰撞指物体相互冲击，不能用来表示遭遇困难。"}, {"text": "我们俩碰撞完成了作业。", "explanation": "这里应该用〈合作〉。碰撞是物体的冲击，不能用来指人之间共同做事。"}, {"text": "他碰撞我们去他家做客。", "explanation": "这里应该用〈邀请〉。碰撞不能表示发出邀约，这句的意思完全不通。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '6cb03430-2c85-4101-a555-ba294ac0068a') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (22644, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "碰撞", "is_correct": true, "explanation": "正确：“碰撞”指物体互相接触，与“请小心”提醒防止磕碰的语境相合。"}, {"text": "结交", "is_correct": false, "explanation": "语义：“结交”是人与人之间的交往，瓶子不能结交。"}, {"text": "原谅", "is_correct": false, "explanation": "配价：“原谅”要求受事是人或行为，“瓶子”不能作“原谅”的对象。"}, {"text": "倾诉", "is_correct": false, "explanation": "语义：“倾诉”是人表达内心感情，瓶子不能倾诉。"}], "explanations": {"碰撞": "正确：“碰撞”指物体互相接触，与“请小心”提醒防止磕碰的语境相合。", "结交": "语义：“结交”是人与人之间的交往，瓶子不能结交。", "原谅": "配价：“原谅”要求受事是人或行为，“瓶子”不能作“原谅”的对象。", "倾诉": "语义：“倾诉”是人表达内心感情，瓶子不能倾诉。"}, "sentence_index": 6, "correct_answer": "碰撞"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "他用手机碰撞了一张照片。", "explanation": "这里应该用〈拍〉。碰撞指物体相互冲击，不能用来表示拍照。"}, {"text": "我们要碰撞花草树木。", "explanation": "这里应该用〈爱护〉。碰撞指力量较大的相互冲击，不能表示珍惜保护花草。"}, {"text": "我们应该碰撞老师。", "explanation": "这里应该用〈尊重〉。碰撞是物体相互冲击，不能用来表示对老师的尊重。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '6cb03430-2c85-4101-a555-ba294ac0068a') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (22644, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "两个杯子碰撞很响。", "corrected_sentence": "两个杯子碰撞得很响。", "error_description": "错误形式：“碰撞很响”；正确形式：“碰撞得很响”。描述程度的补语前须加结构助词“得”，“很响”不能直接跟在动词后。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '6cb03430-2c85-4101-a555-ba294ac0068a') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (22644, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "两个小球正碰撞了，发出脆响。", "corrected_sentence": "两个小球正碰撞着，发出脆响。", "error_description": "错误形式：“正碰撞了”；正确形式：“正碰撞着”。“正”表示动作正在进行，应与“着”搭配，“了”表示完成，二者不能同用。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '6cb03430-2c85-4101-a555-ba294ac0068a') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
