INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (22646, 1, 'prompt1_core', '{"pos": "名词", "semantic_class": "concrete", "definition": "指很远的地方。", "primary_collocate": null, "pronunciation": "yuǎn chéng", "ipa": "ɥɛn˨˩˦ ʈʂʰɤŋ˧˥", "syllable_count": 2, "sentences": [{"text": "这架飞机适合远程飞行。", "target_word": "远程", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这辆卡车专门跑远程运输。", "target_word": "远程", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他是跑远程的司机。", "target_word": "远程", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "我不喜欢开车跑远程。", "target_word": "远程", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "远程旅行前，要先检查汽车。", "target_word": "远程", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这种导弹可以打到远程目标。", "target_word": "远程", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他从小就梦想去远程探险。", "target_word": "远程", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这辆车只适合跑近程，不适合跑远程。", "target_word": "远程", "complexity_tier": "T3", "furigana": "zhè liàng chē zhǐ shì hé pǎo jìn chéng, bù shì hé pǎo yuǎn chéng。", "sentence_source": "generated"}, {"text": "货车司机常常要跑远程，很少回家。", "target_word": "远程", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这是一条远程航线，要飞十个小时。", "target_word": "远程", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "远程教育", "label": "复合"}, {"form": "遠程", "label": "繁体"}], "register": "中性", "sense_fingerprint": "路途遥远的地方或距离", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '5a7d32c5-7ea6-49ff-a5b8-7910f90aa5ec') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (22646, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "远程", "is_correct": true, "explanation": "远程：指很远的路途，此处修饰“飞行”，指长距离的飞行。"}, {"text": "水下", "is_correct": false, "explanation": "语义：水下指水面以下，与飞机在空中的飞行相矛盾。"}, {"text": "地底", "is_correct": false, "explanation": "语义：地底指地面以下，与飞机飞行的意思相悖。"}, {"text": "赛车", "is_correct": false, "explanation": "搭配：“赛车”指车辆比赛，不能与“飞行”搭配。"}], "explanations": {"远程": "远程：指很远的路途，此处修饰“飞行”，指长距离的飞行。", "水下": "语义：水下指水面以下，与飞机在空中的飞行相矛盾。", "地底": "语义：地底指地面以下，与飞机飞行的意思相悖。", "赛车": "搭配：“赛车”指车辆比赛，不能与“飞行”搭配。"}, "sentence_index": 0, "correct_answer": "远程"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "这里保存着远程的文明遗迹。", "explanation": "这里应该用〈远古〉。远程指空间距离很远，不能用来形容时间久远。"}, {"text": "这项决定对社会有远程的影响。", "explanation": "这里应该用〈深远〉。远程只说距离遥远，不能用来形容影响的深远。"}, {"text": "我们的友谊远程而深厚。", "explanation": "这里应该用〈长久〉。远程指空间距离，不能用来形容友谊存在的时间长久。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '28eee4b8-5aea-4484-a73e-9196fa0b69e1') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (22646, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "远程", "is_correct": true, "explanation": "远程：指很远的地方或路途，此处修饰“探险”，指遥远之处的探险。"}, {"text": "体育", "is_correct": false, "explanation": "搭配：“探险”的对象是陌生或遥远的地域，不能说“去体育探险”。"}, {"text": "纸张", "is_correct": false, "explanation": "语义：纸张是物品，不是可以前往探索的地方，与“梦想去……探险”不相合。"}, {"text": "电话", "is_correct": false, "explanation": "语义：电话是通讯工具，不是可以前往探险的地方，与句意不符。"}], "explanations": {"远程": "远程：指很远的地方或路途，此处修饰“探险”，指遥远之处的探险。", "体育": "搭配：“探险”的对象是陌生或遥远的地域，不能说“去体育探险”。", "纸张": "语义：纸张是物品，不是可以前往探索的地方，与“梦想去……探险”不相合。", "电话": "语义：电话是通讯工具，不是可以前往探险的地方，与句意不符。"}, "sentence_index": 6, "correct_answer": "远程"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "他远程赶来参加婚礼。", "explanation": "这里应该用〈远道〉。远程形容的是很远的地方，不能用来描述人从远方赶来，应说远道赶来。"}, {"text": "这件事的远程后果十分严重。", "explanation": "这里应该用〈深远〉。远程只说距离很远，不能用来形容后果影响的深远。"}, {"text": "这座古城的远程历史已经有两千年了。", "explanation": "这里应该用〈悠久〉。远程指空间距离很远，不能用来形容历史存续的时间长。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '28eee4b8-5aea-4484-a73e-9196fa0b69e1') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (22646, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "这次任务要去一片很远程海域。", "corrected_sentence": "这次任务要去一片远程海域。", "error_description": "“远程”作定语修饰“海域”时，前面不能加“很”。应说“一片远程海域”；“很”只能修饰形容词或“很远的”这类带“的”的结构，不能直接修饰定语。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '28eee4b8-5aea-4484-a73e-9196fa0b69e1') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (22646, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "这支科考队要去很远程的雪山探险。", "corrected_sentence": "这支科考队要去远程的雪山探险。", "error_description": "“远程”作定语修饰“雪山”，前面不能加“很”。应说“远程的雪山”，“很”不能直接修饰这个定语。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '28eee4b8-5aea-4484-a73e-9196fa0b69e1') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
