INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (22656, 1, 'prompt1_core', '{"pos": "动词", "semantic_class": "action", "definition": "让某物安全，不让人破坏它。", "primary_collocate": null, "pronunciation": "bǎo zhàng", "ipa": "pɑʊ˨˩ tʂɑŋ˥˩", "syllable_count": 2, "sentences": [{"text": "保安日夜巡逻，保障小区的安全。", "target_word": "保障", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "我们要保障河水不受污染。", "target_word": "保障", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这把锁能保障家里的财物安全。", "target_word": "保障", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "学校请了保安，保障学生的安全。", "target_word": "保障", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "工人检查了桥，保障过往车辆安全。", "target_word": "保障", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "博物馆装了摄像头，保障文物安全。", "target_word": "保障", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他在仓库周围加装了铁栅栏，保障货物安全。", "target_word": "保障", "complexity_tier": "T3", "furigana": "tā zài cāng kù zhōu wéi jiā zhuāng le tiě zhà lan, bǎo zhàng huò wù ān quán.", "sentence_source": "generated"}, {"text": "银行用密码保障客户的存款安全。", "target_word": "保障", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "军人守着边境，保障国家的安全。", "target_word": "保障", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "好的设置能保障个人信息的安全。", "target_word": "保障", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "保障了", "label": "体标"}, {"form": "保障着", "label": "体标"}, {"form": "保障过", "label": "体标"}], "register": "书面语", "sense_fingerprint": "采取办法让人或物保持安全，不遭破坏", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '25ed9bc7-01da-4ef0-9d7d-214cdf98c5c9') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (22656, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "保障", "is_correct": true, "explanation": "“保障小区的安全”指采取措施使小区保持安全，与“保安日夜巡逻”相呼应。"}, {"text": "打扰", "is_correct": false, "explanation": "语义：“打扰”指妨碍别人，与保安守护小区的作用相反，句意矛盾。"}, {"text": "修建", "is_correct": false, "explanation": "搭配：“修建”的对象是房屋、道路等建筑，不能说修建安全。"}, {"text": "购买", "is_correct": false, "explanation": "配价：“购买”的宾语须是可买的物品或服务，安全不能被购买。"}], "explanations": {"保障": "“保障小区的安全”指采取措施使小区保持安全，与“保安日夜巡逻”相呼应。", "打扰": "语义：“打扰”指妨碍别人，与保安守护小区的作用相反，句意矛盾。", "修建": "搭配：“修建”的对象是房屋、道路等建筑，不能说修建安全。", "购买": "配价：“购买”的宾语须是可买的物品或服务，安全不能被购买。"}, "sentence_index": 0, "correct_answer": "保障"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "他保障不会迟到。", "explanation": "这里应该用〈保证〉。保障指让人或物保持安全、不受破坏，承诺某事才用保证。"}, {"text": "他把坏了的电脑保障了一下。", "explanation": "这里应该用〈修理〉。保障指使人或物保持安全，不指修理具体的物件。"}, {"text": "他很在意，总想保障自己的心情。", "explanation": "这里应该用〈调节〉。保障多用于安全、财产和利益，心情要说调节。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '30f22364-fbff-41e5-b603-90028fed7570') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (22656, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "保障", "is_correct": true, "explanation": "“保障货物安全”指使货物不受损坏，与“加装铁栅栏”的防护目的相呼应。"}, {"text": "清点", "is_correct": false, "explanation": "语义：“清点”指查数，与铁栅栏的防护作用无关，不能使货物安全。"}, {"text": "装饰", "is_correct": false, "explanation": "搭配：“装饰”的对象是外观或物件，不能说装饰货物安全。"}, {"text": "登记", "is_correct": false, "explanation": "配价：“登记”的宾语是名册或信息，不能接“安全”作宾语。"}], "explanations": {"保障": "“保障货物安全”指使货物不受损坏，与“加装铁栅栏”的防护目的相呼应。", "清点": "语义：“清点”指查数，与铁栅栏的防护作用无关，不能使货物安全。", "装饰": "搭配：“装饰”的对象是外观或物件，不能说装饰货物安全。", "登记": "配价：“登记”的宾语是名册或信息，不能接“安全”作宾语。"}, "sentence_index": 6, "correct_answer": "保障"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "这位老师保障学生的口音。", "explanation": "这里应该用〈纠正〉。保障指使人或物保持安全、不遭破坏，改正口音要说纠正。"}, {"text": "他保障了这项纪录。", "explanation": "这里应该用〈保持〉。保障指使人或物保持安全、不遭破坏；纪录要说保持，不能说保障。"}, {"text": "她保障了自己的看法。", "explanation": "这里应该用〈表达〉。保障指使人或物不遭破坏，看法要说表达。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '30f22364-fbff-41e5-b603-90028fed7570') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (22656, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "这个新的门禁系统了保障宿舍的安全。", "corrected_sentence": "这个新的门禁系统保障宿舍的安全。", "error_description": "“了”误放在动词“保障”前。“了”不能放在动词前，应删去，说“保障宿舍的安全”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '30f22364-fbff-41e5-b603-90028fed7570') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (22656, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "社区门口有人轮班值守，周密的保障了小区的安全。", "corrected_sentence": "社区门口有人轮班值守，周密地保障了小区的安全。", "error_description": "“周密的保障了”误用“的”。“周密”修饰动词“保障”时是状语，应用“地”，应说“周密地保障了小区的安全”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '30f22364-fbff-41e5-b603-90028fed7570') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
