INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (22660, 1, 'llm_types_B', '{}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '0e155ee9-b460-47eb-b88b-f47b46a1a6c3') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (22660, 1, 'prompt1_core', '{"pos": "动词", "semantic_class": "action", "definition": "别人叫你做什么，你就去做。", "primary_collocate": null, "pronunciation": "xiǎng yìng", "ipa": "ɕiɑŋ˨˩˦ iŋ˥˩", "syllable_count": 2, "sentences": [{"text": "全班同学都响应了老师的号召。", "target_word": "响应", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "很多市民响应政府的号召，少用塑料袋。", "target_word": "响应", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "我们要响应环保号召，出门坐地铁。", "target_word": "响应", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "学校号召大家捐书，同学们都积极响应。", "target_word": "响应", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他第一个响应了队长的号召。", "target_word": "响应", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "公司发出通知后，没有几个人响应。", "target_word": "响应", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "社区号召大家打扫公园，很多邻居马上响应。", "target_word": "响应", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "社区号召大家节约用电，可是响应的人不多。", "target_word": "响应", "complexity_tier": "T3", "furigana": "xiǎng yìng", "sentence_source": "generated"}, {"text": "为了响应节约用水的号召，我家装了新水龙头。", "target_word": "响应", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "我愿意响应你的倡议，明天一起去植树。", "target_word": "响应", "complexity_tier": "T3", "furigana": "xiǎng yìng", "sentence_source": "generated"}], "morphological_forms": [{"form": "响应了", "label": "体标"}, {"form": "响应过", "label": "体标"}], "register": "中性", "sense_fingerprint": "听到号召或呼吁后照着去做", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '90865500-d708-484f-b474-f4f4acd19e44') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (22660, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "响应", "is_correct": true, "explanation": "正确。“响应了老师的号召”指照着号召去做，与句意相合。"}, {"text": "唱", "is_correct": false, "explanation": "语义：“唱”不能用来指照着号召去做，“都唱了老师的号召”读起来不通。"}, {"text": "煮", "is_correct": false, "explanation": "语义：“煮”指加热食物，与“号召”无关，句子不通。"}, {"text": "修理", "is_correct": false, "explanation": "搭配：“修理”的对象应是器物，不能与“号召”搭配。"}], "explanations": {"响应": "正确。“响应了老师的号召”指照着号召去做，与句意相合。", "唱": "语义：“唱”不能用来指照着号召去做，“都唱了老师的号召”读起来不通。", "煮": "语义：“煮”指加热食物，与“号召”无关，句子不通。", "修理": "搭配：“修理”的对象应是器物，不能与“号召”搭配。"}, "sentence_index": 0, "correct_answer": "响应"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "开车要响应交通规则。", "explanation": "这里应该用〈遵守〉。“遵守”用于规则、制度，“响应”用于号召、倡议，不用于交通规则。"}, {"text": "我们要响应公共秩序。", "explanation": "这里应该用〈维护〉。“维护”用于秩序、利益，“响应”用于号召、倡议，不用于秩序。"}, {"text": "他很快响应了这门语言。", "explanation": "这里应该用〈掌握〉。“掌握”用于语言、技术、知识，“响应”用于号召、倡议，不用于语言。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '0e155ee9-b460-47eb-b88b-f47b46a1a6c3') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (22660, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "响应", "is_correct": true, "explanation": "正确。“很多邻居马上响应”指邻居照着号召马上去做，与句意相合。"}, {"text": "睡觉", "is_correct": false, "explanation": "语义：“睡觉”与打扫公园的号召无关，“马上睡觉”读起来不合语境。"}, {"text": "下雨", "is_correct": false, "explanation": "语义：“下雨”不是人能按号召采取的行动，句子不通。"}, {"text": "冻结", "is_correct": false, "explanation": "搭配：“冻结”不用于描述邻居的行动，“邻居马上冻结”不能这样搭配。"}], "explanations": {"响应": "正确。“很多邻居马上响应”指邻居照着号召马上去做，与句意相合。", "睡觉": "语义：“睡觉”与打扫公园的号召无关，“马上睡觉”读起来不合语境。", "下雨": "语义：“下雨”不是人能按号召采取的行动，句子不通。", "冻结": "搭配：“冻结”不用于描述邻居的行动，“邻居马上冻结”不能这样搭配。"}, "sentence_index": 6, "correct_answer": "响应"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "他很快响应了这次考试。", "explanation": "这里应该用〈参加〉。“参加”用于考试、活动，“响应”用于号召、倡议，不用于考试。"}, {"text": "这道数学题很难，他响应了半天。", "explanation": "这里应该用〈解答〉。“解答”用于解决问题、习题，“响应”不能用于题目。"}, {"text": "面对网友的批评，他很快响应了错误。", "explanation": "这里应该用〈承认〉。“承认”用于承认错误、事实，“响应”不能用于错误。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '0e155ee9-b460-47eb-b88b-f47b46a1a6c3') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (22660, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "居民们很快响应了了号召。", "corrected_sentence": "居民们很快响应了号召。", "error_description": "错误：“响应了了”。动态助词“了”只用一个，正确为“响应了号召”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '0e155ee9-b460-47eb-b88b-f47b46a1a6c3') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (22660, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "我们没有响应掉大家的倡议。", "corrected_sentence": "我们没有响应大家的倡议。", "error_description": "错误：“响应掉”。“响应”后不能接结果补语“掉”，应去掉“掉”，说“没有响应大家的倡议”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '0e155ee9-b460-47eb-b88b-f47b46a1a6c3') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (22662, 1, 'llm_types_A', '{}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '345aac53-d378-411e-8585-f8029ab75f18') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (22662, 1, 'llm_types_B', '{}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '345aac53-d378-411e-8585-f8029ab75f18') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (22662, 1, 'prompt1_core', '{"pos": "名词", "semantic_class": "concrete", "definition": "地球上的人们把一天分成不同的时间，每个地方用同一个钟表时间的地方叫时区。", "primary_collocate": null, "pronunciation": "shí qū", "ipa": "ʂɻ̩³⁵ tɕʰy⁵⁵", "syllable_count": 2, "sentences": [{"text": "我家和奶奶家不在一个时区。", "target_word": "时区", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "每个时区的钟表时间都不一样。", "target_word": "时区", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "去国外前，我查了那里的时区。", "target_word": "时区", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "手机会自动换成新的时区。", "target_word": "时区", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "同一个时区的人，用同样的钟表时间。", "target_word": "时区", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "地球分成很多时区，所以各地时间不同。", "target_word": "时区", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "你在哪个时区工作？", "target_word": "时区", "complexity_tier": "T1", "sentence_source": "generated"}, {"text": "他飞到另一个时区，白天变成了晚上。", "target_word": "时区", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "请把电脑的时区改成北京。", "target_word": "时区", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "时区不同，所以我们不能同时吃饭。", "target_word": "时区", "complexity_tier": "T2", "sentence_source": "generated"}], "morphological_forms": [{"form": "个", "label": "量词"}], "register": "中性", "sense_fingerprint": "使用同一个钟表时间的地方", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '269c24e7-3516-4df9-a5a0-d403936721b3') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (22662, 1, 'prompt2_exercises_A', '{"level_1": {"options": [{"text": "时区", "is_correct": true, "explanation": "正确：时区指地球上使用相同钟表时间的地方。"}, {"text": "市区", "is_correct": false, "explanation": "shì（第四声）与 shí（第二声）声调不同，意思是市区，即城市内部的区域。"}, {"text": "时期", "is_correct": false, "explanation": "qī 与 qū 的韵母不同（ī 与 ū），意思是时期，即一段时间。"}, {"text": "失去", "is_correct": false, "explanation": "shī（第一声）与 shí（第二声）、qù（第四声）与 qū（第一声）声调都不同，意思是失去。"}, {"text": "时局", "is_correct": false, "explanation": "jú（第二声）与 qū（第一声）声母与声调不同，意思是时局，即当时的局势。"}], "explanations": {"时区": "正确：时区指地球上使用相同钟表时间的地方。", "市区": "shì（第四声）与 shí（第二声）声调不同，意思是市区，即城市内部的区域。", "时期": "qī 与 qū 的韵母不同（ī 与 ū），意思是时期，即一段时间。", "失去": "shī（第一声）与 shí（第二声）、qù（第四声）与 qū（第一声）声调都不同，意思是失去。", "时局": "jú（第二声）与 qū（第一声）声母与声调不同，意思是时局，即当时的局势。"}, "sentence_index": null, "correct_answer": "时区"}, "level_3": {"options": [{"text": "时区", "is_correct": true, "explanation": "正确：“不在一个时区”指两地用的钟表时间不同。"}, {"text": "颜色", "is_correct": false, "explanation": "语义：“颜色”不能划分两个地方的位置关系，“不在一个颜色”说不通。"}, {"text": "乐器", "is_correct": false, "explanation": "语义：“乐器”不是地点或范围，不能说“不在一个乐器”。"}, {"text": "歌曲", "is_correct": false, "explanation": "搭配：“不在一个……”后接地点或范围，“歌曲”不能这样用。"}], "explanations": {"时区": "正确：“不在一个时区”指两地用的钟表时间不同。", "颜色": "语义：“颜色”不能划分两个地方的位置关系，“不在一个颜色”说不通。", "乐器": "语义：“乐器”不是地点或范围，不能说“不在一个乐器”。", "歌曲": "搭配：“不在一个……”后接地点或范围，“歌曲”不能这样用。"}, "sentence_index": 0, "correct_answer": "时区"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "我家和奶奶家的时区是三个小时。", "explanation": "这里应该用〈时差〉。时差指两地时间相差的小时数，时区不能表示相差几小时。"}, {"text": "客厅的时区停了。", "explanation": "这里应该用〈挂钟〉。挂钟会走会停，时区是地区的划分，不会停。"}, {"text": "手机会自动换成一只新的时区。", "explanation": "这里应该用〈个〉。时区是抽象的区域概念，量词用“个”，不用“只”。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '345aac53-d378-411e-8585-f8029ab75f18') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (22662, 1, 'prompt2_exercises_B', '{"level_1": {"options": [{"text": "时区", "is_correct": true, "explanation": "正确：时区指地球上使用相同钟表时间的地方。"}, {"text": "社区", "is_correct": false, "explanation": "shè（第四声）与 shí（第二声）的韵母与声调都不同，意思是社区，即居民聚居的地区。"}, {"text": "石器", "is_correct": false, "explanation": "qì（第四声）与 qū（第一声）的韵母与声调不同，意思是石器，即石头制成的工具。"}, {"text": "食具", "is_correct": false, "explanation": "shí 相同，jù（第四声）与 qū（第一声）声母与声调不同，意思是食具，即饮食用具。"}, {"text": "识趣", "is_correct": false, "explanation": "shí 相同，qù（第四声）与 qū（第一声）只有声调不同，意思是识趣，即懂得分寸。"}], "explanations": {"时区": "正确：时区指地球上使用相同钟表时间的地方。", "社区": "shè（第四声）与 shí（第二声）的韵母与声调都不同，意思是社区，即居民聚居的地区。", "石器": "qì（第四声）与 qū（第一声）的韵母与声调不同，意思是石器，即石头制成的工具。", "食具": "shí 相同，jù（第四声）与 qū（第一声）声母与声调不同，意思是食具，即饮食用具。", "识趣": "shí 相同，qù（第四声）与 qū（第一声）只有声调不同，意思是识趣，即懂得分寸。"}, "sentence_index": null, "correct_answer": "时区"}, "level_3": {"options": [{"text": "时区", "is_correct": true, "explanation": "正确：“哪个时区”询问工作所在的时区，符合句子语境。"}, {"text": "味道", "is_correct": false, "explanation": "语义：“味道”不能指工作的地方，“哪个味道”说不通。"}, {"text": "音乐", "is_correct": false, "explanation": "搭配：“哪个”之后接地点或单位，“音乐”不能这样用。"}, {"text": "字体", "is_correct": false, "explanation": "语义：“字体”是文字的样式，不能指工作的地方，句子不通。"}], "explanations": {"时区": "正确：“哪个时区”询问工作所在的时区，符合句子语境。", "味道": "语义：“味道”不能指工作的地方，“哪个味道”说不通。", "音乐": "搭配：“哪个”之后接地点或单位，“音乐”不能这样用。", "字体": "语义：“字体”是文字的样式，不能指工作的地方，句子不通。"}, "sentence_index": 6, "correct_answer": "时区"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "会议的时区定在下午三点。", "explanation": "这里应该用〈时刻〉。时刻指具体的时间点，可以定在下午三点；时区是地区划分，不能定在某个钟点。"}, {"text": "我们吃饭的时区定在晚上七点。", "explanation": "这里应该用〈时间〉。吃饭的时间可以定在晚上七点，时区不是钟点，不能这样说。"}, {"text": "这个时区很短。", "explanation": "这里应该用〈时段〉。时段指一段时间，可以很短；时区是地区划分，不能用“很短”形容。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '345aac53-d378-411e-8585-f8029ab75f18') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (22662, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "这次旅行跨过了两只时区。", "corrected_sentence": "这次旅行跨过了两个时区。", "error_description": "量词错误：时区应使用量词“个”，不能用“只”。正确说法是“跨过了两个时区”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '345aac53-d378-411e-8585-f8029ab75f18') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (22662, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "我每次坐飞机都要先调只时区。", "corrected_sentence": "我每次坐飞机都要先调时区。", "error_description": "量词错误：时区是抽象的区域概念，前面不能用量词“只”。正确说法是“先调时区”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '345aac53-d378-411e-8585-f8029ab75f18') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
