INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (22664, 1, 'llm_types_B', '{}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '345aac53-d378-411e-8585-f8029ab75f18') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (22664, 1, 'prompt1_core', '{"pos": "形容词", "semantic_class": "property", "definition": "一个东西有两个，或者一个事有两个方面。", "primary_collocate": null, "pronunciation": "shuāng chóng", "ipa": "ʂwɑŋ˥ ʈʂʰʊŋ˧˥", "syllable_count": 2, "sentences": [{"text": "这件事具有双重性质，好坏很难分。", "target_word": "双重", "complexity_tier": "T3", "furigana": "zhè jiàn shì jù yǒu shuāng chóng xìng zhì, hǎo huài hěn nán fēn.", "sentence_source": "generated"}, {"text": "他的笑容有双重意思，我猜不到。", "target_word": "双重", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这套方案有双重好处，既省钱又省时间。", "target_word": "双重", "complexity_tier": "T3", "furigana": "zhè tào fāng àn yǒu shuāng chóng hǎo chu, jì shěng qián yòu shěng shíjiān.", "sentence_source": "generated"}, {"text": "这个任务有双重目的，一是学习，二是赚钱。", "target_word": "双重", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "她过着双重生活，白天上班，晚上写书。", "target_word": "双重", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这把剪刀有双重功能，既能剪纸又能开瓶。", "target_word": "双重", "complexity_tier": "T3", "furigana": "zhè bǎ jiǎn dāo yǒu shuāng chóng gōng néng, jì néng jiǎn zhǐ yòu néng kāi píng.", "sentence_source": "generated"}, {"text": "老师对我的要求是双重的。", "target_word": "双重", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他的话有双重意义，大家都明白。", "target_word": "双重", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这座桥有双重作用，既能过车又能过人。", "target_word": "双重", "complexity_tier": "T3", "furigana": "zhè zuò qiáo yǒu shuāng chóng zuò yòng, jì néng guò chē yòu néng guò rén.", "sentence_source": "generated"}, {"text": "这次旅行有双重收获，既长见识又交了朋友。", "target_word": "双重", "complexity_tier": "T3", "furigana": "zhè cì lǚ xíng yǒu shuāng chóng shōu huò, jì zhǎng jiàn shi yòu jiāo le péng you.", "sentence_source": "generated"}], "morphological_forms": [{"form": "雙重", "label": "繁体"}], "register": "中性", "sense_fingerprint": "一个东西有两层，或一件事有两个方面、两种用途", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '269c24e7-3516-4df9-a5a0-d403936721b3') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (22664, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "双重", "is_correct": true, "explanation": "正确：“双重性质”指事物兼有两个方面的性质，所以好坏很难分。"}, {"text": "甜美", "is_correct": false, "explanation": "搭配：“甜美”多修饰声音、笑容，不修饰“性质”。"}, {"text": "圆形", "is_correct": false, "explanation": "语义：“圆形”指形状，不能说明事情的性质。"}, {"text": "冷清", "is_correct": false, "explanation": "搭配：“冷清”描述场所或气氛，不修饰“性质”。"}], "explanations": {"双重": "正确：“双重性质”指事物兼有两个方面的性质，所以好坏很难分。", "甜美": "搭配：“甜美”多修饰声音、笑容，不修饰“性质”。", "圆形": "语义：“圆形”指形状，不能说明事情的性质。", "冷清": "搭配：“冷清”描述场所或气氛，不修饰“性质”。"}, "sentence_index": 0, "correct_answer": "双重"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "这场双重比赛很精彩。", "explanation": "这里应该用〈双打〉。双打指两人一组的比赛，如网球双打；双重表示两层或两个方面，不能指比赛形式。"}, {"text": "他们是双重兄弟。", "explanation": "这里应该用〈双胞胎〉。双胞胎指同时出生的两个人；双重不能指人。"}, {"text": "她每次都买双重的菜。", "explanation": "这里应该用〈双份〉。双份指两份，表示分量加倍；双重表示两层或两个方面，不能表示份量。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '345aac53-d378-411e-8585-f8029ab75f18') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (22664, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "双重", "is_correct": true, "explanation": "正确：“双重的要求”指要求包含两个方面。"}, {"text": "绿色", "is_correct": false, "explanation": "体貌：“绿色”描述外观颜色，不能形容“要求”。"}, {"text": "清脆", "is_correct": false, "explanation": "搭配：“清脆”多修饰声音，不修饰“要求”。"}, {"text": "方形", "is_correct": false, "explanation": "语义：“方形”指形状，不能说明要求的性质。"}], "explanations": {"双重": "正确：“双重的要求”指要求包含两个方面。", "绿色": "体貌：“绿色”描述外观颜色，不能形容“要求”。", "清脆": "搭配：“清脆”多修饰声音，不修饰“要求”。", "方形": "语义：“方形”指形状，不能说明要求的性质。"}, "sentence_index": 6, "correct_answer": "双重"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "双重的朋友都来了。", "explanation": "这里应该用〈双方〉。双方指两个人或两个团体；双重指两层或两个方面，不能指代人，也不能作主语。"}, {"text": "他一个人吃了双重的米饭。", "explanation": "这里应该用〈双倍〉。双倍指数量加倍；双重表示两层或两个方面，不能表示分量翻倍。"}, {"text": "她用双重的手接住了杯子。", "explanation": "这里应该用〈双手〉。双手指两只手，是名词；双重不能指手。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '345aac53-d378-411e-8585-f8029ab75f18') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (22664, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "这次活动有很双重意义，既能娱乐又能学习。", "corrected_sentence": "这次活动有双重意义，既能娱乐又能学习。", "error_description": "程度错误：“双重”表示两层或两个方面，是非等级形容词，不能受“很”修饰。正确说法是“双重意义”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '345aac53-d378-411e-8585-f8029ab75f18') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (22664, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "这个房间有双重了用途，白天学习，晚上睡觉。", "corrected_sentence": "这个房间有双重用途，白天学习，晚上睡觉。", "error_description": "语法错误：“了”插在“双重”和“用途”之间，应说“双重用途”，不能说“双重了用途”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '345aac53-d378-411e-8585-f8029ab75f18') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
