INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (22666, 1, 'prompt1_core', '{"pos": "名词", "semantic_class": "abstract", "definition": "地球上的地方和样子。", "primary_collocate": null, "pronunciation": "dì lǐ", "ipa": "ti˥˩ li˨˩˦", "syllable_count": 2, "sentences": [{"text": "这里的地理很特别，三面都是山。", "target_word": "地理", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "他对这一带的地理很熟，从不会迷路。", "target_word": "地理", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "老司机知道各地的地理和天气。", "target_word": "地理", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "这个岛的地理很简单，只有一座山。", "target_word": "地理", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "不同国家的地理不一样，生活也不同。", "target_word": "地理", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "这本书写的是中国的地理。", "target_word": "地理", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "从地图上可以看出这个国家的地理。", "target_word": "地理", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他走遍了全国，所以很熟悉各地的地理。", "target_word": "地理", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "导游先给大家介绍了这座城市的地理。", "target_word": "地理", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "爷爷说，他年轻时就熟悉这一带的地理。", "target_word": "地理", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "地理位置", "label": "复合"}, {"form": "地理环境", "label": "复合"}], "register": "通用", "sense_fingerprint": "某地的山水地形等地理情况", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'bcd5bd62-667b-408b-99e4-5d930ae38128') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (22666, 1, 'prompt2_exercises_A', '{"level_1": {"options": [{"text": "地理", "is_correct": true, "explanation": "正确：地理（dì lǐ），指地球上的地方和样子。"}, {"text": "地利", "is_correct": false, "explanation": "lì（第四声）与 lǐ（第三声）只有声调不同，意思是地理上的有利条件。"}, {"text": "地质", "is_correct": false, "explanation": "zhì（第四声）与 lǐ（第三声）声母与声调都不同，意思是地层的构造和组成。"}, {"text": "地力", "is_correct": false, "explanation": "lì（第四声）与 lǐ（第三声）只有声调不同，意思是土地的肥力。"}, {"text": "地址", "is_correct": false, "explanation": "zhǐ（第三声）与 lǐ（第三声）只有声母不同（zh 与 l），意思是住址或所在的位置。"}], "explanations": {"地理": "正确：地理（dì lǐ），指地球上的地方和样子。", "地利": "lì（第四声）与 lǐ（第三声）只有声调不同，意思是地理上的有利条件。", "地质": "zhì（第四声）与 lǐ（第三声）声母与声调都不同，意思是地层的构造和组成。", "地力": "lì（第四声）与 lǐ（第三声）只有声调不同，意思是土地的肥力。", "地址": "zhǐ（第三声）与 lǐ（第三声）只有声母不同（zh 与 l），意思是住址或所在的位置。"}, "sentence_index": null, "correct_answer": "地理"}, "level_3": {"options": [{"text": "地理", "is_correct": true, "explanation": "正确：“地理”指地球上的地方和样子，与“三面都是山”的描写相符。"}, {"text": "价格", "is_correct": false, "explanation": "语义：“价格”指买卖的钱数，与“三面都是山”讲的地形不搭。"}, {"text": "脾气", "is_correct": false, "explanation": "搭配：“脾气”多用于人，不说“这里的脾气”。"}, {"text": "工资", "is_correct": false, "explanation": "语义：“工资”指劳动报酬，与“三面都是山”的描写无关。"}], "explanations": {"地理": "正确：“地理”指地球上的地方和样子，与“三面都是山”的描写相符。", "价格": "语义：“价格”指买卖的钱数，与“三面都是山”讲的地形不搭。", "脾气": "搭配：“脾气”多用于人，不说“这里的脾气”。", "工资": "语义：“工资”指劳动报酬，与“三面都是山”的描写无关。"}, "sentence_index": 0, "correct_answer": "地理"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "这个城市的地理很干净，空气也好。", "explanation": "这里应该用〈环境〉。地理指地形地貌等自然状况，不能说干净；描写卫生和空气要用环境。"}, {"text": "明天的地理很好，适合出门。", "explanation": "这里应该用〈天气〉。地理指地形地貌等自然状况的总体情况，不指某一天的晴雨冷暖；说天气好坏要用天气。"}, {"text": "会议的地理在二楼。", "explanation": "这里应该用〈地点〉。地理是泛指地形地貌的名词，不能指会议的具体场所；说在某处要用地点。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '92090941-8504-467c-8bd8-eb8dff2db2c7') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (22666, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "地理", "is_correct": true, "explanation": "正确：“地理”指国家的地形地貌，可以从地图上看出。"}, {"text": "学费", "is_correct": false, "explanation": "语义：“学费”指上学交的钱，地图上看不出。"}, {"text": "身高", "is_correct": false, "explanation": "体貌：“身高”指人的身体高矮，不能用来说一个国家。"}, {"text": "作业", "is_correct": false, "explanation": "语义：“作业”指学生的课后练习，与地图和国家无关。"}], "explanations": {"地理": "正确：“地理”指国家的地形地貌，可以从地图上看出。", "学费": "语义：“学费”指上学交的钱，地图上看不出。", "身高": "体貌：“身高”指人的身体高矮，不能用来说一个国家。", "作业": "语义：“作业”指学生的课后练习，与地图和国家无关。"}, "sentence_index": 6, "correct_answer": "地理"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "这一带的地理很重，一头牛都拉不动。", "explanation": "这里应该用〈重量〉。“地理”指地形地貌，不能用来形容轻重。"}, {"text": "这一带的地理很热情，见了外地人都打招呼。", "explanation": "这里应该用〈居民〉。“地理”指地形地貌，不能形容性格，“热情”说的是人。"}, {"text": "这一带的地理很少，只有几十户。", "explanation": "这里应该用〈人口〉。地理指地形地貌，不能用来说户数多少；说人数要用人口。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '92090941-8504-467c-8bd8-eb8dff2db2c7') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (22666, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "这个小镇的地理位子很好，交通方便。", "corrected_sentence": "这个小镇的地理位置很好，交通方便。", "error_description": "用词错误：“地理位置”是固定的复合词，末尾是“置”，不能写成“位子”。“位子”指座位或职位，不能与“地理”组合。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '92090941-8504-467c-8bd8-eb8dff2db2c7') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (22666, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "我们正在调查这一带得地理。", "corrected_sentence": "我们正在调查这一带的地理。", "error_description": "用词错误：“这一带的地理”中修饰语的标记应为“的”，写成“得”错误。“得”作补语的标记，用在动词或形容词后，这里应使用“的”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '92090941-8504-467c-8bd8-eb8dff2db2c7') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
