INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (22688, 1, 'prompt1_core', '{"pos": "动词", "semantic_class": "action", "definition": "对别人说的话或问题做出回答。", "primary_collocate": null, "pronunciation": "huí fù", "ipa": "xweɪ̯˧˥ fu˥˩", "syllable_count": 2, "sentences": [{"text": "老师问了一个问题，我不知道怎么回复。", "target_word": "回复", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他说的话让我很难回复。", "target_word": "回复", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "面对朋友的批评，她只是笑着回复了一句。", "target_word": "回复", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "记者的问题很多，他一一回复了。", "target_word": "回复", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "妈妈在微信上问我想吃什么，我回复说都可以。", "target_word": "回复", "complexity_tier": "T3", "furigana": "Māma zài wēixìn shàng wèn wǒ xiǎng chī shénme, wǒ huífù shuō dōu kěyǐ.", "sentence_source": "generated"}, {"text": "对这个问题，你准备怎么回复他？", "target_word": "回复", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "她的问题太突然了，我一时没法回复。", "target_word": "回复", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他认真地回复了每一位同学的提问。", "target_word": "回复", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "大家都在等你回复这个建议。", "target_word": "回复", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他在微信上邀请我，我马上回复说好。", "target_word": "回复", "complexity_tier": "T3", "furigana": "Tā zài wēixìn shàng yāoqǐng wǒ, wǒ mǎshàng huífù shuō hǎo.", "sentence_source": "generated"}], "morphological_forms": [{"form": "回复了", "label": "体标（了）"}, {"form": "回复过", "label": "体标（过）"}, {"form": "回覆", "label": "繁体"}], "register": "中性", "sense_fingerprint": "对别人说的话或提问作出回答", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'dcaf70f6-1c60-4940-ade5-b030778acacc') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (22688, 1, 'prompt2_exercises_A', '{"level_1": {"options": [{"text": "回复", "is_correct": true, "explanation": "正确答案：回复 huí fù，指对别人的话或问题作出回答。"}, {"text": "回府", "is_correct": false, "explanation": "fǔ（第三声）与 fù（第四声）声调不同，意思是回到住所。"}, {"text": "回顾", "is_correct": false, "explanation": "gù 与 fù 声母不同（g 与 f），意思是回头看、回想。"}, {"text": "回护", "is_correct": false, "explanation": "hù 与 fù 声母不同（h 与 f），意思是袒护、包庇。"}, {"text": "回路", "is_correct": false, "explanation": "lù 与 fù 声母不同（l 与 f），意思是电路或往返的路线。"}, {"text": "汇付", "is_correct": false, "explanation": "huì（第四声）与 huí（第二声）声调不同，意思是汇款付款。"}], "explanations": {"回复": "正确答案：回复 huí fù，指对别人的话或问题作出回答。", "回府": "fǔ（第三声）与 fù（第四声）声调不同，意思是回到住所。", "回顾": "gù 与 fù 声母不同（g 与 f），意思是回头看、回想。", "回护": "hù 与 fù 声母不同（h 与 f），意思是袒护、包庇。", "回路": "lù 与 fù 声母不同（l 与 f），意思是电路或往返的路线。", "汇付": "huì（第四声）与 huí（第二声）声调不同，意思是汇款付款。"}, "sentence_index": null, "correct_answer": "回复"}, "level_3": {"options": [{"text": "回复", "is_correct": true, "explanation": "正确：“不知道怎么回复”指不知道如何答复老师的问题，与句中的提问相符。"}, {"text": "拍照", "is_correct": false, "explanation": "语义：拍照与老师的提问无关，句意不通。"}, {"text": "点赞", "is_correct": false, "explanation": "搭配：“点赞”用于动态、帖子，不能用来回应一个问题。"}, {"text": "演唱", "is_correct": false, "explanation": "语义：演唱与老师的提问没有联系，前后句意不通。"}], "explanations": {"回复": "正确：“不知道怎么回复”指不知道如何答复老师的问题，与句中的提问相符。", "拍照": "语义：拍照与老师的提问无关，句意不通。", "点赞": "搭配：“点赞”用于动态、帖子，不能用来回应一个问题。", "演唱": "语义：演唱与老师的提问没有联系，前后句意不通。"}, "sentence_index": 0, "correct_answer": "回复"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "他被对方推了一把，立刻回复了一掌。", "explanation": "这里应该用〈回击〉。回复指答复，对推打的还击要用回击。"}, {"text": "他用微笑回复了我的帮助。", "explanation": "这里应该用〈回报〉。回复指答复，报答别人的帮助要用回报。"}, {"text": "朋友送了我礼物，我也回复了一份。", "explanation": "这里应该用〈回礼〉。回复指答复，回送礼物要用回礼。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'a5cc93b5-3c52-41c1-8841-7642119eb5f8') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (22688, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "回复", "is_correct": true, "explanation": "正确：前句说问题太突然，“一时没法回复”正是指无法立即答复。"}, {"text": "跳舞", "is_correct": false, "explanation": "语义：跳舞与她突然提出的问题无关，句意不通。"}, {"text": "播放", "is_correct": false, "explanation": "搭配：“播放”的对象是视频、音乐，不能用于问题。"}, {"text": "刷牙", "is_correct": false, "explanation": "语义：刷牙与问题毫无关系，句意不通。"}], "explanations": {"回复": "正确：前句说问题太突然，“一时没法回复”正是指无法立即答复。", "跳舞": "语义：跳舞与她突然提出的问题无关，句意不通。", "播放": "搭配：“播放”的对象是视频、音乐，不能用于问题。", "刷牙": "语义：刷牙与问题毫无关系，句意不通。"}, "sentence_index": 6, "correct_answer": "回复"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "这顿饭的味道，我至今还在回复。", "explanation": "这里应该用〈回味〉。回复指答复，回想、品味过去的经历要用回味。"}, {"text": "这些旧报纸要回复利用。", "explanation": "这里应该用〈回收〉。回复指答复，把废品重新利用要用回收。"}, {"text": "他伤愈后终于回复了赛场。", "explanation": "这里应该用〈回归〉。回复不表示重新回到某处，运动员重返赛场要用回归。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'a5cc93b5-3c52-41c1-8841-7642119eb5f8') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (22688, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "我还没回复了老师的问题呢。", "corrected_sentence": "我还没回复老师的问题呢。", "error_description": "“没”字句中不能与“了”同用，“还没”后的动词应直接说“回复”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'a5cc93b5-3c52-41c1-8841-7642119eb5f8') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (22688, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "老师已经回复了了我的问题。", "corrected_sentence": "老师已经回复了我的问题。", "error_description": "“了”重复：“回复了”后只需一个“了”，不能在“回复了”后再加一个“了”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'a5cc93b5-3c52-41c1-8841-7642119eb5f8') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
