INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (22690, 1, 'prompt1_core', '{"pos": "名词", "semantic_class": "property", "definition": "反思就是自己想想自己做得好不好，反思性就是喜欢这样想的特点。", "primary_collocate": null, "pronunciation": "fǎn sī xìng", "ipa": "fan²¹⁴ sz̩⁵⁵ ɕiŋ⁵¹", "syllable_count": 3, "sentences": [{"text": "他很有反思性，每天晚上都想想自己做得好不好。", "target_word": "反思性", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "小林的反思性很强，考试后会先找自己的问题。", "target_word": "反思性", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "有反思性的人，做错事以后不会怪别人。", "target_word": "反思性", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这个孩子越来越有反思性了，会自己说错在哪里。", "target_word": "反思性", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "经理说，我们需要有反思性的新同事。", "target_word": "反思性", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "她的反思性让她每次都比上次做得更好。", "target_word": "反思性", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "写日记可以提高你的反思性。", "target_word": "反思性", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他没有反思性，总是觉得错的是别人。", "target_word": "反思性", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "比赛输了，教练夸他有反思性，没有找借口。", "target_word": "反思性", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "反思性强的学生，成绩常常进步得很快。", "target_word": "反思性", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "反思性思维", "label": "复合"}, {"form": "反思性实践", "label": "复合"}], "register": "中性", "sense_fingerprint": "喜欢想想自己做得好不好的特点", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '879a0741-3d13-4cd5-a933-7197b357419d') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
